/* The Contents of Investigation I: six parts, thirty laws, approved 5 November 2026.
   Each law names the figure its Transgression opens on. Everyone else appears inside the law.
   The Judgment, the three era stamps and the Key line drop in as each entry is written
   (judgment, eras, key below); the reader shows them as soon as they are filled. */
import type { Part } from "./types";

export const PASS_LINE = "One Series Pass opens every part as it is released.";

export const PARTS: Part[] = [
  {
    n: 1, title: "The Crown and the State", opens: "17 Dec 2026",
    line: "How the powerful collide with the one power larger than them all.",
    laws: [
      {
        n: 1, title: "Never Make the State Your Rival", opener: "Jack Ma", place: "Shanghai, 2020",
        judgment: "However large you grow, the state can grow larger in a single afternoon. Make it your partner, never your audience.",
        eras: ["Paris, 1307", "Moscow, 2003", "Shanghai, 2020"],
        story: "On 24 October 2020, Jack Ma stood before China's most senior financial officials in Shanghai and told them their banks still had a pawnshop mentality. Ten days later the largest stock listing the world had ever seen, his Ant Group's, was stopped two days before it opened. Then the most celebrated businessman in China vanished from public view for almost three months. He had broken no law. He had made the state look small, in public, in its own house.",
        key: "Seeking: grow inside the state's interest, and let its officials take the credit. Keeping: the larger you become, the quieter you must speak.",
        sections: [
          { name: "The Law", text: "Never make the state your rival. Not in public, not in private, not in a joke. Every company, church, gang and movement stands on ground the state can take back, and the state does not need to be right to take it. On Friday, 13 October 1307, before dawn, the officers of Philip IV of France opened sealed orders in every town of the kingdom and arrested the Knights Templar, the richest order in Christendom, its bankers, its lenders, its knights. The king owed them money. Within five years Pope Clement V dissolved the order. On 18 March 1314 its last Grand Master, Jacques de Molay, was burned alive on an island in the Seine. The Templars had broken no law the king could not invent. Their crime was being a power the crown could not command, holding money the crown needed. The law is older than any of us: grow as large as you like, but never so large, so loud or so independent that the state must prove it is still the master." },
          { name: "Judgment", text: "However large you grow, the state can grow larger in a single afternoon. It writes the rules, it holds the courts, it prints the money and it decides what counts as a crime. On 30 June 2021 the Chinese ride-hailing giant Didi raised $4.4 billion on the New York Stock Exchange, against the quiet wishes of its own regulators. Two days later, on 2 July, the Cyberspace Administration of China opened a security review. Two days after that, Didi's app was ordered off every app store in China. Within a year Didi announced it would leave the New York exchange altogether. No court case, no trial, no warning. Make the state your partner, never your audience. The moment it feels like your audience, it stops being your partner." },
          { name: "Transgression", text: "Shanghai, Saturday 24 October 2020. Jack Ma, the former English teacher who started Alibaba with seventeen friends in his flat in Hangzhou in 1999, walks onto the stage of the Bund Summit. Alibaba's 2014 listing in New York had raised $25 billion, then the largest in history. Now his payments company, Ant Group, is days from raising about $34.5 billion in Shanghai and Hong Kong, a new record, at a value near $313 billion. In the audience sit the men who run China's money, with Vice President Wang Qishan among the speakers. Ma tells them the global banking rules, the Basel Accords, are a club for old men, and that China's banks still have a pawnshop mentality. The speech is reported nationwide within hours. On 2 November Ma is summoned to a joint meeting with four regulators. On 3 November the Shanghai exchange suspends Ant's listing, two days before trading was due to begin. In December regulators open an antitrust investigation into Alibaba. On 10 April 2021 it is fined 18.2 billion yuan, about $2.8 billion, a Chinese record. Ma is not seen in public until a short video for rural teachers on 20 January 2021. In January 2023 Ant announces he has given up control of the company he built." },
          { name: "Observance", text: "Augsburg, 1519. Jakob Fugger, a weaver's grandson, is the richest man in Europe, richer than the kings who borrow from him. When the Holy Roman Emperor Maximilian dies, the princes who choose his successor are for sale. Fugger lends most of the roughly 850,000 florins that buy the election for the nineteen-year-old Charles V. Four years later the emperor has still not repaid him. Fugger does not complain at court or to the crowd. He writes a private, courteous letter reminding Charles that without him the crown could not have been won, and asks only to be paid. He is paid, in mining rights and revenues. He dies in his bed on 30 December 1525, perhaps the richest man who has ever lived. Four centuries later, in November 1907, a run on New York's trust companies threatens to bring down American banking. J. P. Morgan locks the city's bankers inside his library until they agree to put up the money to stop it. He acts, in private rooms, as the state's partner, and leaves the credit to the Treasury. He dies in 1913 rich and untouched. Both men were larger than the rulers of their day in money. Neither ever let a ruler feel it in public." },
          { name: "Interpretation", text: "A state is not a company. It does not compete with you on price or quality. It competes on survival, and it reads public humiliation as an attack on its survival. Jack Ma made an argument any banker might make. His mistake was where he made it, who was listening, and how large he had become when he made it. A small man who criticises the state is a critic. A man whose company is larger than the state's own banks, criticising it from a stage, is a rival. China had spent 2020 warning of financial risk, and Ant lent to hundreds of millions of people with less capital held back than any bank was allowed. The state did not need to win the argument. It needed to show who decides. Ibn Khaldun saw it six centuries earlier: royal power, by its nature, claims all the glory for itself. Whatever seems to share the glory must be brought down, not because it is wrong, but because it is there." },
          { name: "Parallels", text: "Bourges, 1451. Jacques Coeur, the richest merchant in France, lends Charles VII the money to drive the English out of Normandy. In July 1451 he is arrested on charges that include poisoning the king's mistress, which no one seriously believed. His fortune is seized and shared among the courtiers who owed him money. He escapes to Rome and dies in 1456 on the island of Chios, leading a papal fleet. Tokyo, 2006. Takafumi Horie, the young founder of the internet company Livedoor, has spent a year openly defying Japan's business establishment, trying to buy his way into a national broadcaster. On 23 January 2006 prosecutors arrest him for securities fraud. He serves almost two years in prison. Moscow, 2003. On 19 February, on live television, Mikhail Khodorkovsky, the richest man in Russia, accuses officials of corruption to Vladimir Putin's face. On 25 October armed agents board his plane on the runway at Novosibirsk. He spends ten years in prison; his oil company, Yukos, is broken up and its best field is sold to the state. Medellín, 1984 to 1993. Pablo Escobar has his men kill the justice minister, Rodrigo Lara Bonilla, who exposed him, then declares war on the Colombian state to stop his extradition. He bombs, kidnaps and bribes for nine years. On 2 December 1993 the state, with help from abroad, kills him on a Medellín rooftop." },
          { name: "The Cost", text: "For Ma: a listing that would have made Ant one of the most valuable financial companies on earth, gone; the largest antitrust fine in China's history; control of his life's work; and more than half of Alibaba's value, hundreds of billions of dollars, wiped away in the two years after the speech. For the Templars: their order, their wealth and, for de Molay, his life. For Coeur: everything he owned and his country. For Horie: his company, two years and his name. For Khodorkovsky: ten years of his life and the largest oil company in Russia. For Escobar: his life, and those of thousands of Colombians. Notice the scale. The price is never measured by the crime. It is measured by how openly the state was defied." },
          { name: "The Record", text: "Verified: the speech of 24 October 2020 and its words, which were reported in full; the summons of 2 November; the suspension of the listing on 3 November 2020; the fine of 10 April 2021; Ma's reduced control of Ant announced in January 2023. Reported but not confirmed: that President Xi Jinping personally ordered the listing stopped, as The Wall Street Journal reported in November 2020; the Chinese government has never said so. Disputed: whether Ma was held or questioned during his months out of view. No public evidence shows he was detained, and he has never said. Where this book does not know, it says so." },
          { name: "Keys", text: "For those seeking: first, grow inside the state's interest; solve a problem officials care about, and let them stand in the photograph. Second, learn which regulator could close you tomorrow, and know that person's name. Third, never take a public stage in a country whose rules you plan to break. For those keeping: first, the larger you become, the quieter you must speak. Second, raise disagreements in private rooms, through the right people, as Fugger did with a courteous letter, never through the news. Third, when you are larger than the state's own institutions in any one area, assume you are already being watched, and act as its partner before it decides you are its rival." },
          { name: "Image", text: "The tree beside the palace wall. Let it grow tall and give shade, and the king will rest beneath it in summer and boast of it to his guests. Let it grow taller than the wall, so that its branches block the king's view of his own city, and it is cut down in a single morning, however healthy its roots, however sweet its fruit. No one asks the tree what it meant." },
          { name: "Authority", text: "“A tall tree catches the wind.” An old Chinese saying, centuries older than any company in this book. “He who is the cause of another becoming powerful is ruined.” Niccolò Machiavelli, The Prince, 1513, written as if for Jacques Coeur, who made his king strong and was destroyed by him. And Ibn Khaldun, in the Muqaddimah of 1377: royal power, by its nature, claims all the glory for itself." },
          { name: "Reversal", text: "The law bends only when the state itself is dying. In 1351 the Mongol Yuan dynasty in China was rotting from famine, floods and corruption. Rebels rose everywhere, and a former beggar monk named Zhu Yuanzhang defied it openly, fought for sixteen years, and in 1368 made himself the first emperor of the Ming. In August 1980 a shipyard electrician named Lech Wałęsa led a strike in Gdańsk that openly defied Poland's communist state. He was arrested and his union banned, but the state behind it was failing, and in 1990 he was elected president. On 11 February 1990 Nelson Mandela walked out of prison after twenty-seven years, and in 1994 he became president of the country that had jailed him. Each of them defied a state that was already breaking. The reversal is a bet on the state's death. Until it is certainly dying, it remains the largest power in the room." },
        ],
      },
      {
        n: 2, title: "Never Mistake a Title for Power", opener: "Louis XVI", place: "Versailles, 1789",
        judgment: "A title is a promise that other people agree to keep. Power is what they do when you give an order. Confuse the two, and you will find out which one you had on the day it matters.",
        eras: ["Soissons, 751", "Versailles, 1789", "Moscow, 1991"],
        story: "On 23 June 1789 the King of France, Louis XVI, ordered the deputies of the Third Estate to leave their hall at Versailles. They stayed in their seats. Three weeks later the royal French Guards in Paris joined the crowd that stormed the Bastille; that night the king wrote one word in his journal, \"Nothing\". He still had the crown, the palace and the title of the most powerful monarch in Europe. Within four years he had his head cut off in a public square in his own capital.",
        key: "Seeking: before you reach for the title, win the things a title stands on: soldiers, money, information and people who obey. Keeping: test, quietly and often, whether your orders are still carried out.",
        sections: [
          { name: "The Law", text: "Never mistake a title for power. A title is a word; power is the army that marches when you speak, the money that comes when you call, the officials who carry out your order without asking twice. In 1908 a two-year-old boy named Puyi was placed on the Dragon Throne of China. He cried through his own enthronement. In February 1912 the revolution made him abdicate, and for twelve years he was an emperor inside the walls of the Forbidden City and nowhere else. In 1934 Japan crowned him again, as Emperor of Manchukuo, a state that Japanese officers ran from behind his chair. In 1945 the Soviets captured him; after nearly ten years in a Chinese prison he was released to work as a gardener in Beijing, and he died in 1967 an ordinary citizen. Three thrones, three titles, and not one day of real power in his life. A title is not something you have. It is something other people agree, for now, to give you." },
          { name: "Judgment", text: "A title is a promise other people agree to keep. Power is what they do when you give an order. On 4 September 476, a Germanic general named Odoacer walked into Ravenna and deposed Romulus Augustulus, a teenager who held the most famous title in the world: Emperor of the West. Odoacer did not even bother to kill him. He sent him to live on a pension in a villa near Naples and sent the imperial regalia to Constantinople, saying the West no longer needed an emperor. The title had outlived the power behind it by decades. The power had belonged to the generals for a long time; that afternoon, they simply stopped pretending." },
          { name: "Transgression", text: "Versailles, spring 1789. Louis XVI has worn the crown since May 1774, when he was nineteen. France is bankrupt, broken by the cost of the American war, and to raise taxes he summons the Estates-General, an assembly that has not met since 1614. It opens on 5 May. On 17 June the commoners of the Third Estate declare themselves the National Assembly. Locked out of their hall on 20 June, they gather in a royal tennis court and swear not to separate until France has a constitution. On 23 June the king holds a royal session, annuls their decisions and orders them out. They refuse. The Count of Mirabeau, by the account later told, says they will leave only by the force of bayonets. The king's answer is to give in. On 14 July the Bastille falls, and the French Guards, his own soldiers, fight on the crowd's side. In October a crowd of women marches on Versailles and brings the royal family back to Paris as hostages in all but name. In June 1791 Louis tries to escape in disguise and is recognised and stopped at Varennes. On 10 August 1792 the Tuileries palace is stormed. On 21 September the monarchy is abolished. On 21 January 1793, Citizen Louis Capet is guillotined. He held the title of King of France until the last months; the power had left him in the first." },
          { name: "Observance", text: "Rome, 27 BC. After fifteen years of civil war, Octavian is master of the Roman world. He has the legions, the treasury and Egypt's grain. The Senate offers him honours, and he chooses his title with care: not king, a word Romans hated, not dictator, the title that got Julius Caesar stabbed, but princeps, first citizen, and later Augustus. In his own account of his reign he wrote that he excelled others in authority, but held no more official power than his colleagues. It was a modest title sitting on top of total power, and it was the opposite of Louis XVI's mistake. Augustus ruled for forty-one years and died in his bed in AD 14. Nineteen centuries later, Deng Xiaoping did the same in China. From 1978 until the early 1990s he was the most powerful man in the country, yet he never held the top titles of state or party. What he kept for himself was the chairmanship of the commission that commands the army. Titles he handed to others. Power he kept." },
          { name: "Interpretation", text: "Power is a relationship, not an object. It exists only while the people who carry out orders keep carrying them out: the soldier, the tax collector, the clerk, the guard at the gate. A title is the label on that relationship. It can stay on the door long after the room is empty. Louis XVI was not stupid, and not cruel. He simply believed the label was the thing. He kept waiting for his title to work, and each time it did not, he gave a little more ground, and each retreat told everyone watching that the title was empty. Ibn Khaldun saw it in the dynasties of North Africa: royal authority rests on group feeling, on the shared bond of the men who fight for it. When that bond dissolves, the throne is just a chair." },
          { name: "Parallels", text: "Soissons, 751. For a century the Merovingian kings of the Franks had reigned while the Mayors of the Palace ruled; chroniclers called the kings the do-nothings. In 751 the mayor, Pepin the Short, with the Pope's blessing, had the last of them, Childeric III, shorn of his long royal hair and sent to a monastery, and took the crown himself. Kyoto, 1192 to 1867. For almost seven centuries Japan had an emperor who held the highest title in the land and a shogun who held the army; the emperor reigned, the shogun ruled. Cupertino, 1985. Steve Jobs, co-founder of Apple, had personally recruited John Sculley as chief executive in 1983. Two years later, in May 1985, the board backed Sculley and stripped Jobs of his operating role; by September he had resigned from the company that carried his name in every newspaper. Moscow, 1991. After the failed coup of August, Boris Yeltsin held the streets, the Russian government and the army's loyalty. Mikhail Gorbachev still held the title of President of the Soviet Union. On 25 December 1991 he resigned on television, and that evening the red flag over the Kremlin was lowered for the last time." },
          { name: "The Cost", text: "For Louis XVI: his crown, his head, and a monarchy that had lasted, in one form or another, for more than eight hundred years. His wife, Marie Antoinette, followed him to the guillotine on 16 October 1793. His son, Louis-Charles, the boy royalists called Louis XVII, died in a Paris prison on 8 June 1795, aged ten. For Childeric III: his hair, his crown and the rest of his life in a cloister. For Gorbachev: a country of fifteen republics. For Jobs: eleven years outside the company he founded, until Apple, near collapse, bought his new company and brought him back in 1997. The higher the title, the longer the fall when the power has already gone." },
          { name: "The Record", text: "Verified: the dates of the Estates-General, the Tennis Court Oath, the royal session of 23 June, the fall of the Bastille, the flight to Varennes, the storming of the Tuileries and the execution of 21 January 1793, all in the official records of the Revolution. The word \"Rien\" in Louis XVI's journal for 14 July 1789 is genuine. Disputed: what it meant. The journal mostly records his hunting, and many historians read \"nothing\" as \"no game caught\", not as indifference to the Bastille. Disputed: Mirabeau's exact words on 23 June, which survive in several versions written down later. Where the words are uncertain, this book says so." },
          { name: "Keys", text: "For those seeking: first, win what a title stands on before you take the title: the people who carry out orders, the money and the information. Second, prefer a modest title over real power to a grand title over nothing, as Augustus and Deng did. Third, watch the men who guard the doors; they decide more than the man on the throne. For those keeping: first, test quietly and often whether your orders are still carried out as given. Second, never retreat in public on a direct order; each retreat tells everyone the title is hollow. Third, know who commands the soldiers, the money and the records in your house, and make sure their loyalty runs to you, not to the title." },
          { name: "Image", text: "The crown on an empty chair. Courtiers still bow to it as they pass. Guards still stand on either side. Visitors are still told to lower their voices. But the chair is empty, and everyone in the room already knows it. They are only waiting to see who will be the first to stop bowing." },
          { name: "Authority", text: "\"All armed prophets have conquered, and the unarmed ones have been destroyed.\" Niccolò Machiavelli, The Prince, chapter 6, 1513. \"The king reigns, but does not govern.\" Adolphe Thiers, 1830, describing the kind of king France should have, a title without power, chosen on purpose. And Ibn Khaldun, in the Muqaddimah of 1377: royal authority rests on group feeling, and dies when it dies." },
          { name: "Reversal", text: "Madrid, 23 February 1981. Armed civil guards under Lieutenant Colonel Antonio Tejero storm the Spanish parliament and hold the deputies at gunpoint. Tanks roll in Valencia. Spain's young democracy is six years old. That night, after midnight, King Juan Carlos appears on national television in the uniform of captain general of the armed forces and orders the army to obey the constitution. By the next day the coup has collapsed. Here the title was the power, because the officers who mattered still believed in it. That is the reversal: a title works only for as long as those who must obey still believe in it. Juan Carlos spent the trust that night, used it well, and kept it for decades. He spent it again in scandal, and in June 2014 he abdicated." },
        ],
      },
      {
        n: 3, title: "The Law Is Your Wall; Do Not Climb Over It", opener: "Richard Nixon", place: "Watergate, 1972",
        judgment: "The law that binds you is the same law that shields you. Climb over it to strike your enemies, and you leave its protection behind, and they will not need to climb to reach you.",
        eras: ["Rome, 63 BC", "Washington, 1974", "Lima, 2000"],
        story: "In November 1972 Richard Nixon won forty-nine of fifty states, one of the largest landslides in American history. Five months earlier, burglars working for his re-election campaign had been caught inside the Democratic Party's offices at the Watergate building. He did not order the break-in, as far as the record shows. He ordered the cover-up. Every tape of his own voice became evidence. On 9 August 1974 he became the only president in American history to resign.",
        key: "Seeking: win inside the rules, even when breaking them looks faster. Keeping: the higher you rise, the more the law is your shield; never be the first to tear it.",
        sections: [
          { name: "The Law", text: "The law is your wall. It keeps your enemies out as surely as it keeps you in. Rome, 5 December 63 BC. The consul Marcus Tullius Cicero, the greatest lawyer of his age, has uncovered a conspiracy led by the nobleman Catiline. Five of the conspirators are under arrest. Every Roman citizen has the right to appeal to the people before being put to death, but Cicero, with the Senate behind him, has them strangled in the prison that same night, without a trial. He is hailed as father of the fatherland. Five years later, in 58 BC, his enemy Clodius passes a law exiling anyone who has put a citizen to death without trial. Cicero flees Rome; his house on the Palatine is torn down. The law he stepped over to save the Republic was the one used to throw him out of it." },
          { name: "Judgment", text: "The law that binds you is the same law that shields you. Climb over it to strike your enemies, and you leave its protection behind you; they will not need to climb to reach you. In 1977, three years after he resigned, Richard Nixon sat down for televised interviews with the British broadcaster David Frost. Asked whether a president could act illegally, he said: \"Well, when the president does it, that means that it is not illegal.\" It is the clearest statement ever made of the mistake this law is about." },
          { name: "Transgression", text: "Washington, 17 June 1972, a little after two in the morning. A security guard named Frank Wills finds tape over a door lock at the Watergate office building. Police arrest five men inside the headquarters of the Democratic National Committee, carrying cameras and bugging equipment. One of them works for the Committee to Re-elect the President. Six days later, on 23 June, Nixon is recorded in the Oval Office approving a plan to have the CIA tell the FBI to stop investigating, on grounds of national security. That tape will later be called the smoking gun. On 7 November he wins forty-nine states. In 1973 the Senate holds televised hearings. On 16 July, an aide named Alexander Butterfield reveals that Nixon secretly recorded his own conversations. Nixon refuses to hand over the tapes. On 20 October 1973, when the special prosecutor Archibald Cox insists, Nixon orders him fired; the attorney general and his deputy resign rather than do it. The press calls it the Saturday Night Massacre. On 17 November Nixon tells a meeting of newspaper editors, \"I'm not a crook.\" On 24 July 1974 the Supreme Court rules eight to nothing that he must release the tapes. On 5 August the smoking gun is published. On the evening of 8 August he announces his resignation, and at noon on 9 August it takes effect." },
          { name: "Observance", text: "Newburgh, New York, 15 March 1783. The war for independence is won, but Congress has not paid the army, and a group of officers is talking openly of marching on the government. George Washington, their commander, the most popular man in America, could have led them anywhere. He calls the officers together and argues against them. When his speech is not working, he takes out a letter and then, fumbling, a pair of spectacles that few of them had seen him wear, and says he has grown grey in their service and now finds himself growing blind. Officers weep; the movement collapses. In 1797, after two terms as president and with no law to stop him from a third, he goes home to Mount Vernon. King George III is said to have remarked that if Washington gave up power, he would be the greatest man in the world. Washington kept inside the wall when he was strong enough to tear it down, and the wall has protected every president since, including from themselves." },
          { name: "Interpretation", text: "The powerful are tempted to treat the law as a tool that works for them and against their enemies. But the law is a wall, and a wall cannot tell the difference between the people it is keeping out and the people behind it. When the man at the top shows that rules can be ignored, he teaches everyone below him the same lesson, and the first people to use it are usually the people closest to him. Nixon's campaign broke into an office because the people around him believed winning justified anything; they believed it because they had heard him say so. The cover-up was worse than the crime because it turned a burglary by others into a crime by the president himself, recorded in his own voice. The law did not destroy Nixon. Nixon left the law, and then had nothing left to stand behind." },
          { name: "Parallels", text: "Lima, 5 April 1992. President Alberto Fujimori, elected two years earlier, sends tanks to close Congress and the courts, a self-coup. For eight years he rules with the help of his spy chief, Vladimiro Montesinos, who records himself bribing politicians and journalists on video. In September 2000 one of those videos is shown on television. In November, on a trip to Asia, Fujimori faxes his resignation from Tokyo. He is extradited from Chile in 2007 and in 2009 sentenced to twenty-five years. Seoul, 10 March 2017. South Korea's Constitutional Court unanimously removes President Park Geun-hye from office after a scandal in which a private friend, Choi Soon-sil, used their relationship to pull money from the country's largest companies. Park is sentenced to more than twenty years and pardoned in December 2021. Chicago, 17 October 1931. Al Capone, who had bought half the city's police and courts and survived every attempt to charge him with murder, is convicted of tax evasion. He gets eleven years. The law he could not bribe was the one he never thought to respect." },
          { name: "The Cost", text: "For Nixon: the presidency, months after one of the greatest victories in American electoral history, and a name that became a suffix for scandal: every scandal since has been called something-gate. His attorney general, John Mitchell, went to prison, the first attorney general in American history to do so, along with his two closest aides, H. R. Haldeman and John Ehrlichman. Nixon himself was pardoned by his successor, Gerald Ford, on 8 September 1974, which may have cost Ford the 1976 election. For Cicero: exile and his house. For Fujimori: his presidency and his freedom. For Capone: his health and his empire; he left prison sick and never ruled again." },
          { name: "The Record", text: "Verified: the arrests of 17 June 1972; the tape of 23 June 1972, released 5 August 1974; the firing of Archibald Cox on 20 October 1973; the unanimous Supreme Court ruling in United States v. Nixon on 24 July 1974; the resignation of 9 August 1974; the pardon of 8 September 1974. Unresolved: the eighteen and a half minutes erased from a tape of 20 June 1972. Nixon's secretary, Rose Mary Woods, said she may have erased part of it by accident; experts found several separate erasures; who did it has never been proven. Settled in 2005: the identity of the secret source the reporters called Deep Throat, who was Mark Felt, then the second most senior official in the FBI." },
          { name: "Keys", text: "For those seeking: first, win inside the rules, even when breaking them looks faster, because a victory gained outside the law is a debt the law collects later. Second, never let people working for you believe you want them to cross the line for you; they will, and it will be your crime. Third, keep your own records clean; assume that every message you send will one day be read aloud. For those keeping: first, the higher you rise, the more the law becomes your shield; never be the first to tear it. Second, when something goes wrong beneath you, the cover-up is the trap; a mistake confessed early is a story, a mistake hidden is a crime. Third, give up power the way you were given it, by the rules, and the rules will protect you afterwards." },
          { name: "Image", text: "The wall around a castle. The king inside it finds it narrow, and dislikes the gates that close at night and the guards who ask everyone their name, even him. One night he has a section knocked down so that he can ride out to strike an enemy. He wins. But the gap he made is still there in the morning, and that night it is not his men who come through it." },
          { name: "Authority", text: "\"Be you never so high, the law is above you.\" Thomas Fuller, Gnomologia, 1732. \"It is more proper that law should govern than any one of the citizens.\" Aristotle, Politics, Book III. And from Washington's Farewell Address of 1796: the habit of trusting the constitution is worth more than any gain won by breaking it." },
          { name: "Reversal", text: "There is one way to climb over the wall and win: do it in daylight, on purpose, against a law that is itself unjust, and accept the punishment in front of everyone. On 12 March 1930 Mohandas Gandhi set out from his ashram with seventy-eight followers and walked about 240 miles to the sea at Dandi to make salt, which British law forbade Indians to do without paying tax. On 6 April he picked up a lump of salt from the shore. Some sixty thousand Indians were arrested in the months that followed, Gandhi among them. On 1 December 1955, in Montgomery, Alabama, Rosa Parks refused to give up her seat on a bus to a white passenger, and was arrested. Both broke the law openly, hid nothing, and accepted the price. That is the reversal: breaking a bad law in public and paying for it can build more power than any law ever gave. Breaking a fair law in secret, as Nixon did, only spends it." },
        ],
      },
      {
        n: 4, title: "Do Not Outgrow Your Protectors", opener: "Manuel Noriega", place: "Panama, 1989",
        judgment: "The power that raised you can always see how big you have grown. Grow until you could threaten it, and it will deal with you before you decide whether to.",
        eras: ["Rome, AD 31", "Munich, 1934", "Panama, 1989"],
        story: "For two decades Manuel Noriega worked for American intelligence while he rose to rule Panama. He took their money and, by many accounts, the drug cartels' money too. By 1988 he had been indicted in Florida for drug trafficking. In December 1989 his assembly declared Panama to be in a state of war with the United States. Days later, twenty-seven thousand American troops invaded. He hid in the Vatican's embassy while soldiers blasted rock music at the walls, and on 3 January 1990 he walked out and surrendered.",
        key: "Seeking: rise with your protector, never past him; let him always feel he could still replace you. Keeping: when you grow strong enough to threaten the one who raised you, either step back into his shadow or leave his house entirely.",
        sections: [
          { name: "The Law", text: "Do not outgrow your protectors. The hand that lifts you can see exactly how high you have risen. Rome, AD 31. Lucius Aelius Sejanus commands the Praetorian Guard, the soldiers who protect the emperor Tiberius. The emperor has withdrawn to the island of Capri and leaves Rome in Sejanus's hands. Statues of Sejanus go up beside the emperor's; senators bow to him; his birthday is celebrated in public. In 31 he holds the consulship alongside Tiberius himself. On 18 October he walks into the Senate expecting new honours. A long letter from Capri is read aloud. It begins with polite matters, wanders, and ends with an order for his arrest. By evening he has been strangled and his body thrown down the steps into the river. Tiberius had never stopped watching how large his servant had grown." },
          { name: "Judgment", text: "The power that raised you can always see how big you have grown. Grow until you could threaten it, and it will deal with you before you have decided whether to. The protector does not need proof of betrayal. The size of the protected is the proof. That is why outgrowing a protector is fatal even for the loyal: loyalty is a feeling, and size is a fact." },
          { name: "Transgression", text: "Panama, 1950s to 1989. Manuel Antonio Noriega, an officer from a poor family, begins passing information to American intelligence in the 1950s and is on the CIA's payroll for much of the next thirty years. He becomes head of military intelligence in 1970, and in August 1983 commander of the Panama Defence Forces and the real ruler of the country. Washington tolerates him because he is useful in Central America's wars. But he also sells his services to others: to Cuba, to arms dealers and, prosecutors say, to the Medellín cartel, letting cocaine and its money move through Panama. In February 1988 grand juries in Miami and Tampa indict him on drug charges. In May 1989 he annuls an election his candidate has lost; opposition candidates are beaten in the street on camera. On 15 December 1989 Panama's assembly, which he controls, names him maximum leader and declares the country in a state of war with the United States. The next night his soldiers kill an American Marine officer at a roadblock. On 20 December Operation Just Cause begins: about twenty-seven thousand American troops. Noriega runs, and on 24 December takes refuge in the Vatican's diplomatic mission. American troops surround it and play loud rock music day and night. On 3 January 1990 he walks out, in uniform, and surrenders. In April 1992 a Miami jury convicts him on eight counts." },
          { name: "Observance", text: "Beijing, 1949 to 1976. Zhou Enlai is premier of China for twenty-seven years, the man who runs the government while Mao Zedong rules the country. He is brilliant, admired abroad, popular at home, and in many things more capable than his master. He never lets it show. Through the Great Leap Forward and the Cultural Revolution, while Mao destroys almost every other senior colleague, including the head of state Liu Shaoqi and the marshal Peng Dehuai, Zhou survives by making himself indispensable and never visible as a rival. He takes blame, praises Mao in public, and stays a step behind him in every photograph. He dies of cancer in January 1976, still in office, and the outpouring of public grief is so large that the authorities try to suppress it. Three centuries earlier, Cardinal Mazarin ran France for the young Louis XIV and the queen mother, grew enormously rich, and died in office in 1661, in his bed. He served a crown and never let it doubt who wore it." },
          { name: "Interpretation", text: "A protector does not raise you out of kindness. He raises you because you are useful, and because he believes he can always put you down again. The moment that second belief weakens, your usefulness no longer matters. Noriega was useful to Washington for decades. What changed was not that he became less useful; it was that he became independent: indicted in American courts, defiant on American television, declaring war. He had begun to act as if his protector needed him more than he needed his protector. That is the most dangerous belief a protected man can hold, and it is almost always wrong. The protector is the one with the larger army, the larger treasury and the longer memory." },
          { name: "Parallels", text: "Munich, 30 June 1934. Ernst Röhm has built Hitler's brownshirt army, the SA, from a gang of street fighters into a force of around three million men, far larger than Germany's regular army. He talks of a second revolution. Before dawn Hitler himself arrives at the hotel at Bad Wiessee where Röhm is sleeping and has him arrested. Over the next days, in what became known as the Night of the Long Knives, the SS kills Röhm and scores of others. Colombia, 4 February 1987. Carlos Lehder, co-founder of the Medellín cartel, had built a private island in the Bahamas as the cartel's runway, given interviews boasting of his wealth and politics, and grown famous in his own right. Police capture him at a farmhouse near Medellín; he is extradited to the United States the same day. Many in the cartel's world believed Escobar gave him up; it has never been proven. In 1988 Lehder is sentenced to life without parole plus 135 years. Russia, 23 to 24 June 2023. Yevgeny Prigozhin, whose Wagner mercenaries had been built and paid for by the Russian state, seizes the city of Rostov and sends a column toward Moscow, then turns back. Two months later, on 23 August, his private jet falls out of the sky north of Moscow, killing everyone on board." },
          { name: "The Cost", text: "For Noriega: his country, his freedom and the rest of his life. He spent about twenty years in American custody, was then extradited to France and convicted of money laundering, and finally returned to a Panamanian prison, where he served time for the murder of political opponents. He died on 29 May 2017. For Panama: an invasion in which, by official American count, a few hundred Panamanian soldiers and civilians died; human rights groups put the civilian toll much higher. For Sejanus: his life, and then his children's lives. For Röhm: his life and his army. For Prigozhin: his life two months after his march." },
          { name: "The Record", text: "Verified: the indictments of February 1988; the annulled election of May 1989; the declaration of 15 December 1989; the invasion of 20 December; the surrender of 3 January 1990; the conviction of April 1992. Verified from the trial: Noriega had received payments from American intelligence over many years. Disputed: how much. Figures from tens of thousands of dollars a year to more than ten million in total have been cited by different sides, and the full records have never been released. Disputed: the number of Panamanians killed in the invasion. Not proven: that the crash of Prigozhin's plane was ordered by the Kremlin, which denies it; the investigation's findings have not been made public." },
          { name: "Keys", text: "For those seeking: first, rise with your protector, never past him; let him always feel he could still replace you. Second, keep your own fame smaller than your usefulness; a famous servant is a rival in the making. Third, never sell to your protector's enemies; the day it is found out, all your past usefulness is erased. For those keeping: first, if you have become strong enough to threaten the one who raised you, you have two choices only: step back into his shadow, or leave his house and stand on your own. Staying, large and independent, is the one choice that is always fatal. Second, never declare the break before you have the strength to survive it. Third, remember that the protector's patience is not forgiveness; it is timing." },
          { name: "Image", text: "The lion cub raised in the palace. It sleeps at the foot of the king's bed and eats from his hand, and the court laughs at how tame it is. Each year it grows. One morning the king looks at it and sees not a pet but a lion, with the same teeth it has always had. It has done nothing wrong. It has only grown. That afternoon it is in a cage, or worse." },
          { name: "Authority", text: "\"He who is the cause of another becoming powerful is ruined.\" Machiavelli, The Prince, 1513: and the man made powerful knows it, which is why the protector strikes first. From Aesop's fables, more than two thousand years old: the frog who saw an ox and puffed himself up to match it, puffed again and again, and burst. And from Tacitus, who wrote the story of Sejanus a century later: the closer a man stands to the emperor's favour, the shorter the fall." },
          { name: "Reversal", text: "There is one way to outgrow a protector and live: do it suddenly, completely and before he moves. On 9 November 1799, the eighteenth of the revolutionary month of Brumaire, General Napoleon Bonaparte, whom the five Directors running France had raised to command and thought they could control, overthrows them in a single day and makes himself First Consul. On 16 July 1979 Saddam Hussein, for years the deputy and protégé of Iraq's president Ahmed Hassan al-Bakr, forces him to resign and takes his place, then purges the party on camera. Both outgrew their protectors and won, but only because they struck first and left nothing standing. Halfway is death. Noriega lived halfway for years: too big to obey, never big enough to win." },
        ],
      },
      {
        n: 5, title: "What You Buy Can Be Sold Back", opener: "Miguel Ángel Félix Gallardo", place: "Guadalajara, 1989",
        judgment: "Loyalty that is bought belongs to the highest bidder, and the highest bidder is rarely you on the day you need it most.",
        eras: ["Rome, AD 193", "Guadalajara, 1989", "Kyiv, 2014"],
        story: "Miguel Ángel Félix Gallardo, a former state police officer from Sinaloa, built the Guadalajara cartel into the main gateway for cocaine into the United States, and he bought the protection that made it possible: police chiefs, commanders, officials. In April 1989 a federal police commander arrested him in Guadalajara; by Félix's own account, the commander had once been a friend. The protection he paid for had changed hands. He has spent more than thirty years in custody.",
        key: "Seeking: pay people well, but build loyalty that money alone did not create, because what money bought, more money can buy back. Keeping: know who else could outbid you for the people who protect you, and assume one day someone will.",
        sections: [
          { name: "The Law", text: "What you buy can be sold back. Rome, 28 March AD 193. The soldiers of the Praetorian Guard, the emperor's own protectors, murder the emperor Pertinax, who has tried to impose discipline and cut their pay. Then they do something unheard of: they offer the empire for sale. Two rich senators bid against each other at the gates of the Guard's camp. Didius Julianus wins, promising each soldier 25,000 sesterces. The Senate confirms him. The people of Rome jeer him in the street. Within weeks three generals in the provinces declare themselves emperor. When one of them, Septimius Severus, marches on Rome, the Guard Julianus bought does not fight for him. On 1 June 193, sixty-six days after the auction, a soldier kills him in the palace. What he bought had been bought before, and it was sold again." },
          { name: "Judgment", text: "Loyalty that is bought belongs to the highest bidder, and the highest bidder is rarely you on the day you need it most. On that day, the man who wants you gone is offering more than you can, and offering it to the same people. Money is the cheapest way to get loyalty and the most expensive way to keep it, because you must keep paying more than everyone who would like to take your place, forever." },
          { name: "Transgression", text: "Sinaloa and Guadalajara, 1960s to 1989. Miguel Ángel Félix Gallardo begins as a state police officer in Sinaloa and serves as a bodyguard to the state's governor, Leopoldo Sánchez Celis, which gives him introductions to the men who matter. By the late 1970s he is organising the trade: marijuana and heroin, then cocaine from the Colombian cartels, flown into Mexico and moved across the border. He moves his base to Guadalajara, buys houses, hotels and bank accounts, and buys protection: local police, state commanders, federal agents, officials in the capital. In February 1985 men of his circle kidnap and murder an American agent, Enrique Camarena, and the United States turns its full weight on Mexico. The protection holds for four more years. Then, on 8 April 1989, the federal police commander Guillermo González Calderoni leads the team that arrests Félix in Guadalajara. By Félix's own later account, written from prison, the commander had once been close to him. Félix was sentenced to decades in prison. From his cell, by his own account, he divided the routes he had run among the younger men who would found the cartels of Tijuana, Juárez and Sinaloa." },
          { name: "Observance", text: "Italy, 218 to 203 BC. The Carthaginian general Hannibal crosses the Alps with an army of Africans, Spaniards, Gauls and others: mercenaries and allies who share no language, no gods and no country. For sixteen years he keeps them together in enemy territory, often unpaid and short of food, cut off from home. The Greek historian Polybius, writing a few decades later, marvelled that in all those years there was never a mutiny against him. Hannibal had paid them, but he had not only paid them. He ate what they ate, slept on the ground among them, and won them battles that made them rich and proud, as at Cannae in 216 BC. Their loyalty was bought once and earned every day after. Money got them to Italy. Something money could not buy kept them there." },
          { name: "Interpretation", text: "When you buy loyalty, you are not buying a person; you are renting a decision. The person makes the same decision again every day: is staying with you still the best price on offer? While you are strong, rich and rising, the answer is easy. The moment you weaken, two things happen at once: your ability to pay falls, and your enemies' willingness to pay for the people around you rises. Félix bought officials because it was faster than anything else. But the officials he bought were also for sale to the state, to rivals and to the Americans, and when the price of protecting him became higher than the price of arresting him, they changed sides. They did not betray him. They completed the transaction." },
          { name: "Parallels", text: "Carthage, 241 to 237 BC. After losing the First Punic War, Carthage cannot pay the mercenaries who fought for it. They revolt, besiege the city that hired them and are crushed only after more than three years of a war so savage that Polybius called it the most cruel he knew of. Mexico, 14 January 1996. Juan García Ábrego, head of the Gulf cartel and the first drug trafficker ever placed on the FBI's Ten Most Wanted list, had been protected for years by officials he paid. A year earlier, in February 1995, Raúl Salinas, brother of the former president, had been arrested in Mexico. Now García Ábrego is arrested near Monterrey and flown to Houston within a day. He is sentenced to eleven life terms. Kyiv, 21 to 22 February 2014. After months of protest, the riot police and the paid street gangs who had protected President Viktor Yanukovych melt away from the government quarter. That night he flees the capital, and the next day parliament votes him out of office. The men he had paid to stand between him and the crowd simply went home." },
          { name: "The Cost", text: "For Félix Gallardo: his freedom since April 1989, more than three decades of it, and the empire he built, split among the younger men who became its heirs and then each other's enemies; the wars between their cartels have killed tens of thousands of Mexicans since. For Didius Julianus: his life, after sixty-six days. For Carthage: years of war against its own hired army. For Yanukovych: his country, his palace and the rest of his career, lived in exile in Russia. Every one of them paid twice: once to buy the loyalty, and once, far more, when it was sold back." },
          { name: "The Record", text: "Verified: Félix Gallardo's arrest in Guadalajara on 8 April 1989, and that the operation was led by Guillermo González Calderoni; his conviction on drug, kidnapping and related charges. Verified: the arrest of Juan García Ábrego in January 1996 and his conviction in Houston. Disputed: Félix's own account of how far his protection went and of the meeting at which, he says, he divided the routes, which comes mainly from writings he produced in prison and published through journalists. Disputed: the details of Camarena's murder and who ordered it, which have been argued in courts in two countries for decades. González Calderoni himself was later accused of corruption, fled to the United States, and was shot dead in Texas in 2003; the killing was never solved." },
          { name: "Keys", text: "For those seeking: first, pay people well, but give them something money did not give them: a share in winning, a name, a future with you that a rival cannot offer. Second, never rely on one bought protector; whoever controls your protection controls you. Third, assume every official you buy is also for sale to your enemies. For those keeping: first, know who else could outbid you for the people around you, and watch them. Second, the moment your money weakens, the people you bought are already being approached; strengthen what you built on loyalty, not what you built on payment. Third, the safest guards are the ones who would lose everything if you fell." },
          { name: "Image", text: "A coat bought from a stranger in the market. It fits well. It is warm. It is the best coat you have ever had. One day you see a man across the market looking at it, and the stranger is standing beside him, pointing at you. You realise you never asked who owned the coat before you, or how many times it has been sold." },
          { name: "Authority", text: "\"Mercenaries and auxiliaries are useless and dangerous.\" Machiavelli, The Prince, chapter 12, 1513. And in chapter 17: friendships that are won by payment, and not by greatness of mind, may be bought, but they cannot be relied on, and in time of need they cannot be spent. Polybius, on Hannibal's army in Italy: in sixteen years, not one mutiny." },
          { name: "Reversal", text: "Paris, 10 August 1792. As the crowd storms the Tuileries palace, King Louis XVI and his family flee to the National Assembly. Behind them, about nine hundred Swiss Guards, foreign soldiers paid by the French crown, hold the palace. They are ordered to cease fire and many are cut down as they try to obey; around six hundred die that day or soon after. They were bought soldiers, and they died for a king who was already gone. In Lucerne, a stone lion was carved in their memory in 1821. That is the reversal: bought loyalty can hold, but only when it is tied to something deeper than the pay: a code of honour, a home to return to, the shame of breaking a word. Where bought men have nothing but the money, the money is all you have." },
        ],
      },
    ],
  },
  {
    n: 2, title: "The Court", opens: "Jan 2027",
    line: "The flatterers, favourites and keepers of secrets who stand closest to the throne.",
    laws: [
      {
        n: 6, title: "Punish the Messenger and You Will Rule Blind", opener: "Saddam Hussein", place: "Baghdad, 2003",
        judgment: "Every ruler is told the truth exactly as often as the truth is safe to tell. Punish one messenger, and every messenger after him will bring you what you want to hear, until the day the enemy arrives in person.",
        eras: ["Armenia, 69 BC", "Moscow, 1941", "Baghdad, 2003"],
        story: "By 2003 Saddam Hussein had ruled Iraq for twenty-four years, and for most of them the men around him had learned what happened to anyone who brought bad news. His generals told him his army was ready. On 7 April 2003 his information minister told the world there were no American troops in Baghdad while American tanks could be seen behind him. Two days later the city fell. Eight months later Saddam was pulled out of a hole in the ground near his home town.",
        key: "Seeking: become the one person who tells the powerful the truth gently and usefully, and you become rare. Keeping: reward the first bearer of bad news in public, so that the second one comes to you sooner.",
        sections: [
          { name: "The Law", text: "Punish the messenger and you will rule blind. Armenia, 69 BC. Tigranes the Great, who calls himself King of Kings, rules an empire from the Caspian to Syria. The Roman general Lucullus marches against him. According to Plutarch, the first man who comes to tell Tigranes that Lucullus is approaching has his head cut off for spreading panic. After that, no one tells him anything. While the war comes closer every day, the king sits in ignorance, surrounded by men who assure him that Lucullus would not dare. When Lucullus's army appears before Tigranes's new capital, Tigranocerta, the king's vast army is routed in a single afternoon on 6 October 69 BC. Plutarch's lesson is precise: Tigranes did not lose because he had no information. He lost because he had taught everyone around him not to give it." },
          { name: "Judgment", text: "Every ruler hears the truth exactly as often as the truth is safe to tell. Moscow, 17 June 1941. Joseph Stalin receives a report from one of his own intelligence officers: a source inside the German air ministry says the attack on the Soviet Union is ready and can come at any moment. Stalin scrawls across it, in obscene language, that this is not a source but a spreader of disinformation. Dozens of such warnings had reached him for months, from spies, diplomats and even Winston Churchill. Officers who pressed them had learned to stop. Five days later, at dawn on 22 June, more than three million German and allied soldiers cross the border. In the first days the Soviet air force loses thousands of planes, many still on the ground." },
          { name: "Transgression", text: "Iraq, 1979 to 2003. Saddam Hussein takes the presidency in July 1979, and within days he has a meeting of the ruling party filmed as he reads out the names of men accused of treason; they are led from the room, and many are executed. The lesson is not lost on anyone. Over the next two decades his commanders learn to report victories, his ministers to report plans fulfilled. After his fall, American researchers interviewed his senior officers and read his own captured records; their 2006 study, the Iraqi Perspectives Project, found a ruler who believed his army was far stronger than it was, because the men under him were afraid to tell him otherwise. Saddam expected that the Americans, if they came at all, would not come all the way to Baghdad. On 20 March 2003 the invasion begins. On 7 April his information minister, Muhammad Saeed al-Sahhaf, assures television cameras there are no American soldiers in Baghdad; American tanks are visible across the river behind him. On 9 April the city falls, and his statue in Firdos Square is pulled down on live television. On 22 July his sons Uday and Qusay are killed in a gun battle in Mosul. On 13 December American soldiers pull Saddam from a narrow hole at a farm near Tikrit. He is hanged on 30 December 2006." },
          { name: "Observance", text: "Washington, March 1861. Abraham Lincoln, a one-term congressman from the frontier, becomes president and does something no one expects: he fills his cabinet with the men who ran against him for the nomination, William Seward, Salmon Chase and Edward Bates, all of whom think they would be the better president and say so. He wanted, he explained, the strongest men in the country around him, and men who would tell him he was wrong. Through four years of civil war they argued with him constantly, and he kept them. A century later at General Motors, its chairman Alfred Sloan is said to have closed a meeting with these words: \"I take it we are all in complete agreement on the decision here. Then I propose we postpone further discussion until our next meeting, to give ourselves time to develop disagreement.\" Both men understood that a room where everyone agrees is a room where someone is afraid." },
          { name: "Interpretation", text: "No one sets out to punish the truth. A ruler punishes a messenger because the news makes him angry, or afraid, or ashamed in front of others. But everyone watching learns the same lesson, and they learn it permanently. From that day on, every report passes through a filter in the mind of the person writing it: what will happen to me if I say this? Bad news is softened, then delayed, then never sent. The ruler does not notice, because what he now hears is pleasant. He believes he is better informed than ever. In reality he is surrounded by a wall of fear built from his own reactions, and he sees through it only when the enemy walks through it. Machiavelli put the cure in one sentence: there is no way to guard yourself against flatterers except to let people know that telling you the truth does not offend you." },
          { name: "Parallels", text: "Pripyat, 26 April 1986. Reactor Number Four at the Chernobyl nuclear plant explodes. The night-shift managers, afraid of their superiors, report that the reactor is intact and the radiation low; the instruments they use can read no higher than a fraction of the real level. The nearby town of Pripyat, with about forty-nine thousand people, is not evacuated until the afternoon of the next day. Moscow tells its own people nothing for days, and the world learns of the disaster only when radiation sets off alarms at a nuclear plant in Sweden. Gorbachev later wrote that Chernobyl was perhaps the real cause of the Soviet Union's collapse. Palo Alto, 2015. Tyler Shultz, a young employee at the blood-testing company Theranos, and grandson of a former Secretary of State who sat on its board, warns that its tests do not work. The company's founder, Elizabeth Holmes, has lawyers pursue him; he is followed, and his family spends hundreds of thousands of dollars defending him. Reporters prove him right. In 2022 Holmes is convicted of fraud and sentenced to more than eleven years in prison." },
          { name: "The Cost", text: "For Saddam: his country, his two sons, killed in Mosul, and his life, on a gallows on 30 December 2006. For Iraq: a war and its aftermath in which hundreds of thousands of people died, by the most careful estimates. For Tigranes: his capital and his empire; he ended his reign as a client king of Rome. For Stalin's Soviet Union: catastrophic losses in the first months of the war, millions of soldiers killed or captured. For Theranos: the company, once valued at about nine billion dollars, dissolved in 2018. The cost of a punished messenger is never paid by the messenger alone." },
          { name: "The Record", text: "Verified: the filmed party meeting of 22 July 1979; the start of the invasion on 20 March 2003; al-Sahhaf's broadcast claims and the fall of Baghdad on 9 April; the deaths of Uday and Qusay on 22 July 2003; Saddam's capture on 13 December 2003 and execution on 30 December 2006. Verified: the findings of the Iraqi Perspectives Project, published by the United States Joint Forces Command in 2006. Verified: Stalin's note on the report of 17 June 1941, now published from Soviet archives. Disputed: the often-told story that in 1982 Saddam had his health minister shot during a cabinet meeting for suggesting he step aside temporarily to make peace with Iran. The minister was executed, but the accounts of how and why come from defectors and differ. Disputed: the number of Iraqi dead, which different studies put at very different levels." },
          { name: "Keys", text: "For those seeking: first, become the person who tells the powerful the truth gently, early and with a way forward; such people are rare and are remembered. Second, never deliver bad news in front of an audience; let the powerful hear it alone, where pride does not have to defend itself. Third, bring the evidence with the news. For those keeping: first, reward the first bearer of bad news in public, so that the next one comes to you sooner. Second, build more than one road for information to reach you, so no single filter can blind you. Third, watch your own face: if people leave your office relieved, ask what they did not say." },
          { name: "Image", text: "The king's mirror that only smiles. It was once an ordinary mirror. Each time it showed him something he did not like, he had a servant whipped, and so the servants learned to polish it differently. Now, whatever his face does, the mirror shows him handsome and calm. He looks into it every morning before he rides out, and he is the last man in the kingdom to see that he is bleeding." },
          { name: "Authority", text: "\"There is no other way of guarding oneself from flatterers except letting men understand that to tell you the truth does not offend you.\" Machiavelli, The Prince, chapter 23, 1513. Plutarch, on Tigranes, about a hundred years after Christ: the first messenger lost his head, and after that the king heard nothing. And an old saying at many courts: the king's anger kills the messenger, and the king's ignorance kills the king." },
          { name: "Reversal", text: "There is a difference between hiding bad news from the crowd and hiding it from yourself. In the summer of 1940, with France fallen and Britain alone, Winston Churchill gave the British people defiance in public: we shall fight on the beaches, we shall never surrender. In private he demanded the worst numbers available, and in 1941 he set up a central statistics office so that the true figures reached him in plain form, without anyone softening them. He kept morale high and his own eyes open. That is the reversal: a leader may control what the crowd hears in a crisis, but never what he himself is told. Punish the panic-monger who spreads fear in the streets if you must; never punish the officer who brings the truth to your desk." },
        ],
      },
      {
        n: 7, title: "Beware the Favourite Who Owns Your Ear", opener: "Nicholas II and Rasputin", place: "St Petersburg, 1916",
        judgment: "A favourite costs you twice: once in what he does with your trust, and once in what everyone else concludes about your judgment for giving it to him.",
        eras: ["Warwick, 1312", "Aranjuez, 1808", "St Petersburg, 1916"],
        story: "Grigori Rasputin, a wandering peasant holy man from Siberia, seemed to be the only person who could ease the bleeding of the tsar's son, who had haemophilia. The empress came to trust him completely, and when Nicholas II left for the front in 1915, ministers rose and fell on Rasputin's word. In December 1916 a group of nobles murdered him and threw his body into a frozen river. It was too late. Within three months the tsar had lost his throne, and within two years he and his family were shot in a cellar.",
        key: "Seeking: if you become a ruler's favourite, spend the favour on his interests, never on yours, and keep away from the jobs you are not fit for. Keeping: let favourites share your table, never your seal.",
        sections: [
          { name: "The Law", text: "Beware the favourite who owns your ear. England, 1307. The new king, Edward II, makes his closest friend, Piers Gaveston, the son of a minor knight, Earl of Cornwall, a title kept for the royal family. He gives him lands, jewels and a place at his side above the greatest lords of England; at the coronation feast Gaveston is dressed more splendidly than the king. The barons force him into exile twice, and twice Edward brings him back. In June 1312 they capture him, and on 19 June he is run through and beheaded on Blacklow Hill near Warwick. Edward learns nothing. Within a few years he has new favourites, the Despensers, father and son, who grow even greedier. In January 1327 Edward is forced to give up his crown, and that September he dies, almost certainly murdered, at Berkeley Castle." },
          { name: "Judgment", text: "A favourite costs you twice: once in what he does with your trust, and once in what everyone else concludes about your judgment for giving it to him. Portsmouth, 23 August 1628. George Villiers, Duke of Buckingham, the handsome favourite of King James I and then of his son Charles I, has led England into failed wars with Spain and France. Parliament has tried to impeach him; Charles has dissolved Parliament to save him. That morning a discontented officer named John Felton walks into an inn and stabs him in the chest. Crowds in London drink to Felton's health. The king's loyalty to his favourite had already cost him the trust of his Parliament, a quarrel that ended, twenty-one years later, with Charles's own head on a block." },
          { name: "Transgression", text: "St Petersburg, 1905 to 1917. Grigori Rasputin, a peasant wanderer from Siberia with a reputation for healing, is introduced to Tsar Nicholas II and Empress Alexandra in November 1905. Their only son, Alexei, has haemophilia; the smallest injury can make him bleed for days. Rasputin, again and again, seems to calm the boy when doctors cannot; in 1912, when Alexei is near death at Spała, a telegram from Rasputin is followed by his recovery. To Alexandra he becomes a man sent by God. To everyone else he is a drunken, debauched peasant who has the ear of the throne. In August 1915, with the war against Germany going badly, Nicholas takes personal command of the army and leaves for headquarters at Mogilev, hundreds of miles away, leaving the government in his wife's hands, and through her in Rasputin's. Ministers are appointed and dismissed so fast that it is called ministerial leapfrog; Russia has four prime ministers in 1916 alone. Rumour says Rasputin and the German-born empress are working for Germany. On the night of 16 to 17 December 1916, by the Russian calendar of the time, Prince Felix Yusupov and others lure him to the Yusupov Palace, shoot him and throw his body into the frozen Malaya Nevka river. Ten weeks later revolution breaks out in Petrograd. On 2 March 1917 Nicholas abdicates. On 17 July 1918 he, his wife and their five children are shot in a cellar in Yekaterinburg." },
          { name: "Observance", text: "Paris, 9 March 1661. Cardinal Mazarin, who has ruled France for the young Louis XIV for eighteen years, dies. The court waits to see who the new chief minister will be. The next morning the twenty-two-year-old king calls in his ministers and tells them that from now on he will be his own first minister; they are to report to him, and nothing is to be signed without his order. For fifty-four years he keeps that rule. He has favourites for pleasure and mistresses for love, but no favourite ever holds his seal. Across the Channel, a century earlier, Elizabeth I had done the same in her own way: she adored Robert Dudley and later the Earl of Essex, but for policy she relied on William Cecil, a careful, plain man she trusted for forty years. When Essex, the favourite, mistook her affection for power and led an armed rising in London in February 1601, she signed his death warrant. He was beheaded on 25 February." },
          { name: "Interpretation", text: "A ruler chooses a favourite for the reasons any person chooses a friend: comfort, charm, loyalty, the feeling of being understood. Those are not the reasons anyone should be given power. The trouble begins when the two are confused, when a man is promoted because the ruler likes him rather than because he can do the job. The favourite is rarely capable of the office, and he knows his only protection is the ruler's affection, so he spends his time guarding that affection: isolating the ruler, discrediting rivals, rewarding his own friends. Everyone else sees it, and draws a conclusion not about the favourite, but about the ruler. Machiavelli wrote that the first judgment people make of a prince comes from looking at the men he keeps around him. The favourite is the ruler's own portrait, painted for the whole court to see." },
          { name: "Parallels", text: "Aranjuez, 17 to 19 March 1808. Manuel Godoy, a young guardsman who became the favourite of Queen Maria Luisa of Spain and then chief minister to King Charles IV, has allowed French troops into Spain under a treaty with Napoleon. A crowd led by soldiers and nobles storms his palace at Aranjuez; he is found two days later hiding in a rolled-up carpet in his attic. Charles IV abdicates to save him, and within weeks Napoleon has taken the whole Spanish royal family into France and given Spain to his brother. Istanbul, 15 March 1536. Ibrahim Pasha, a former slave who grew up as the boyhood companion of Sultan Suleiman the Magnificent and became his grand vizier, has signed himself \"Sultan\" in documents and lived more grandly than his master. He dines with Suleiman in the palace and is strangled in his sleep that night on the sultan's orders. Buenos Aires, 1973 to 1976. José López Rega, a former police corporal and occultist the press called the Sorcerer, becomes the confidant of Juan Perón and his wife Isabel, and after Perón's death in July 1974 runs much of the government through her. He founds the death squad known as the Triple A. In July 1975, amid strikes and riots, he is forced to flee the country. On 24 March 1976 the army overthrows Isabel Perón." },
          { name: "The Cost", text: "For Nicholas II: the throne of a dynasty that had ruled Russia for 304 years, since 1613, and the lives of his wife and all five of his children, the youngest a boy of thirteen. For Russia: revolution, civil war, and seven decades of a system that would kill millions. For Edward II: his crown and his life. For Charles I, who saved Buckingham: the trust of his Parliament, and in 1649 his head. For Charles IV of Spain: his throne and his country. A favourite rarely falls alone; he takes his master's judgment with him, and often his master." },
          { name: "The Record", text: "Verified: Rasputin's introduction to the imperial family in November 1905; Nicholas II's assumption of command in August 1915; the four prime ministers of 1916; the murder at the Yusupov Palace on the night of 16 to 17 December 1916 by the old Russian calendar, which is 29 to 30 December by the modern one; the abdication of 2 March 1917, or 15 March by the modern calendar; the killing of the family on 17 July 1918, confirmed by DNA tests on remains found near Yekaterinburg. Disputed: the famous story that Rasputin survived poisoned cakes and wine, and several bullets, before he drowned. It comes mainly from Yusupov's own memoirs. The autopsy found gunshot wounds, including a fatal shot to the forehead, and no trace of poison. Disputed: how much real political influence Rasputin had, as opposed to how much people believed he had; for the throne, the belief did the damage." },
          { name: "Keys", text: "For those seeking: first, if you become a ruler's favourite, spend the favour on his interests, never on yours; the court is counting. Second, refuse the office you are not fit for, however it is offered, because the failure will be blamed on both of you. Third, never let your splendour outshine the one who gave it. For those keeping: first, let favourites share your table, never your seal; separate those you enjoy from those you rely on. Second, when everyone around you hates the same man, ask why before you defend him. Third, never leave the capital and leave a favourite to rule in your place." },
          { name: "Image", text: "The whisper in the king's ear, painted on the wall of the throne room. The court has looked at it so long that no one notices it any more. Only visitors from outside stop and stare, and what they stare at is not the man whispering, but the king, leaning in to listen." },
          { name: "Authority", text: "\"The first opinion which one forms of a prince, and of his understanding, is by observing the men he has around him.\" Machiavelli, The Prince, chapter 22, 1513. And from the court of Louis XIV, the king's own words to his ministers in March 1661, as reported: from now on, I will be my own first minister." },
          { name: "Reversal", text: "A favourite can save a throne, if he is chosen for ability and the king keeps the power. Paris, 11 November 1630, the Day of the Dupes. Louis XIII's own mother, Marie de' Medici, demands that he dismiss his chief minister, Cardinal Richelieu. For a few hours the whole court believes she has won; courtiers rush to congratulate her. That evening the king summons Richelieu and confirms him in power, and the queen mother's party is ruined. Richelieu, ruthless and brilliant, made France the strongest state in Europe; he was hated, but he was accountable to a king who used him and never feared him. That is the reversal: the danger is not having a trusted man close to you. It is having one chosen by your heart instead of your head, and answering to no one." },
        ],
      },
      {
        n: 8, title: "Loyalty You Buy Leaves With the Money", opener: "Mobutu Sese Seko", place: "Kinshasa, 1997",
        judgment: "A system held together by payments is only as strong as the next payment. When the money runs short, it does not weaken slowly. It dissolves, all at once, from the bottom up.",
        eras: ["Antwerp, 1576", "Kinshasa, 1997", "Kabul, 2021"],
        story: "For thirty-two years Mobutu Sese Seko ruled Zaire by paying everyone who mattered: generals, ministers, chiefs and foreign friends, while the country's wealth flowed into his palaces. When the money ran out, he told his soldiers, in effect, to pay themselves; they looted the capital. In 1997 a rebel army marched across the country almost without a fight. On 16 May Mobutu flew out of Kinshasa. Four months later he died in exile in Morocco.",
        key: "Seeking: pay well, but tie people to a future they share with you, not only to a salary. Keeping: never let the payroll depend on your own survival; the day it does, your people start calculating.",
        sections: [
          { name: "The Law", text: "Loyalty you buy leaves with the money. Antwerp, 4 November 1576. Spain is the richest power on earth, but in 1575 King Philip II has declared bankruptcy, and his army in the Netherlands has not been paid for months. The soldiers mutiny. On 4 November they fall on Antwerp, the richest trading city in northern Europe, which they are supposed to be protecting. For three days they burn, rob and kill; around seven thousand people die, and the city's wealth is carried off. It becomes known as the Spanish Fury. Within days, the provinces of the Netherlands sign a pact to drive the Spanish troops out. The army that was meant to hold the Netherlands for the king helped lose it, because the only thing that held it to the king was the pay." },
          { name: "Judgment", text: "A system held together by payments is only as strong as the next payment. When money runs short, it does not weaken slowly; it dissolves, all at once, from the bottom up. Istanbul, 1826. For centuries the Janissaries, the Ottoman sultans' elite infantry, had been the empire's pride. By the nineteenth century they are a privileged, paid caste that topples sultans who threaten their pay; they had deposed or killed several. On 15 June 1826 they revolt again, overturning their soup cauldrons in the old sign of mutiny. This time Sultan Mahmud II is ready. Loyal artillery fires on their barracks; thousands are killed, and the corps is abolished. Mahmud had understood what his ancestors had not: a corps loyal only to its privileges will always, in the end, turn on the throne that pays it." },
          { name: "Transgression", text: "Congo, 24 November 1965 to 16 May 1997. Joseph-Désiré Mobutu, army chief of staff, takes power in a coup. In 1971 he renames the country Zaire, and himself Mobutu Sese Seko. His system is simple: the state's wealth, its copper, cobalt and diamonds, flows to the top and is handed down as favours. Ministers are rotated so none grows a power base; generals are paid to stay loyal; foreign governments are paid in contracts and in his support against communism. He builds a palace in his home village of Gbadolite that the press calls the Versailles of the jungle, and charters Concorde for shopping trips to Paris. The joke in Kinshasa is that the constitution has an unwritten Article 15: fend for yourselves. By the 1990s, the copper price has collapsed and the treasury is empty. In September 1991 and again in 1993, unpaid soldiers loot Kinshasa. In October 1996 a rebellion led by Laurent-Désiré Kabila, backed by Rwanda and Uganda, starts in the east. Mobutu's army, which had been paid to be loyal and was no longer paid, collapses town after town, often selling its weapons as it retreats. On 16 May 1997 Mobutu flies out of Kinshasa. The next day Kabila's troops enter the capital. On 7 September 1997 Mobutu dies of cancer in Rabat, Morocco." },
          { name: "Observance", text: "Valley Forge, Pennsylvania, winter of 1777 to 1778. George Washington's Continental Army, about twelve thousand men, camps in the snow after losing Philadelphia to the British. Congress cannot pay them; the money it does print is nearly worthless. Men march barefoot and leave blood on the snow. Around two thousand die of disease that winter. Yet the army does not dissolve. Washington stays in camp with them through the whole winter, writes letter after letter demanding supplies for them, and, with the drillmaster Baron von Steuben, turns them into trained soldiers. They had joined for a cause and stayed for each other and for their commander. In June 1778 they march out and fight the British to a standstill at Monmouth. Five years later they win the war. Their loyalty had never been bought, so it could not leave with the money." },
          { name: "Interpretation", text: "Paying for loyalty is not wrong; every government, company and army pays its people. The danger is a system in which payment is the only thing holding people to you, and in which their payment depends on your personal survival. In such a system everyone is constantly, silently calculating: is the money still coming, and will it still come if the boss falls? The day the answer becomes doubtful, they begin making arrangements with whoever might pay next. Mobutu's men did not betray him out of hatred. They had simply never been asked to believe in anything but the pay, so when the pay stopped, nothing was left. As Ibn Khaldun observed of declining dynasties, a ruler who has replaced the bond of shared purpose with salaries must keep raising the salaries, until the treasury fails, and then the dynasty." },
          { name: "Parallels", text: "Saigon, March and April 1975. South Vietnam's army has more than a million men and more aircraft than almost any country in Asia, nearly all of it paid for by the United States. In 1974 Congress cuts the aid. Pay and supplies run short. When the North attacks in March 1975, whole divisions disintegrate; officers abandon their units, soldiers strip off their uniforms. On 30 April North Vietnamese tanks break through the gates of the presidential palace. Kabul, 15 August 2021. The Afghan army, paid for by the West at a cost of tens of billions of dollars over twenty years, is reported by its own government to number about three hundred thousand; many are ghost soldiers on the payroll who do not exist, and many real ones have gone months without pay. As American troops leave, the Taliban take province after province, often by buying the local commanders' surrender. On 15 August President Ashraf Ghani flies out of Kabul, and the Taliban walk into the capital. Tamaulipas, 1999 to 2010. Osiel Cárdenas Guillén, head of the Gulf cartel, hires deserters from Mexico's special forces as his bodyguards and enforcers; they call themselves Los Zetas. After Osiel is extradited to the United States in 2007, the Zetas, who had been paid to protect the cartel, break away in 2010 and go to war with it, and become the most violent criminal organisation in Mexico." },
          { name: "The Cost", text: "For Mobutu: his country, his fortune and his life in exile, four months after he fled. For the Congo: two wars that followed his fall and drew in nine African countries; the deaths from violence, disease and hunger were estimated in the millions. For Spain: the Netherlands. For South Vietnam: its existence. For Afghanistan's republic: everything built in twenty years, gone in less than two weeks. Every one of these systems had cost a fortune to build. Each collapsed in weeks, because the loyalty it rested on had been rented, never owned." },
          { name: "The Record", text: "Verified: Mobutu's coup of 24 November 1965; the renaming of the country in 1971; the lootings of Kinshasa in 1991 and 1993; the start of Kabila's rebellion in October 1996; Mobutu's flight on 16 May 1997 and his death in Rabat on 7 September 1997. Disputed: the size of Mobutu's fortune. It was often said to be four or five billion dollars, but investigators searching Swiss banks after his fall found far less than that; much of the money had been spent, or was never found. Disputed: the death toll of the Congo wars. One major survey estimated more than five million excess deaths from 1998 to 2007; other researchers argued the true figure was lower. Verified: the Spanish Fury of 4 to 6 November 1576, and the destruction of the Janissaries on 15 June 1826." },
          { name: "Keys", text: "For those seeking: first, pay people well, but give them a reason to stay that is not money: a shared purpose, a future, a name built together. Second, be present when times are hard, as Washington was at Valley Forge; people forgive missing pay far more easily than a missing leader. Third, never build your force entirely from people who would serve your rival for a better offer. For those keeping: first, never let your people's pay depend on your own survival; when it does, they begin calculating your fall. Second, watch the payroll more closely than the treasury: unpaid guards are a greater danger than an empty vault. Third, the moment you cannot pay, tell the truth early and share the hardship, or the hardship will be shared out without you." },
          { name: "Image", text: "A dam built of coins. For years it holds back the river, and people walk on top of it and admire how high it stands. Each coin is held in place only by the weight of the coins above it. One dry season, the king starts taking coins from the top to pay his debts. Nothing happens for a long time. Then, in a single night, the whole river comes through." },
          { name: "Authority", text: "\"A city for sale, and doomed to quick destruction, if it finds a buyer.\" Sallust, The Jugurthine War, written around 40 BC, quoting the African king Jugurtha's words as he left Rome, where he had bought senator after senator. Machiavelli, The Prince, chapter 12: mercenaries are faithful while there is no war, and in war they flee. And Ibn Khaldun: a ruler who must buy his supporters must pay more each year, until he cannot." },
          { name: "Reversal", text: "Singapore, 1994. Lee Kuan Yew's government publishes a plan to pay its ministers and senior civil servants salaries benchmarked to the top earners in private business, among the highest public salaries in the world. Critics are outraged. Lee's argument is that honest, capable people will not serve for little, and badly paid officials will be bought by someone else. The pay is open, set by formula, and attached to strict anti-corruption law, not to loyalty to any one man. Singapore's government has remained one of the least corrupt in the world. That is the reversal: paying people well is not the mistake. The mistake is paying them for loyalty to you personally, in secret, out of a treasury only you control. Pay them openly for serving something larger than you, and the system can outlive you." },
        ],
      },
      {
        n: 9, title: "Never Let One Man Hold All Your Secrets", opener: "The Rodríguez Orejuela brothers", place: "Cali, 1995",
        judgment: "Whoever holds all your secrets holds your life, and he knows it. On the day he is frightened, or angry, or offered his freedom, your life is his to trade.",
        eras: ["Rome, 1943", "Cali, 1995", "Hong Kong, 2013"],
        story: "The Cali cartel ran like a corporation: quiet, discreet, buying politicians instead of shooting them. Its chief accountant, Guillermo Pallomari, kept the books, including the list of who had been paid. In 1995, after the bosses were arrested and Pallomari feared he would be killed to keep him quiet, he gave himself up to the Americans. His records helped convict the brothers who ran the cartel, and shook the presidency of Colombia itself.",
        key: "Seeking: divide what you know so that no single person can sell all of it. Keeping: the man who keeps your books must have more to lose from betraying you than from staying.",
        sections: [
          { name: "The Law", text: "Never let one man hold all your secrets. Rome, 24 July 1943. For seven years Count Galeazzo Ciano, Benito Mussolini's son-in-law, has been his foreign minister. He sits in every important meeting, and every night he writes it all down in his diary: what Mussolini said, whom he insulted, what he really thought of Hitler. At a meeting of the Fascist Grand Council that night, with Allied armies in Sicily, Ciano votes with the majority against Mussolini. The next day the king has Mussolini arrested. Ciano flees, is captured, and on 11 January 1944 is shot at Verona on the orders of the regime Mussolini set up in the north. But his wife smuggles the diaries out to Switzerland, and after the war they are published: the most damning portrait of Mussolini ever written, by the man who knew everything." },
          { name: "Judgment", text: "Whoever holds all your secrets holds your life, and he knows it. On the day he is frightened, or angry, or offered his freedom, your life is his to trade. Hong Kong, June 2013. Edward Snowden, a twenty-nine-year-old contractor working for the United States National Security Agency, has copied a vast archive of its most secret programmes, reportedly hundreds of thousands of documents, onto drives he carries out of a base in Hawaii. He meets journalists in a Hong Kong hotel room, and from 5 June their stories reveal the agency's mass surveillance programmes to the world. The most powerful intelligence service on earth had given one young contractor the keys to almost everything it was hiding." },
          { name: "Transgression", text: "Cali, Colombia, 1980s to 1995. Gilberto Rodríguez Orejuela, called the Chess Player, and his younger brother Miguel run the Cali cartel. Unlike Pablo Escobar in Medellín, they avoid open war with the state. They buy instead: police, judges, journalists, politicians. By the early 1990s, American officials estimate they control most of the cocaine reaching the United States. Their business is run like a company, with departments, salaries and accounts, and the accounts are kept by a Chilean-born accountant, Guillermo Pallomari. He records everything, including the payments to politicians. In June 1994 tapes surface suggesting that cartel money went into the presidential campaign of Ernesto Samper, who has just been elected. On 9 June 1995 police find Gilberto hiding in a secret compartment of a house in Cali. On 6 August they find Miguel, hiding in a hidden space in an apartment, with help from the cartel's own head of security, Jorge Salcedo, who had secretly gone over to the Americans. Pallomari, by now terrified that the brothers will have him killed to silence him, gives himself up to American agents and is taken to the United States with his family. His testimony and records feed the investigation the press calls Proceso 8000, into the Samper campaign, and, years later, the American prosecution of the brothers. They are extradited in 2004 and 2005, and in 2006 both plead guilty in Miami and are sentenced to thirty years." },
          { name: "Observance", text: "Florence, 1397 onward. The Medici bank, the richest in fifteenth-century Europe, keeps its most important accounts in what it calls the libro segreto, the secret book: the record of the partners' capital and profits. It is held only by the senior partners, never by a branch manager. Each branch, in London, Bruges, Geneva, Rome or Venice, is a separate partnership, with its own books, so that no single manager can see the whole. Cosimo de' Medici, who ran the bank from 1429 until his death in 1464, ruled Florence for thirty years without holding any office, and was never ruined by a clerk. In the twentieth century the Coca-Cola Company turned the same principle into legend: the company says its formula has been kept for decades known to only a handful of people, and it is kept today in a vault in Atlanta. How much of the legend is true, the company has never let anyone check, which is itself the point." },
          { name: "Interpretation", text: "Everyone who holds power needs someone to keep the records, carry the messages and know where the money is. The danger is not in having such a person. It is in letting one person hold everything, and in forgetting that his position is very different from yours. You hold the power; he holds the proof. As long as you are strong and he is safe, he has every reason to stay loyal. But the moment you are under pressure, his calculation changes. He knows that the people hunting you will offer him a great deal for what he knows, and he knows that you may decide the safest thing to do is silence him. From the inside of his fear, betraying you can look like the only way to live. Pallomari did not set out to destroy the Cali cartel. He set out to survive it." },
          { name: "Parallels", text: "Palermo, 1984. Tommaso Buscetta, a senior member of the Sicilian Mafia whose two sons, brother and other relatives had been murdered during a war between the clans, is extradited from Brazil and begins talking to the judge Giovanni Falcone. He explains the structure of Cosa Nostra from the inside, names its bosses and breaks its code of silence. His testimony helps bring about the Maxi Trial, which opens in Palermo in February 1986 with more than four hundred defendants in a bunker courtroom; in December 1987, 338 are convicted. The Mafia murders Falcone in May 1992, but the organisation never recovers its old power. Washington, 1973. John Dean, President Nixon's legal counsel, knows the details of the Watergate cover-up because he helped run it. When he realises he is being set up to take the blame, he goes to the prosecutors, and in June 1973 he testifies for days on live television about what happened in the Oval Office. Moscow, 1985. Oleg Gordievsky, a senior officer of the Soviet intelligence service, the KGB, had been working secretly for British intelligence for more than a decade. Recalled to Moscow under suspicion, he escapes across the Finnish border in the boot of a British diplomat's car in July 1985, carrying in his head the names and methods of an entire service." },
          { name: "The Cost", text: "For the Rodríguez Orejuela brothers: their freedom, a cartel that had once supplied most of the world's cocaine, and, as part of their plea deal, the forfeiture of about $2.1 billion in assets. For Colombia: a presidency spent under a cloud, and a visa withdrawn by the United States from its own sitting president. For Mussolini: a portrait of himself that historians still quote. For the Mafia: hundreds of convictions. For the NSA: its secrets on front pages around the world. The secret-keeper's betrayal is always more expensive than his salary ever was." },
          { name: "The Record", text: "Verified: the arrest of Gilberto Rodríguez Orejuela on 9 June 1995 and of Miguel on 6 August 1995; the role of Jorge Salcedo in Miguel's capture; Pallomari's surrender to American authorities in 1995 and his later testimony; the extradition of both brothers and their guilty pleas in 2006, with sentences of thirty years. Disputed: whether President Samper knew that cartel money entered his campaign. His campaign treasurer and others were convicted; Samper himself was cleared by Colombia's Congress in June 1996, and he has always denied knowing. Unresolved: the fate of Pallomari's wife, who disappeared in 1995. Disputed: the exact number of documents Snowden took, which American officials and Snowden describe very differently." },
          { name: "Keys", text: "For those seeking: first, divide what you know among different people, so that no single one can sell all of it. Second, keep the most dangerous records out of writing, or out of existence, where you lawfully can. Third, choose secret-keepers whose futures are bound to yours, and make sure they know you will protect them when things go wrong. For those keeping: first, the person who keeps your books must have more to lose from betraying you than from staying; if he is frightened of you, he is already halfway out of the door. Second, never threaten the one who holds your proof. Third, assume that every secret held by one person will one day be told, and decide now whether you can survive its telling." },
          { name: "Image", text: "One key to every door in the castle, on a ring at the belt of a single servant. It makes the household easy to run. The lord never has to search for anything. Then one night the servant hears the lord's guards talking about him in the corridor, and in the morning the servant is gone, and so is the ring." },
          { name: "Authority", text: "\"Three may keep a secret, if two of them are dead.\" Benjamin Franklin, Poor Richard's Almanack, 1735. Machiavelli, in the Discourses on Livy, on conspiracies: the more men who share a secret, the sooner it is out, and the one who shares it with you is the one who can sell it." },
          { name: "Reversal", text: "Washington, 1924 to 1972. J. Edgar Hoover runs the FBI for forty-eight years and keeps private files on presidents, senators, judges and their families. Several presidents want him gone; none of them dares remove him, because of what he holds. Lyndon Johnson put it, in his own crude words, that it was better to have him inside the tent than outside. Hoover dies in office on 2 May 1972. That is the reversal, and it is a grim one: once a man already holds your secrets, the safest place for him may be close to you, bound to your success, honoured and watched. It is a way of surviving the mistake, not of avoiding it. The real lesson is to never let one man gather so much in the first place." },
        ],
      },
      {
        n: 10, title: "Your Household Is Part of Your Throne", opener: "Ferdinand and Imelda Marcos", place: "Manila, 1986",
        judgment: "People judge a ruler by his family as much as by his laws. Every excess in your household is counted against your throne, and the people keeping count are the people you rule.",
        eras: ["Rome, AD 48", "Manila, 1986", "Tunis, 2011"],
        story: "Ferdinand Marcos ruled the Philippines for twenty years, and his wife Imelda became a power of her own: governor of Manila, minister, collector of palaces, paintings and jewels. In February 1986 millions of Filipinos filled the main highway of Manila to stop his soldiers. On the night of 25 February American helicopters carried the family out of the palace. In the closets they left behind, the crowd found more than a thousand pairs of her shoes, and the shoes became the most famous picture of the whole regime.",
        key: "Seeking: keep your family out of the offices and the deals; their gains will be counted as your theft. Keeping: the more power you hold, the more your household must live as if every room is watched, because it is.",
        sections: [
          { name: "The Law", text: "Your household is part of your throne. Rome, AD 48. The emperor Claudius is away at the port of Ostia. In the city, his young wife, Valeria Messalina, takes part in a public wedding ceremony with a senator named Gaius Silius, with guests and a feast, while her husband is still alive and on the throne. For years Messalina has used her place at the emperor's side to destroy her rivals and enrich her friends; Claudius has seen none of it. His freedmen, terrified of what this marriage means, rush to Ostia and finally tell him. Messalina is killed in the gardens she had seized from a man she had ruined, and Silius and others are executed. Claudius goes in to dinner and, according to the historians, does not even ask how she died. He survived his wife's scandal. He would not survive his next marriage: he was dead within six years, most ancient writers say poisoned by his next wife, Agrippina." },
          { name: "Judgment", text: "People judge a ruler by his family as much as by his laws. Every excess in your household is counted against your throne, and the people counting are the people you rule. Tunis, December 2010 to January 2011. Zine El Abidine Ben Ali has ruled Tunisia for twenty-three years. His second wife, Leila Trabelsi, and her large family have taken control of banks, airlines, car dealerships and land; an American ambassador's cable, leaked in 2010, calls the extended family a quasi-mafia. On 17 December 2010 a fruit seller named Mohamed Bouazizi, humiliated by an official, sets himself on fire in the town of Sidi Bouzid. Protests spread across the country, and the anger falls on the family as much as on the president. On 14 January 2011 Ben Ali flies to Saudi Arabia. Within weeks the uprisings he had set off spread across the Arab world." },
          { name: "Transgression", text: "Manila, 1965 to 1986. Ferdinand Marcos, a brilliant lawyer and war hero by his own telling, is elected president in 1965, and re-elected in 1969. In September 1972, a year before he must leave office, he declares martial law. His wife, Imelda, a former beauty queen, becomes a power in her own right: governor of Metro Manila from 1975, minister of human settlements from 1978, builder of cultural centres, film festivals and palaces, and traveller with an entourage around the world. Friends and relatives of the couple, the press calls them the cronies, receive monopolies over sugar, coconuts and construction. On 21 August 1983 the opposition leader Benigno Aquino, returning from exile, is shot dead on the steps of the plane at Manila airport. Two and a half years later Marcos calls a snap election against Aquino's widow, Corazon. On 7 February 1986 the vote is held; on 9 February, thirty-five computer workers at the official count walk out, saying the results are being falsified. On 22 February two of Marcos's top commanders defect. Cardinal Jaime Sin calls on the people to protect them, and for four days hundreds of thousands, then by many estimates millions, fill the highway known as EDSA, stopping tanks with their bodies, rosaries and flowers. On the night of 25 February American helicopters carry the Marcos family from the palace to an air base, and from there to exile in Hawaii. In the palace, the crowd finds Imelda's closets." },
          { name: "Observance", text: "Rome, 62 BC. During the women-only rites of the Good Goddess at the house of Julius Caesar, then the chief priest of Rome, a young nobleman, Publius Clodius, sneaks in disguised as a woman. Scandal follows; people whisper that he came to see Caesar's wife, Pompeia. Caesar divorces her. At Clodius's trial he says he knows nothing against her, and when asked why he then divorced her, he answers, by Plutarch's account, that Caesar's wife must be above suspicion. Two thousand years later, Angela Merkel led Germany for sixteen years, from 2005 to 2021, and her husband, the chemist Joachim Sauer, stayed almost entirely out of public life; he kept his own work, gave almost no interviews and rarely appeared beside her. No member of her family held office or did business with her government. In sixteen years at the top of Europe's largest economy, the household gave her enemies nothing to use." },
          { name: "Interpretation", text: "People cannot see into a ruler's mind, and most cannot read the budget. But they can see the wife's jewels, the son's cars, the brother-in-law's new company. The household is the part of power that ordinary people can actually look at, so it is the part they judge. A ruler can often survive his own mistakes, because he can explain them as policy; the excesses of his family cannot be explained as anything but greed. And there is a second danger: family members are the people a ruler is least able to discipline. He cannot sack his wife or exile his son as easily as a minister, so their excesses grow unchecked, and he becomes their defender, sharing their guilt. Ibn Khaldun warned that the luxury of the ruling family is one of the surest signs of a dynasty's decline: in the third generation, the family forgets the hardship that built the throne, and the people do not forget the luxury that replaced it." },
          { name: "Parallels", text: "Jakarta, 1967 to 1998. Under President Suharto, his six children build business empires in toll roads, telecommunications, cars, oil and banks; the family's fortune was estimated in the billions. When the Asian financial crisis of 1997 wrecks the economy, their wealth becomes the face of everything people hate about the regime. Suharto resigns on 21 May 1998 after riots in which more than a thousand people die. His youngest son, Hutomo Mandala Putra, called Tommy, is later convicted of ordering the murder of a judge who had sentenced him for corruption. Culiacán, 17 October 2019 and 5 January 2023. Ovidio Guzmán, one of the sons of the jailed drug lord El Chapo, is arrested by Mexican troops in Culiacán in 2019. The cartel's gunmen take over the city until the government releases him that same afternoon. In January 2023 he is captured again in a raid in which ten soldiers die; in September he is extradited to the United States. El Chapo's sons, known as Los Chapitos, had turned their father's household into a war that the Mexican state could no longer ignore." },
          { name: "The Cost", text: "For Marcos: his presidency and the rest of his life, in exile in Honolulu, where he died on 28 September 1989. For the Philippines: billions of dollars that a government commission spent decades trying to recover; it has recovered a large part, but not all, of what it says was taken. For Imelda: years of lawsuits, and in 2018, at the age of eighty-nine, a conviction for corruption in a Philippine court, which she appealed. For Ben Ali: exile in Saudi Arabia until his death in 2019. For Suharto: his presidency and his name. The family had been the source of the ruler's comfort. It became the evidence against him." },
          { name: "The Record", text: "Verified: the declaration of martial law in September 1972; Imelda Marcos's posts as governor of Metro Manila and minister; the assassination of Benigno Aquino on 21 August 1983; the walkout of the vote counters on 9 February 1986; the four days of EDSA, 22 to 25 February 1986; the family's departure on American helicopters on 25 February. Disputed: the number of shoes. Inventories recorded around a thousand pairs; the popular figure of three thousand comes from early reports; Imelda herself later said she had one thousand and sixty. Disputed: the total amount taken by the Marcos family and their associates, estimated anywhere from five to ten billion dollars; the government's recovery commission has recovered billions of pesos but has never fixed the total. Verified: in May 2022, thirty-six years after the family fled, Ferdinand Marcos Jr., known as Bongbong, was elected President of the Philippines by a landslide." },
          { name: "Keys", text: "For those seeking: first, keep your family out of offices and deals connected to your power; their gains will be counted as your theft. Second, if a family member must serve, give them a role with clear rules and no money passing through their hands. Third, decide early who in your household speaks for you, and make sure the answer is no one. For those keeping: first, the more power you hold, the more your household must live as if every room is watched, because it is. Second, deal with a family member's excess the moment you see it, privately and firmly; every month you wait, you become their accomplice. Third, remember that the people judge what they can see, and what they can see is your family." },
          { name: "Image", text: "The glass palace. The ruler built it so that everyone could admire his wealth from the street, and for years they did. Now, at night, the crowd outside can see every room lit up: the wife trying on jewels, the son counting money, the cousins at the table. The ruler is in the study at the back, working on the budget, and he cannot understand why the crowd outside is growing." },
          { name: "Authority", text: "\"Caesar's wife must be above suspicion.\" Julius Caesar, 62 BC, as told by Plutarch. And from Ibn Khaldun, the Muqaddimah of 1377: in its last stage a dynasty's rulers and their families spend in luxury what their ancestors won in hardship, and the people who once supported them turn away." },
          { name: "Reversal", text: "Manila, 9 May 2022. Thirty-six years after the crowd at EDSA drove his family out, Ferdinand Marcos Jr. is elected president with about thirty-one million votes, the largest majority in decades, with Sara Duterte, daughter of the outgoing president, as his vice-president. The family had never stopped working: winning governorships and Senate seats, rebuilding its name among voters too young to remember martial law. That is the reversal: a household that stays united, patient and disciplined after the fall can become the very thing that rebuilds a throne. The same family that brought the father down carried the son back up. But note what it took: thirty-six years, and a new generation that had never seen the shoes." },
        ],
      },
    ],
  },
  {
    n: 3, title: "The Treasury", opens: "Feb 2027",
    line: "What money builds, and how money buries the ones who built it.",
    laws: [
      {
        n: 11, title: "Do Not Feast Where the Hungry Can See You", opener: "The Shah of Iran", place: "Persepolis, 1971",
        judgment: "Wealth shown to the hungry is not admired. It is counted, remembered and one day collected, and the bill is always larger than the feast.",
        eras: ["Rome, AD 64", "Persepolis, 1971", "Colombo, 2022"],
        story: "In October 1971 the Shah of Iran celebrated 2,500 years of Persian monarchy in a city of silk tents among the ruins of Persepolis. Kings, presidents and princes from around the world dined on food flown in from Paris. In exile in Iraq, an old cleric named Ruhollah Khomeini denounced it to anyone who would listen. Seven years later, millions of Iranians marched against the Shah. In January 1979 he left Iran for good; two weeks later Khomeini came home to cheering crowds.",
        key: "Seeking: spend on what others share in: roads, schools, jobs, before you spend on what only you enjoy. Keeping: the higher you rise, the more privately you must enjoy it, and the more publicly you must be seen to give.",
        sections: [
          { name: "The Law", text: "Do not feast where the hungry can see you. Rome, July AD 64. A fire breaks out near the Circus Maximus and burns for six days; of the city's fourteen districts, three are destroyed and seven badly damaged. The emperor Nero, who was away at Antium, opens his gardens to the homeless. But when the ashes cool, he takes a great stretch of the burned land in the heart of the city and builds himself the Golden House: a palace of gilded rooms, a dining hall said to revolve, an artificial lake and a colossal bronze statue of himself. Romans who had lost their homes walk past it every day. The rumour spreads that Nero sang of the fall of Troy while the city burned, and that he started the fire to clear space for his palace. Within four years the army and the Senate turn on him, and in June 68 he kills himself, aged thirty. His successors drain the lake and build the Colosseum on it, for the people." },
          { name: "Judgment", text: "Wealth shown to the hungry is not admired; it is counted, remembered and one day collected. Bangui, 4 December 1977. Jean-Bédel Bokassa, who had seized power in the Central African Republic in 1965, crowns himself emperor in a ceremony modelled on Napoleon's. His throne is a giant gilded eagle; his crown is set with thousands of diamonds; the wine and the horses come from France. The ceremony costs about twenty million dollars, a large part of the yearly budget of one of the poorest countries on earth. Less than two years later, in January and April 1979, schoolchildren protest against being forced to buy expensive uniforms made by a company linked to his family; many are killed. In September 1979, while he is visiting Libya, French troops fly in and restore the president he overthrew. The emperor's coronation had been watched by a hungry country, and remembered." },
          { name: "Transgression", text: "Persepolis, 12 to 16 October 1971. Mohammad Reza Pahlavi, Shah of Iran since 1941, marks 2,500 years since Cyrus the Great founded the Persian Empire. Beside the ruined palaces of Persepolis a city of air-conditioned tents is built, designed by a Paris decorating firm, with gardens planted in the desert. Kings, queens, presidents and princes from around the world arrive. The banquet, prepared by the Paris restaurant Maxim's, lasts more than five hours: quail eggs stuffed with caviar, roast peacock, wines from France's great vineyards. A parade of soldiers in costumes of every Persian dynasty marches past the guests. The official cost was given as about seventeen million dollars; critics claimed many times more. From exile in Najaf, in Iraq, the cleric Ruhollah Khomeini denounces the celebration as a feast of tyrants while Iranians go hungry. His sermons are copied on cassette tapes and smuggled into Iran. Two years later, in 1973, oil prices quadruple and money floods into the country, but much of it flows to the court and the cities while prices soar for everyone else. In 1978 protests turn into a revolution. On 16 January 1979 the Shah and his wife fly out of Tehran. On 1 February Khomeini lands in Tehran, and millions line the streets to greet him. The Shah dies of cancer in Cairo on 27 July 1980." },
          { name: "Observance", text: "Omaha, Nebraska, 1958 to today. Warren Buffett, one of the richest men in the history of the world, still lives in the house he bought in 1958 for $31,500. He has said for decades that he will give away almost his entire fortune, and has given away tens of billions of dollars. When his company's shareholders gather each year in Omaha, he eats with them in the arena. Montevideo, 2010 to 2015. José Mujica, a former guerrilla who spent about thirteen years in prison, becomes President of Uruguay. He gives away most of his salary, refuses to live in the presidential palace and stays on his small farm outside the capital, driving himself in an old Volkswagen Beetle. The press called him the poorest president in the world. Neither man had any shortage of critics. But no one could ever point at a feast." },
          { name: "Interpretation", text: "People do not resent wealth as much as they resent being made to watch it. A ruler's wealth that stays out of sight is an abstraction; a banquet on television while bread prices rise is an insult, delivered personally, to every family that cannot afford bread. The Shah did not lose his throne because of one party. He lost it over decades of repression, inequality and a country changing faster than its politics. But the party at Persepolis became the image that explained everything to people who would never read an economic report: the king had flown in peacocks from Paris for foreigners while his own people struggled. A feast is a story the powerful tell about themselves. They forget that the hungry tell it too, and that the hungry tell it longer." },
          { name: "Parallels", text: "Bucharest, 1984 to 1989. Nicolae Ceaușescu begins building the House of the People, one of the largest buildings on earth, after demolishing a fifth of the old city centre to make room. At the same time, to pay off the national debt, he exports most of Romania's food; Romanians queue for bread and meat with ration cards, and homes are heated for a few hours a day in winter. The building is still unfinished when he is shot on Christmas Day 1989. Sardinia, June 2001. Dennis Kozlowski, chief executive of Tyco, throws his wife a two-million-dollar birthday party with an ice sculpture of Michelangelo's David; the company pays about half. Later his six-thousand-dollar shower curtain, bought with company money, becomes a national joke. In 2005 he is convicted of looting the company and sentenced to up to twenty-five years. Colombo, 9 July 2022. Sri Lanka has run out of fuel, food and medicine. Protesters storm the presidential palace of Gotabaya Rajapaksa; television shows them swimming in his pool, lying on his bed and cooking in his kitchen. Four days later he flees the country, and resigns by email from Singapore." },
          { name: "The Cost", text: "For the Shah: the Peacock Throne, a dynasty that ended with him after only two generations, and his last years as a dying exile whom few countries would accept. For Iran: a revolution and an Islamic Republic that has ruled ever since. For Nero: his life, at thirty. For Bokassa: his empire and, in 1987, a death sentence in his own country, later commuted. For Kozlowski: about six years in prison. For Rajapaksa: the presidency, and his family's grip on Sri Lankan politics. A feast lasts a few days. The memory of it can last for generations." },
          { name: "The Record", text: "Verified: the celebration of 12 to 16 October 1971, the tent city, the catering by Maxim's of Paris, and the guest list of heads of state; Khomeini's denunciations from Najaf; the Shah's departure on 16 January 1979 and Khomeini's return on 1 February; the Shah's death in Cairo on 27 July 1980. Disputed: the cost of the celebration. The government's own figure was around seventeen million dollars; critics and later writers gave figures ranging up to a hundred million and more; no full accounting has ever been published. Disputed: that Nero fiddled while Rome burned. The fiddle had not been invented; the story that he sang of Troy during the fire was told by Roman historians writing decades later, and Tacitus himself calls it a rumour. Verified: the Golden House, whose ruins can still be visited in Rome." },
          { name: "Keys", text: "For those seeking: first, spend on what others share in before you spend on what only you enjoy; a road with your name on it is remembered longer than a party. Second, never let your celebration fall in a season of hardship for the people you lead. Third, if you must display wealth to impress partners, do it where those you lead cannot watch. For those keeping: first, the higher you rise, the more privately you must enjoy your wealth and the more publicly you must be seen to give. Second, watch the price of bread, fuel and rent in the places you rule; they tell you how your feasts will be judged. Third, never build your palace on the ruins of other people's homes." },
          { name: "Image", text: "The lit window in a winter street. Inside, a long table, candles, laughter, a roast being carved. Outside, in the snow, a crowd has gathered. They are not looking at the food. They are looking at each other, and they are counting how many of them there are." },
          { name: "Authority", text: "Machiavelli, The Prince, chapter 16, 1513: a prince who wishes to be known as generous will spend everything on display and end by burdening his people, which makes him hated; it is better to be thought mean than to be hated. And from Ibn Khaldun: luxury is the disease of dynasties in their last stage; the rulers spend in comfort what their fathers won in hardship, and the people learn to hate what they once followed." },
          { name: "Reversal", text: "Rome, 27 BC to AD 14. Augustus spent on a vast scale, but almost always on the public: temples, aqueducts, a forum, a theatre, roads across the empire. His own house on the Palatine was famous for being modest. By the end of his life he could boast that he had found Rome a city of brick and left it a city of marble. Paris, from 1661. Louis XIV built Versailles, the most extravagant palace in Europe, and kept his throne for fifty-four more years, partly because the feast was turned into a system that trapped his nobles at court, away from their lands and armies. That is the reversal: spending can build power when the public shares in what is built, or when the display is a tool of control rather than a pleasure. But note what came after Louis XIV: within three generations, Versailles was the image that a hungry Paris marched on in 1789." },
        ],
      },
      {
        n: 12, title: "Borrowed Strength Breaks All at Once", opener: "Lehman Brothers", place: "New York, 2008",
        judgment: "Debt makes you look stronger than you are, right up to the day it makes you weaker than anyone imagined. Borrowed strength does not bend. It snaps.",
        eras: ["Paris, 1720", "New York, 2008", "Hong Kong, 2024"],
        story: "By 2007 Lehman Brothers, a bank that had survived the Civil War and the Great Depression, was borrowing about thirty dollars for every dollar of its own money, much of it bet on American property. When house prices fell, the losses ran through that borrowed money like fire. On the weekend of 13 and 14 September 2008 no rescue came. At 1:45 in the morning of Monday 15 September it filed for bankruptcy, the largest in American history, and the world's financial system went into shock.",
        key: "Seeking: borrow to build something that will pay back the debt, never to look bigger than you are. Keeping: know how much you owe, to whom, and when it falls due, better than anyone else in the room.",
        sections: [
          { name: "The Law", text: "Borrowed strength breaks all at once. Paris, 1716 to 1720. A Scottish gambler and financial genius named John Law persuades the regent of France to let him found a bank that issues paper money. Then he takes over the Mississippi Company, which holds France's trade with Louisiana, and sells shares that can be bought with the paper money his own bank prints. The shares rise more than twentyfold. Crowds fight in the Rue Quincampoix to buy them; a new word, millionaire, is coined. Law becomes Controller General of Finances, effectively France's finance minister. In 1720 investors begin to cash out, and there is not enough gold behind the paper. Law issues decree after decree to stop the run; in July the crowd at his bank is so large that people are crushed to death. By December the system has collapsed, and Law flees France in disguise. He dies poor in Venice in 1729. France's distrust of banks and paper money lasted for generations." },
          { name: "Judgment", text: "Debt makes you look stronger than you are, right up to the day it makes you weaker than anyone imagined. Greenwich, Connecticut, 1998. Long-Term Capital Management is the most admired hedge fund in the world; its partners include two economists, Robert Merton and Myron Scholes, who won the Nobel Prize in 1997. Its trades are tiny bets made enormous by borrowing: it holds positions worth more than a hundred billion dollars on less than five billion of its own capital. In August 1998 Russia defaults on its debt, and markets move in ways the fund's models said were almost impossible. In weeks it loses most of its capital. On 23 September the Federal Reserve Bank of New York gathers the major banks in a room and they put in $3.6 billion to prevent a collapse that could take them with it. The geniuses had not been wrong about much. They had simply borrowed so much that being slightly wrong was fatal." },
          { name: "Transgression", text: "New York, 1994 to 2008. Richard Fuld, a former trader with a fierce temper, becomes chief executive of Lehman Brothers in 1994, when it is a small, struggling bank, and makes it the fourth largest investment bank in America. In the property boom of the 2000s Lehman buys mortgage lenders, packages home loans into securities and buys commercial property, all with borrowed money. By the end of 2007 it holds about thirty dollars of assets for every dollar of its own capital. When American house prices fall, the value of those assets falls with them, and every dollar lost comes out of that thin layer of capital. In March 2008 Bear Stearns, a smaller rival, nearly collapses and is sold to JPMorgan with government help. Lehman tells investors it is safe. A later court-appointed examiner finds that it used an accounting move called Repo 105 to make about fifty billion dollars of its debt disappear from its books at the end of each quarter. Through the summer it looks for a buyer: Korea, then Bank of America, then Barclays. On the weekend of 13 and 14 September, at the Federal Reserve Bank of New York, the British regulator refuses to approve the Barclays deal in time, and the American Treasury, under Henry Paulson, refuses to put in public money. At 1:45 in the morning of 15 September 2008, Lehman files for bankruptcy with about $639 billion in assets. That day the Dow Jones falls more than five hundred points. The next day the government lends the insurer AIG eighty-five billion dollars to stop the panic spreading. It spreads anyway." },
          { name: "Observance", text: "New York, 2005 to 2008. Jamie Dimon, chief executive of JPMorgan Chase, talks endlessly about what he calls a fortress balance sheet: more capital than the rules require, less borrowing than his rivals, and cash he can reach in a crisis. In 2006 and 2007 his bank pulls back from the riskiest mortgage securities while others are piling in, and analysts complain that it is missing out on profits. When the crisis comes, JPMorgan is strong enough to buy Bear Stearns in March 2008 and Washington Mutual in September, and comes out of the crisis larger than it went in. It was not braver or cleverer than Lehman. It had simply borrowed less, so it could survive being wrong." },
          { name: "Interpretation", text: "Borrowing is not weakness. Almost every great enterprise in history was built partly with borrowed money. The danger is in what borrowing does to the shape of the risk. Without debt, a fall of ten percent in what you own costs you ten percent. With thirty dollars borrowed for every one of your own, a fall of a little over three percent wipes you out entirely. Worse, the lenders know this, and the moment they suspect you are close to the edge, they stop lending, and the borrowed strength disappears in days. That is why such collapses always seem sudden: everything looks fine, and then nothing is fine. The firm did not weaken slowly. It was already that weak; the debt simply hid it, until the morning the lenders all asked for their money back at once." },
          { name: "Parallels", text: "London, 11 May 1866, Black Friday. Overend, Gurney and Company, the greatest discount house in the world, called the bankers' bank, has lent heavily against railways and ships that cannot pay. It suspends payments. Crowds fill Lombard Street, and more than two hundred companies fail in the panic that follows. Santa Clara, California, 9 and 10 March 2023. Silicon Valley Bank, the bank of America's tech start-ups, has put its customers' deposits into long-term bonds that lost value as interest rates rose. When it announces a loss and tries to raise money, its customers, connected on group chats, try to withdraw about forty-two billion dollars in a single day. The next morning regulators close it. Hong Kong, 29 January 2024. China Evergrande, once the most valuable property developer in the world, with more than three hundred billion dollars of debts and over a thousand unfinished projects, is ordered into liquidation by a Hong Kong court. Its founder, Hui Ka Yan, once Asia's richest man, had been placed under police control in China the previous September." },
          { name: "The Cost", text: "For Lehman Brothers: one hundred and fifty-eight years of history ended in a weekend; about twenty-five thousand employees lost their jobs, many leaving the building on 15 September carrying their belongings in boxes; shareholders lost everything. For Richard Fuld: the fortune he held in Lehman shares, said to have once been worth hundreds of millions of dollars, and his reputation. For the world: the deepest financial crisis since the 1930s, millions of jobs lost, millions of homes repossessed. For John Law: France and his fortune. For Evergrande's buyers: homes paid for and never built. Borrowed strength breaks the borrower, and then everyone standing near him." },
          { name: "The Record", text: "Verified: Lehman's bankruptcy filing at 1:45 a.m. on 15 September 2008, with about $639 billion in assets; its leverage of about thirty to one; the failed talks with Barclays and the government's refusal of public money. Verified: the court examiner Anton Valukas's report of March 2010, which described Repo 105 and found that it was used to reduce reported debt by about fifty billion dollars at the end of quarters. Disputed: whether executives broke the law. The examiner said there were claims that could be brought against them; no criminal charges were ever filed, and Fuld has always said Lehman did nothing wrong. Disputed: whether the government could and should have saved Lehman; Paulson said it lacked the legal power, and critics say it chose not to." },
          { name: "Keys", text: "For those seeking: first, borrow to build something that will pay back the debt, never to look bigger than you are. Second, never let anyone else's borrowed money be the only thing holding up your success; the day they want it back, you fall. Third, test yourself with the worst year you can imagine, then a worse one. For those keeping: first, know how much you owe, to whom, and when it falls due, better than anyone else in the room. Second, keep a reserve that you can reach in a single day, because a crisis never waits for a week. Third, when your lenders start asking questions, they are already deciding; answer early, and from strength." },
          { name: "Image", text: "A tower built on stilts. From the street it is the tallest building in the city, and people pay a great deal to live in its upper floors. Only the builder knows that most of the stilts are rented, and that the owners of each one can take it back with a day's notice. One windy morning, a few of them do." },
          { name: "Authority", text: "\"The borrower is servant to the lender.\" Proverbs 22:7, King James Version, 1611. \"Neither a borrower nor a lender be; for loan oft loses both itself and friend.\" Shakespeare, Hamlet, around 1600, in the mouth of Polonius, a foolish old man who is right about this one thing. And from Warren Buffett's letter to shareholders of 2001: only when the tide goes out do you discover who has been swimming naked." },
          { name: "Reversal", text: "London, 1694. England, at war with France and short of money, creates the Bank of England to lend the government £1.2 million, and begins a national debt that it never fully repays. Over the next century that debt pays for the navy, the wars and the expansion that make Britain the strongest power on earth, because Parliament guarantees it with taxes, pays the interest without fail, and lenders trust it. France, with a richer country and no such trust, borrows at higher rates, defaults again and again, and ends in revolution. That is the reversal: borrowed strength can build an empire when it is used to build lasting power, backed by income you can count on, and when you never miss a payment. It breaks the ones who borrow to look strong, rather than to become strong." },
        ],
      },
      {
        n: 13, title: "Praise Is Not Proof", opener: "Enron", place: "Houston, 2001",
        judgment: "Applause tells you what people believe, never what is true. When everyone is praising you, ask who has actually checked.",
        eras: ["Stockholm, 1932", "Houston, 2001", "Munich, 2020"],
        story: "For six years running, Fortune magazine named Enron, an energy company in Houston, America's Most Innovative Company. Its executives were celebrated as geniuses; its share price rose more than tenfold. In March 2001 a young reporter asked a simple question in print: how exactly does Enron make its money? No one could answer clearly. By December the company that everyone had praised was bankrupt, and the profits had turned out to be largely an invention.",
        key: "Seeking: do not believe your own praise; find the one person who will check your numbers and listen to her. Keeping: when everyone praises you, invite the doubter in before the doubter invites the prosecutor.",
        sections: [
          { name: "The Law", text: "Praise is not proof. Paris, 12 March 1932. In an apartment on the Avenue Victor-Emmanuel III, Ivar Kreuger, the Swedish industrialist known as the Match King, shoots himself. For a decade he has been one of the most admired businessmen in the world: his companies make about three-quarters of the world's matches, he lends money to governments across Europe in exchange for match monopolies, and Time magazine has put him on its cover. Investors in America and Europe have bought his companies' bonds by the hundreds of millions of dollars, on the strength of his name. After his death, accountants open the books. They find that hundreds of millions in assets do not exist; he had even forged Italian government bonds. The Kreuger crash became one of the reasons America created the Securities and Exchange Commission. His investors had trusted the praise, and never asked to see the proof." },
          { name: "Judgment", text: "Applause tells you what people believe, never what is true. Munich, June 2020. Wirecard, a German payments company, has risen to join the DAX, Germany's index of its thirty largest companies, replacing Commerzbank, one of the country's oldest banks. Since 2015 the Financial Times reporter Dan McCrum has published evidence that its accounts are false. Germany's financial regulator responds by investigating the journalists and banning bets against the company's shares. On 18 June 2020 the auditors announce that 1.9 billion euros, money that supposedly sits in banks in the Philippines, cannot be found. The banks say it never existed. On 25 June Wirecard files for insolvency. Its chief executive, Markus Braun, is arrested; its chief operating officer, Jan Marsalek, disappears and is still being hunted." },
          { name: "Transgression", text: "Houston, 1985 to 2001. Enron is formed in 1985 from a merger of two gas pipeline companies under Kenneth Lay. In the 1990s, led by a brilliant young executive named Jeffrey Skilling, it turns itself from a pipeline company into a trader of energy, then of almost anything: electricity, broadband capacity, even weather risk. It is allowed to use an accounting method called mark-to-market, which lets it book the whole expected profit of a long contract on the day it is signed. Its finance chief, Andrew Fastow, creates hundreds of side companies, with names like LJM and Raptor, which buy Enron's failing assets and hide its debts. Fortune names Enron America's Most Innovative Company every year from 1996 to 2001. Its shares reach $90.75 in August 2000. In March 2001 Bethany McLean of Fortune publishes an article titled \"Is Enron Overpriced?\" asking how the company actually makes money. In February Skilling becomes chief executive; on 14 August he suddenly resigns. That month an accountant inside the company, Sherron Watkins, writes to Lay that she fears Enron will implode in a wave of accounting scandals. On 16 October Enron announces a loss of $618 million and cuts its shareholders' equity by $1.2 billion. Within weeks the side companies are exposed. On 2 December 2001 Enron files for bankruptcy, then the largest in American history. Its auditors, Arthur Andersen, are found to have shredded documents." },
          { name: "Observance", text: "New York, late 2000. Jim Chanos, an investor who makes his living betting that companies are worth less than the market believes, picks up Enron's annual report and reads it the way almost no one else does: line by line. He notices that its returns on capital are low, that it sells shares heavily, and that its side deals are described in language no one can understand. He bets against the company in November 2000, when its shares are still near their peak, and tells reporters what he has found; his doubts help prompt Bethany McLean's article. While analysts at the largest banks were still rating Enron a buy, one man with a highlighter had read the proof, and found there was none. It is the oldest discipline in finance and the most neglected: read the numbers, not the headlines." },
          { name: "Interpretation", text: "Praise is cheap to give and pleasant to receive, and that is exactly why it is dangerous. Once a person or a company is admired, a strange thing happens: the admiration itself becomes the evidence. Investors buy because others have bought. Journalists praise because others have praised. Regulators hesitate to question someone everyone else respects. And the person being praised begins to believe it too, and begins to defend the image rather than the substance. At Enron the praise did more than flatter; it covered for the fraud. Every year that Fortune named the company most innovative, it became harder for anyone inside to say the profits were fake, and easier for those outside to dismiss the doubters as jealous. The only defence is the plainest question in the world: show me." },
          { name: "Parallels", text: "New York, 11 December 2008. Bernard Madoff, former chairman of the Nasdaq stock market and one of the most respected figures on Wall Street, tells his sons that his investment business is one big lie. They report him, and he is arrested the next morning. For decades his clients had been content with steady returns and his reputation; an investigator named Harry Markopolos had sent the Securities and Exchange Commission detailed warnings from 2000 onward, and was ignored. Clients' accounts showed about sixty-five billion dollars; most of it had never existed. Madoff is sentenced to 150 years. The Bahamas, November 2022. Sam Bankman-Fried, the young founder of the crypto exchange FTX, had been praised on magazine covers and in Congress as the honest face of the industry. On 2 November a news report questions his trading firm's balance sheet; within nine days FTX collapses, with about eight billion dollars of customers' money missing. In 2024 he is sentenced to twenty-five years. Crimea, 1787. Legend says that when Catherine the Great toured her new southern lands, her minister and favourite Grigory Potemkin built false village fronts along the river to impress her. Historians say the legend is mostly invented by his rivals. But the phrase Potemkin village has outlived the truth, because everyone recognises the thing it describes." },
          { name: "The Cost", text: "For Enron: the company; about twenty thousand employees lost their jobs, and many lost their retirement savings, which had been invested in Enron shares that went from about ninety dollars to less than a dollar. For its shareholders: tens of billions of dollars. For Arthur Andersen, one of the five largest accounting firms in the world: its existence; convicted of obstruction in 2002, it collapsed, and about eighty-five thousand people around the world lost their jobs, even though the Supreme Court later overturned the conviction. For Lay: a conviction, and death from a heart attack before he could be sentenced. For Skilling: twelve years in prison. Praise had been the most valuable thing Enron owned. Its value turned out to be zero." },
          { name: "The Record", text: "Verified: Fortune's \"Most Innovative\" award to Enron from 1996 to 2001; the peak share price of $90.75 in August 2000; Bethany McLean's article of March 2001; Skilling's resignation on 14 August 2001; Sherron Watkins's warning letter of August 2001; the announcement of 16 October 2001; the bankruptcy of 2 December 2001. Verified: the convictions of Lay and Skilling in May 2006; Lay's death on 5 July 2006, after which his conviction was cleared under the law because he could not appeal; Fastow's guilty plea and six-year sentence. Verified: the conviction of Arthur Andersen in 2002 and its reversal by the Supreme Court in 2005, too late to save the firm. Disputed: the Potemkin villages, as the parallel above says." },
          { name: "Keys", text: "For those seeking: first, do not believe your own praise; the moment you start quoting your press, you have stopped checking your numbers. Second, find the one person who will read your accounts line by line and tell you what is wrong, and listen to her. Third, never build a result you cannot explain in plain words to a stranger. For those keeping: first, when everyone praises you, invite the doubter in, before the doubter invites the prosecutor. Second, treat every award and ranking as a risk, not an asset: the higher the pedestal, the further the fall. Third, when you hear yourself defending your image rather than your results, stop and look at the results." },
          { name: "Image", text: "A crown of paper, painted gold. From the back of the hall it shines as brightly as a real one, and the crowd cheers the man who wears it. Only in the rain does anyone notice that the gold is running down his face." },
          { name: "Authority", text: "From Aesop's fables: the fox who praised the crow's beautiful voice until the crow opened its beak to sing, and dropped the cheese the fox had wanted all along. \"Trust, but verify\": a Russian proverb, repeated by President Ronald Reagan to Mikhail Gorbachev when they signed a treaty in December 1987, and the motto of every honest auditor since." },
          { name: "Reversal", text: "Chicago, autumn 1982. Seven people die after taking Tylenol capsules that someone has laced with cyanide on store shelves. Johnson and Johnson, which makes Tylenol, is not at fault, but within days it pulls about thirty-one million bottles from shops across America, at a cost of around a hundred million dollars, and reintroduces the product in tamper-proof packaging. Its honesty is praised everywhere, and within a year Tylenol has recovered most of its market. That is the reversal: praise that comes after proof, earned by real action, becomes an asset that can carry a company through a disaster. Praise that comes instead of proof is a debt, and the bill always arrives." },
        ],
      },
      {
        n: 14, title: "What Hunger Built, Comfort Spends", opener: "The House of Gucci", place: "Milan, 1995",
        judgment: "The first generation builds with its hands, the second keeps with its name, the third spends with its comfort. Every fortune starts the countdown on the day it is made.",
        eras: ["Florence, 1494", "Milan, 1995", "Tokyo, 2006"],
        story: "Guccio Gucci opened a small leather shop in Florence in 1921. His sons made the name famous across the world. His grandsons went to war with each other in courtrooms, and in 1993 the last of them, Maurizio, sold the family's final share of the company. On 27 March 1995 a hired gunman shot Maurizio dead on the steps of his office in Milan. In 1998 his former wife was convicted of arranging it. Within three generations, the family had lost both the company and one another.",
        key: "Seeking: remember the hunger that built you, and build it into the people who will inherit what you build. Keeping: make your heirs earn their place, or the comfort you give them will spend what you won.",
        sections: [
          { name: "The Law", text: "What hunger built, comfort spends. New York, 1877. Cornelius Vanderbilt, who began as a teenager ferrying passengers across New York harbour in a small boat, dies the richest man in America, leaving about a hundred million dollars, more than the United States Treasury held at the time. His son William doubles it. Then the grandchildren begin to spend: the mansions of Fifth Avenue, the marble summer cottages of Newport, one of them with seventy rooms, the yachts, the balls. By the twentieth century the mansions are being sold and demolished one by one. One of the family's own historians later wrote that when a hundred and twenty descendants gathered at Vanderbilt University in 1973, not one of them was a millionaire. The money had not been stolen. It had simply been lived in." },
          { name: "Judgment", text: "The first generation builds with its hands, the second keeps with its name, the third spends with its comfort. Florence, November 1494. The Medici bank, once the richest in Europe, built by Giovanni di Bicci and expanded by his son Cosimo, has been shrinking for years under Cosimo's grandson Lorenzo the Magnificent, a brilliant poet and statesman who paid little attention to the business. Branches in London and Bruges have failed after bad loans to kings. Lorenzo dies in 1492. His son Piero, called the Unfortunate, hands fortresses to the invading French king without a fight; the people of Florence rise, and in November 1494 the Medici are driven out of the city and their bank is closed. Lancashire mill workers had a saying for it centuries later: clogs to clogs in three generations." },
          { name: "Transgression", text: "Florence and Milan, 1921 to 1995. Guccio Gucci, who had worked as a porter at the Savoy Hotel in London and admired the luggage of its rich guests, opens a leather goods shop in Florence in 1921. His sons build it: Aldo opens the first American store in New York in 1953, and the double-G logo becomes a symbol of wealth worn by film stars and presidents' wives. By the 1970s the family is at war. Aldo's son Paolo tries to launch his own brand and is fought in court by his father. In 1986, at eighty-one, Aldo is sentenced to a year in an American prison for tax evasion; it is his son who had reported him. Rodolfo's son Maurizio inherits his father's half on his death in 1983, and, backed by the Bahrain-based investment firm Investcorp, takes control of the company in 1989. He spends lavishly on offices, design and his own life; the company loses money. In 1993, out of cash, he sells the last of the family's shares to Investcorp for around 120 million dollars. No Gucci owns any part of Gucci. On the morning of 27 March 1995 a gunman shoots Maurizio dead on the steps of his office on Via Palestro in Milan. In January 1997 his former wife, Patrizia Reggiani, is arrested; the next year she is convicted of hiring the killer and sentenced to twenty-nine years. The brand itself is rescued by outsiders, Domenico De Sole and the designer Tom Ford, and becomes more valuable than ever. The family is no longer part of the story." },
          { name: "Observance", text: "Stockholm, 1856 to today. André Oscar Wallenberg, a naval officer, founds Stockholms Enskilda Bank in 1856. His descendants build around it one of the most powerful business groups in Europe, with stakes in companies such as Ericsson, ABB, AstraZeneca and Saab. The family's motto is Latin: esse, non videri, to be, not to be seen. Each generation's heirs must earn their place, usually through demanding education and years working outside the family business, before they are given responsibility. Much of the wealth is held in foundations that fund research rather than in the family's own pockets. In its fifth and sixth generations, the family still controls the group its ancestor built. It is one of the rare families that found a way to pass on the hunger along with the money." },
          { name: "Interpretation", text: "Ibn Khaldun explained it in the fourteenth century. The first generation lives in hardship and shares a fierce bond; it takes power because it has nothing to lose. The second generation was born to the power but remembers the founders and imitates them. The third has known only comfort; it inherits the habits of wealth without the discipline that made it, and by the fourth generation the dynasty is spent. He estimated the whole cycle at about a hundred and twenty years. The founder cannot pass on his hunger by passing on his money, because the money is exactly what removes the hunger. The children of the Gucci brothers grew up as heirs to a famous name. None of them had stood behind a counter wondering whether a customer would come in. They fought over the name because the name was all they understood." },
          { name: "Parallels", text: "Delhi, 1707 to 1739. When the emperor Aurangzeb dies in 1707, the Mughal Empire covers almost the whole of India and is among the richest states on earth. His successors, raised in the luxury of the imperial harem, are murdered, deposed or reduced to puppets; within thirty years the provinces have broken away. In 1739 the Persian ruler Nader Shah invades, sacks Delhi, massacres tens of thousands and carries home the Peacock Throne and the Koh-i-Noor diamond. Osaka, 2006. Kongō Gumi, a builder of Buddhist temples founded in the year 578, is the oldest continuously operating company in the world, run by the same family for forty generations. In the property boom of the 1980s it borrowed heavily to build ordinary buildings, and when the bubble burst it could not repay. In January 2006, after more than 1,400 years, it is absorbed by a larger construction company. Atlanta and New York, 2000s. Whole fortunes of the American gilded age, the Astors, the Goulds, the Vanderbilts, were spread and spent within a century, while fortunes made by grandfathers who rationed their children's allowances often survived. The pattern is so common that wealth advisers have a rule of thumb for it: most family fortunes are gone by the third generation." },
          { name: "The Cost", text: "For the Gucci family: the company their grandfather founded, its name in the hands of strangers, years of lawsuits between fathers and sons and cousins, a father imprisoned on his son's evidence, and the murder of the last Gucci to run it, arranged, a court found, by his own former wife. For the Medici: their bank and, for eighteen years, their city. For the Vanderbilts: the largest fortune in America, dispersed in less than a century. For the Mughals: India itself. Comfort does not destroy a fortune in a single blow. It spends it, a little at a time, until one day there is nothing left to spend and no one left who remembers how to earn it." },
          { name: "The Record", text: "Verified: the founding of the Gucci shop in Florence in 1921; Aldo Gucci's conviction for tax evasion in 1986; Maurizio Gucci's control of the company from 1989 and the sale of the family's last stake to Investcorp in 1993; his murder on 27 March 1995; Patrizia Reggiani's conviction in 1998. She served about eighteen years and was released in 2016. Disputed: Reggiani's motives and state of mind. Her defence argued that a brain tumour had affected her judgment; she denied ordering the killing for years, and the court found she had paid the gunman through intermediaries. Disputed: the exact price of the 1993 sale, reported at around 120 million dollars, and the exact number of Vanderbilt descendants at the 1973 gathering, which comes from a family member's book." },
          { name: "Keys", text: "For those seeking: first, remember the hunger that built you; it is the most valuable thing you own and the only thing you cannot buy back. Second, build the discipline into your business, its rules, its accounts, its standards, not just into yourself. Third, never confuse the brand with the work that made it. For those keeping: first, make your heirs earn their place: let them work elsewhere, fail, and come back with something of their own. Second, separate ownership from management; the most gifted grandchild is rarely the eldest. Third, settle the succession while you are alive and strong, because what you leave undecided your children will decide in court." },
          { name: "Image", text: "A well dug by a grandfather with his own hands, through rock, in a dry year. His children draw from it carefully and keep it clean. His grandchildren, who have never known thirst, build a fountain on top of it, then a pool, then a garden of thirsty flowers. One summer the water stops. None of them knows where the well is, or how it was dug." },
          { name: "Authority", text: "Ibn Khaldun, the Muqaddimah, 1377: the prestige of a dynasty lasts at most four generations: the builder, the one who knew the builder, the one who imitates, and the one who destroys. \"The man who dies thus rich dies disgraced.\" Andrew Carnegie, The Gospel of Wealth, 1889, who gave away most of his fortune rather than leave it to make his heirs idle." },
          { name: "Reversal", text: "Macedon, 356 to 323 BC. Alexander is born a prince, the son of Philip II of Macedon, the man who built his small border kingdom into the master of Greece. He grows up in a palace, heir to everything. But Philip has him taught by Aristotle, trained with the army from boyhood, and at eighteen gives him command of the cavalry at the battle of Chaeronea, where he leads the charge that breaks the Theban Sacred Band. The heir does not spend his father's power; he multiplies it, from Greece to India, in thirteen years. That is the reversal: comfort spends what hunger built only when the heir is raised in comfort alone. Raise the heir in hardship and responsibility, and the second generation can outdo the first. But note what followed: within a few years of Alexander's death, his own empire was torn apart by his generals, and his son was murdered." },
        ],
      },
      {
        n: 15, title: "Never Seek the Light With Money Made in the Dark", opener: "Pablo Escobar", place: "Bogotá, 1984",
        judgment: "Money made in the dark can buy almost anything except a place in the light. The moment you step forward to be seen, everyone who was not looking starts to look.",
        eras: ["Sicily, 70 BC", "Bogotá, 1984", "Kuala Lumpur, 2015"],
        story: "By 1982 Pablo Escobar was one of the richest men in the world, and he wanted something money alone had not given him: respect. He built houses for the poor of Medellín and won a seat in Colombia's Congress. In August 1983 the justice minister, Rodrigo Lara Bonilla, accused him in public, and a newspaper printed his old arrest photo for drug trafficking. In January 1984 he was forced out of Congress. In April Lara Bonilla was shot dead. It was the start of a war against the state that ended with Escobar's body on a Medellín rooftop.",
        key: "Seeking: if your money is not clean, the light is the most dangerous place you can stand. Keeping: if you want to be seen, first become someone who can survive being looked at.",
        sections: [
          { name: "The Law", text: "Never seek the light with money made in the dark. Kuala Lumpur and New York, 2009 to 2015. Low Taek Jho, known as Jho Low, a young Malaysian financier, helps set up 1MDB, a state investment fund. Billions of dollars flow out of it. American prosecutors later say that about four and a half billion dollars was stolen. Low does not hide the money. He throws parties in Las Vegas and Saint-Tropez attended by film stars, buys a superyacht, art by Monet and van Gogh, and helps finance the Hollywood film The Wolf of Wall Street, about a fraudster. Journalists, reading about the parties, start asking where a young man with no famous business got such money. In 2015 the Sarawak Report and The Wall Street Journal publish the trail. In 2016 the United States Justice Department files to seize the assets. In 2018 Malaysia's prime minister Najib Razak loses an election and is later imprisoned. Low becomes a fugitive. Had he spent the money quietly, he might have kept it for years. He spent it in the light." },
          { name: "Judgment", text: "Money made in the dark can buy almost anything except a place in the light. New York, 1985 to 1992. John Gotti takes over the Gambino crime family after having its boss shot dead outside a Manhattan steakhouse in December 1985. Unlike the old bosses, who wore grey and avoided cameras, Gotti wears thousand-dollar suits, waves to crowds outside court and holds fireworks parties for his neighbourhood. The newspapers call him the Dapper Don, then, after three acquittals, the Teflon Don. The attention brings the FBI's full attention; agents bug the apartment above his club, and record him talking business. In 1991 his underboss, Sammy Gravano, turns witness. In April 1992 Gotti is convicted of murder and racketeering, and dies in prison in 2002. The old bosses had understood something he did not: in their business, fame is evidence." },
          { name: "Transgression", text: "Medellín and Bogotá, 1976 to 1993. Pablo Escobar, born on 1 December 1949 to a farmer and a schoolteacher outside Medellín, is arrested in 1976 with about thirty-nine pounds of cocaine; the case and its files disappear. By the early 1980s his Medellín cartel supplies most of the cocaine reaching the United States, and he is among the richest men on earth. He buys a vast estate, Hacienda Nápoles, with a private zoo of hippos, giraffes and elephants. And he wants more than money. He pays for football pitches and lighting in poor neighbourhoods and starts a programme to build hundreds of houses for families living on a rubbish dump; the neighbourhood is named Barrio Pablo Escobar. In 1982 he is elected as an alternate member of the House of Representatives. In August 1983 the new justice minister, Rodrigo Lara Bonilla, denounces him in Congress as a drug trafficker, and the newspaper El Espectador reprints the story and photograph of his 1976 arrest. The United States cancels his visa. In January 1984 he is forced to give up his seat. In March police destroy his cartel's jungle laboratory complex, Tranquilandia. On 30 April 1984 gunmen on a motorcycle kill Lara Bonilla in Bogotá. Escobar's war on the state begins: El Espectador's editor, Guillermo Cano, is murdered in December 1986; the presidential favourite Luis Carlos Galán is assassinated in August 1989; in November 1989 a bomb destroys Avianca Flight 203 in the air, killing 107 people. In 1991 he surrenders to a prison he has built himself, La Catedral, escapes in July 1992, and is hunted down. On 2 December 1993, the day after his forty-fourth birthday, he is shot dead on a rooftop in Medellín." },
          { name: "Observance", text: "Miami Beach, 1983. Meyer Lansky dies in bed at the age of eighty. For half a century he had been called the financial genius of American organised crime, building casinos in Havana, Las Vegas and the Bahamas, and moving money for the mob through banks in Switzerland. Yet he never sought a title, a public office or a famous mansion. He lived in a modest apartment, walked his dog on the beach, dressed plainly and avoided photographers. The government spent decades trying to convict him; in 1973 he was acquitted of tax evasion, and he was never imprisoned for his crimes. Whatever one thinks of the man, he understood the rule perfectly: money made in the dark is safest when it never steps into the light." },
          { name: "Interpretation", text: "There is a deep human hunger behind this law. People who make great fortunes outside the law want what other rich men have: respect, a name, a seat at the table, the gratitude of the poor. Money can buy the houses and the parties. But the moment the money steps into public life, it asks to be judged by public rules: where did this come from? Escobar could have been the hidden king of Medellín for years. He chose to stand in Congress, where an honest minister could point at him in front of the nation, and where the newspapers could print his old police photograph. The fame he bought turned the state's attention from a problem it could ignore into an insult it could not. Once Lara Bonilla had named him in public, Escobar had only two choices: retreat into the dark, or kill the light. He chose to kill it, and it cost him everything." },
          { name: "Parallels", text: "Sicily and Rome, 73 to 70 BC. Gaius Verres, Roman governor of Sicily, loots the island for three years, stripping temples and private houses of their statues and paintings, and plans to use his fortune to buy a political career in Rome. The Sicilians hire a young lawyer named Cicero to prosecute him. Cicero gathers so much evidence that after the first part of the trial Verres flees into exile, taking his art with him. London, June 2016. Ruja Ignatova, the self-styled Cryptoqueen, presents her digital currency, OneCoin, to thousands of cheering investors at Wembley Arena, in a ball gown under the lights. OneCoin had no real blockchain, and investors around the world had put in about four billion dollars. In October 2017 she boards a flight from Sofia to Athens and vanishes. In 2022 she is added to the FBI's Ten Most Wanted list. Paris and Malibu, 2004 to 2017. Teodoro Nguema Obiang Mangue, son of the long-ruling president of Equatorial Guinea, earns an official salary of a few thousand dollars a month as a government minister. He buys a mansion in Malibu, a 101-room house on the Avenue Foch in Paris, a private jet, a fleet of supercars and a crystal-covered glove worn by Michael Jackson. French investigators, following anti-corruption complaints, raid the Paris house in 2012 and carry away his cars. In October 2017 a Paris court convicts him in his absence of laundering embezzled public money, and orders the Paris mansion confiscated." },
          { name: "The Cost", text: "For Escobar: his life, at forty-four, and the lives of thousands of Colombians: judges, police officers, journalists, politicians and ordinary people killed in his war against the state. For his family: years of exile; his widow and children fled to Argentina under new names. For Colombia: a decade of terror. His zoo was abandoned; its hippos escaped into the rivers, and their descendants still roam the Magdalena valley today. For Gotti: life in prison. For Jho Low: life as a fugitive. For Verres: Rome. The light they sought was real. It simply showed everyone where to look." },
          { name: "The Record", text: "Verified: Escobar's arrest in 1976; his election as an alternate member of Congress in 1982; Lara Bonilla's accusations and El Espectador's reprint of the arrest photograph in August 1983; his loss of his seat in January 1984; Lara Bonilla's murder on 30 April 1984; the murder of Guillermo Cano on 17 December 1986 and of Luis Carlos Galán on 18 August 1989; the bombing of Avianca Flight 203 on 27 November 1989; his surrender in June 1991, escape in July 1992 and death on 2 December 1993. Disputed: the famous story that Escobar offered to pay off Colombia's foreign debt in exchange for immunity; it is repeated everywhere but has never been documented. Disputed: who fired the shot that killed him. The police unit that cornered him claimed it; members of his family have said he shot himself." },
          { name: "Keys", text: "For those seeking: first, if your money is not clean, the light is the most dangerous place you can stand; every office, award and photograph is an invitation to look. Second, before you ask the public for anything, ask what the public will find if it looks. Third, clean the past before you build the future on it, or do not build in public at all. For those keeping: first, if you want to be seen, first become someone who can survive being looked at. Second, when a respected person names you in public, never answer with force; answering the light with violence makes you the story forever. Third, fame is not protection; for anyone with secrets, it is the opposite." },
          { name: "Image", text: "A thief who buys a lantern. For years he has moved through the city at night, unseen and rich. Now he wants people to see how rich he is, so he carries a great lantern through the streets, lighting up his fine clothes. The crowd admires the clothes. The watchmen admire the lantern, and follow it home." },
          { name: "Authority", text: "Honoré de Balzac, Le Père Goriot, 1835: the secret of great fortunes without apparent cause is a crime that has been forgotten, because it was properly done. Notice the words: forgotten, and properly done. And from Proverbs 10:2, King James Version: treasures of wickedness profit nothing." },
          { name: "Reversal", text: "Canton and New York, 1830s to 1930s. Warren Delano II, an American merchant, makes a fortune in China in the 1830s and 1840s, much of it in the opium trade, which was illegal in China. He comes home, invests in railways and coal, and becomes a pillar of New York society. His grandson, Franklin Delano Roosevelt, becomes President of the United States. Many great respectable fortunes of the world began with trades their founders would not have wanted examined. That is the reversal, and it is a cold one: money from the dark can reach the light, but only after it has been quiet for a generation or more, cleaned by legitimate business and time, and never in the hands of the man who made it. The founder must stay in the shadow. Only his grandchildren may stand in the sun." },
        ],
      },
    ],
  },
  {
    n: 4, title: "The Sword", opens: "Mar 2027",
    line: "Fear, force and war, and the day they turn on their master.",
    laws: [
      {
        n: 16, title: "Fear Rules Only Until It Is Tested", opener: "Idi Amin", place: "Kampala, 1979",
        judgment: "Fear keeps people still. It does not make them fight for you. The first time your power must be defended rather than displayed, you discover how many people were only pretending.",
        eras: ["Rome, AD 41", "Phnom Penh, 1979", "Kampala, 1979"],
        story: "For eight years Idi Amin ruled Uganda by terror. Tens of thousands, perhaps hundreds of thousands, of Ugandans were killed; no one dared oppose him. In 1978 he invaded neighbouring Tanzania. Tanzania struck back with its own army and Ugandan exiles, and Amin's soldiers, who had been so frightening to unarmed civilians, ran. On 11 April 1979 Kampala fell. Amin fled to Libya, then Saudi Arabia, where he lived out his life in exile.",
        key: "Seeking: if people follow you only because they fear you, you have not yet built power, only silence. Keeping: before you test your strength against a real enemy, test it against your own people's willingness to fight for you.",
        sections: [
          { name: "The Law", text: "Fear rules only until it is tested. Cambodia, 1975 to 1979. The Khmer Rouge under Pol Pot empty the cities, abolish money, schools and religion, and drive the whole population into labour camps in the countryside. Anyone suspected of disloyalty, education or foreign contact can be killed; in under four years around a fifth of the population, perhaps 1.7 million people or more, die from execution, starvation and disease. The regime's terror is total. Its leaders believe this makes them strong, and they launch raids across the border into Vietnam, massacring villagers. On 25 December 1978 the Vietnamese army invades. The Khmer Rouge soldiers, so terrifying to the unarmed, cannot hold. On 7 January 1979, about two weeks later, Phnom Penh falls. Pol Pot flees to the jungle on the Thai border. A regime that had controlled every Cambodian through fear collapsed in a fortnight when it met an army that did not fear it." },
          { name: "Judgment", text: "Fear keeps people still; it does not make them fight for you. Rome, 24 January AD 41. The emperor Caligula has ruled for almost four years through humiliation and terror: senators forced to run beside his chariot, executions for jokes, threats to make his horse a consul. The officers of his own guard are among those he mocks most cruelly; one of them, Cassius Chaerea, is given obscene passwords to repeat in front of his men. At the Palatine Games, in a narrow passage under the palace, Chaerea and other officers of the guard stab Caligula to death, along with his wife and infant daughter. The men who had been closest to his terror were the first to test it, and found it was nothing but a man with no one willing to defend him." },
          { name: "Transgression", text: "Kampala, 25 January 1971 to 11 April 1979. Idi Amin, commander of Uganda's army, seizes power while President Milton Obote is abroad at a Commonwealth summit in Singapore. Crowds cheer at first. Within months, soldiers from tribes thought loyal to Obote are massacred in their barracks. In August 1972 Amin gives Uganda's Asian community, tens of thousands of people who run much of its trade, ninety days to leave the country; their shops and businesses are handed to his soldiers and friends, and the economy collapses. Ministers, judges, the chief justice, the vice-chancellor of the university and the Anglican archbishop, Janani Luwum, disappear or are found dead. Estimates of those killed under his rule range from about a hundred thousand to half a million. In July 1976 Israeli commandos fly into Entebbe airport and rescue hijacked hostages whom Amin had been protecting, killing dozens of his soldiers on the tarmac; the world laughs at him. In October 1978, looking for a victory, Amin sends troops across the border into Tanzania and annexes a strip of its land, the Kagera Salient. Tanzania's president, Julius Nyerere, mobilises his army and joins it to Ugandan exiles. Gaddafi sends Libyan troops to help Amin. It is not enough. Amin's army, terrifying to civilians and unpaid for months, melts away town after town. On 11 April 1979 Kampala falls and crowds dance in the streets. Amin flies to Libya, and later to Saudi Arabia, where he lives quietly in Jeddah until his death on 16 August 2003." },
          { name: "Observance", text: "Jerusalem, 2 October 1187. Salah al-Din, known in the West as Saladin, Sultan of Egypt and Syria, takes Jerusalem from the Crusaders after a short siege. Eighty-eight years earlier, in 1099, the Crusaders had taken the city by slaughtering its Muslim and Jewish inhabitants. Saladin does not take revenge. He allows the Christians to ransom themselves, frees thousands who cannot pay, lets them leave with their goods, and allows Christian pilgrims to keep visiting their holy places. His enemies wrote about him with admiration for centuries. When the Third Crusade came, led by Richard the Lionheart, Saladin's armies held most of what he had won, and the treaty of 1192 left Jerusalem in his hands. He ruled by strength, but his strength was trusted rather than merely feared, and men fought for him because they believed in him." },
          { name: "Interpretation", text: "Fear and loyalty look the same in peacetime. In both cases people obey, bow and keep quiet. The difference appears only in a crisis, when the ruler needs people to take risks for him: to fight, to stand firm, to report the truth, to stay at their posts when it is dangerous. Loyal people take those risks. Frightened people calculate. And a frightened army, faced with an enemy that frightens it more than its own commander does, simply runs. Amin's soldiers were very good at terrorising civilians who could not fight back. Against an army, they discovered that they had no reason to die for him. Machiavelli wrote that it is safer to be feared than loved, but in the same chapter he warned that a prince must above all avoid being hated. Amin forgot the warning and kept only the advice." },
          { name: "Parallels", text: "Greece, 28 October 1940. Benito Mussolini, who has boasted for years of eight million bayonets, sends his army from Albania into Greece expecting a quick victory. Within weeks the outnumbered Greeks have driven the Italians back into Albania; Hitler has to send German troops to rescue his ally in the spring. Mussolini's regime, built on fear and display, had never been tested by a real enemy. Buenos Aires and the Falklands, 2 April to 14 June 1982. Argentina's military junta, which has made thousands of its own citizens disappear in the Dirty War, invades the British-held Falkland Islands to win popularity. Britain sends a fleet across the world. On 14 June the Argentine garrison at Port Stanley surrenders. Three days later the junta's leader, General Leopoldo Galtieri, is forced to resign, and the next year Argentina returns to democracy. A government that had terrified its own people for six years collapsed within weeks of losing a war." },
          { name: "The Cost", text: "For Amin: his country, and twenty-four years of exile; he never returned to Uganda. For Uganda: an economy destroyed by the expulsion of its traders, a generation of its educated class murdered, and years of civil war that followed his fall. For Pol Pot: his regime, and in the end his life, under house arrest by his own former comrades in 1998. For Caligula: his life, and the lives of his wife and daughter. For Galtieri: power, and a prison sentence for his conduct of the war. A regime of fear always pays twice: once for the fear it spreads, and once when it discovers that fear cannot fight." },
          { name: "The Record", text: "Verified: Amin's coup of 25 January 1971; the expulsion of the Asians announced in August 1972; the murder of Archbishop Janani Luwum in February 1977; the Entebbe raid of 4 July 1976; the invasion of the Kagera Salient in late 1978; the fall of Kampala on 11 April 1979; his death in Jeddah on 16 August 2003. Disputed: the number of people killed under his rule. Amnesty International and others gave estimates from about a hundred thousand to three hundred thousand; some exile groups claimed half a million. Disputed: the many lurid stories told about Amin, including cannibalism, which have never been proven and which he denied; much of his reputation abroad was built from rumour as well as fact. Disputed: the Khmer Rouge death toll, which researchers estimate at between about 1.5 and 2.2 million." },
          { name: "Keys", text: "For those seeking: first, if people follow you only because they fear you, you have not yet built power, only silence. Second, give the people under you a reason to want you to win, not just a reason to fear your anger. Third, never confuse obedience in peacetime with loyalty in a crisis. For those keeping: first, before you test your strength against a real rival, test whether your own people would take a risk for you. Second, those closest to your anger are the first to test it; treat your inner circle with respect, even when you rule others with fear. Third, never start a fight abroad to cover weakness at home; the fight will reveal the weakness." },
          { name: "Image", text: "A scarecrow in a field. For a whole season the birds keep away from it, and the farmer believes his field is guarded. Then one morning a crow lands on its shoulder, looks around, and calls the others. By noon the field is black with birds." },
          { name: "Authority", text: "\"Fear is a poor guardian of lasting power; goodwill keeps faith for ever.\" Cicero, On Duties, 44 BC. Machiavelli, The Prince, chapter 17, 1513: it is safer to be feared than loved, if one must choose, but a prince must make himself feared in such a way that, if he does not win love, he avoids hatred." },
          { name: "Reversal", text: "Moscow, 1941 to 1945. Stalin's regime had ruled through terror: millions sent to labour camps, much of the army's officer corps shot in the purges of 1937 and 1938. When Germany invaded in June 1941, whole Soviet armies surrendered, and in some regions villagers greeted the Germans with bread and salt. But German terror proved worse than Stalin's, and Stalin changed his message. He spoke of the motherland, not the party; he reopened churches in 1943, revived old Russian military heroes and called the war the Great Patriotic War. Soviet soldiers, at a cost of millions of lives, fought their way to Berlin. That is the reversal: a regime of fear survived its test only when it gave its people something they would fight for that was larger than fear, and when the enemy was even more frightening. Fear alone did not win that war. Love of country did." },
        ],
      },
      {
        n: 17, title: "Never Open a Second Front", opener: "Adolf Hitler", place: "The invasion of Russia, 1941",
        judgment: "Strength divided is weakness doubled. Every new enemy you take on before the first is beaten does not add to your glory; it subtracts from your survival.",
        eras: ["Syracuse, 413 BC", "Russia, 1941", "Medellín, 1988"],
        story: "In June 1941, with Britain still undefeated in the west, Adolf Hitler sent more than three million soldiers into the Soviet Union. Six months later, four days after Japan attacked Pearl Harbor, he declared war on the United States as well. Germany was now fighting the British Empire, the Soviet Union and America at once. In February 1943 his army at Stalingrad surrendered. On 30 April 1945, with Soviet soldiers a few hundred yards from his bunker in Berlin, he shot himself.",
        key: "Seeking: win one war before you start the next; momentum is not the same thing as strength. Keeping: when you are already fighting, every new enemy is a gift to the old one.",
        sections: [
          { name: "The Law", text: "Never open a second front. Athens, 415 BC. Athens and Sparta have been at war, on and off, for sixteen years. In a pause in the fighting, the Athenian assembly, swept up by the young and brilliant Alcibiades, votes to send a great fleet to conquer Sicily, on the other side of the Greek world. The cautious general Nicias warns against it; the assembly gives him more ships instead, and puts him in command. Alcibiades, recalled to face charges, defects to Sparta and advises the Spartans how to hurt Athens. In 413 BC the entire expedition is destroyed at Syracuse: the fleet trapped in the harbour, the army caught on its retreat, Nicias executed, thousands of Athenians sold as slaves or left to die in the stone quarries. Sparta, meanwhile, has restarted the war at home. Athens never recovers, and in 404 BC it surrenders to Sparta. Thucydides, who lived through it, saw the Sicilian expedition as the moment Athens destroyed itself." },
          { name: "Judgment", text: "Strength divided is weakness doubled. Berlin, January 1917. Germany has been fighting France and Britain in the west and Russia in the east for two and a half years. Its leaders decide that unrestricted submarine warfare, sinking any ship near Britain, including American ones, will starve Britain out before America can matter. In the same month the German foreign minister sends a telegram to Mexico proposing an alliance against the United States; the British intercept it and pass it to Washington. On 6 April 1917 the United States declares war on Germany. By the summer of 1918 American soldiers are arriving in France at the rate of about ten thousand a day. In November 1918 Germany asks for an armistice, and Kaiser Wilhelm II flees to the Netherlands. A nation already fighting on two fronts had added a third enemy, the richest in the world." },
          { name: "Transgression", text: "Germany, 1940 to 1945. By the summer of 1940 Hitler is master of Europe from Norway to the Pyrenees. Only Britain fights on. The German air force fails to win control of the skies over England, and on 17 September 1940 Hitler postpones the invasion. Instead of finishing the war in the west, he turns east. On 18 December he signs Directive 21: Operation Barbarossa. At dawn on 22 June 1941, more than three million German and allied soldiers cross into the Soviet Union on a front of almost three thousand kilometres. The early victories are enormous: whole Soviet armies encircled, millions of prisoners taken. But the country is vast, the roads dissolve into mud in autumn, and the winter comes early. On 5 December, within sight of Moscow, the Soviets counterattack. Two days later Japan attacks Pearl Harbor. On 11 December, though no treaty requires it, Hitler declares war on the United States. Germany is now at war with the three most powerful nations on earth at once, on two fronts that will become three. On 2 February 1943 the remains of the Sixth Army surrender at Stalingrad: about ninety-one thousand men march into captivity, and only about five thousand will ever come home. On 6 June 1944 Allied armies land in Normandy. On 30 April 1945, in his bunker beneath the ruins of Berlin, Hitler shoots himself." },
          { name: "Observance", text: "Berlin, 1871 to 1890. Otto von Bismarck, chancellor of the new German Empire, spends twenty years making sure Germany never has to fight on two fronts. France, defeated in 1871, wants revenge, so Bismarck keeps France isolated and keeps Russia friendly at almost any cost. In 1887, when Russia and Austria quarrel, he signs a secret Reinsurance Treaty with Russia, so that Germany will never face France and Russia together. He refuses colonial adventures that might anger Britain, and says that the whole of the Balkans is not worth the bones of a single Pomeranian soldier. In March 1890 the young Kaiser Wilhelm II forces him to resign. That same year Wilhelm lets the Reinsurance Treaty lapse. Within four years Russia and France are allies, and in 1914 Germany goes to war on exactly the two fronts Bismarck had spent his life avoiding." },
          { name: "Interpretation", text: "A second front feels like confidence. You are winning on the first, your momentum seems unstoppable, and the new enemy looks weaker than the one you are already beating. But every army, company and organisation has limits: of men, money, attention and time. A second front does not just add a second enemy. It forces you to divide everything you have, it gives both enemies a reason to help each other, and it removes the one advantage you most need, the ability to concentrate your whole strength in one place at one time. Hitler opened his second front because he believed the Soviet Union would collapse in weeks. He opened the third because he despised America and assumed Japan would keep it busy. He had confused victories with victory. The battles he won only made the war larger." },
          { name: "Parallels", text: "Tokyo, 1941. Japan has been fighting a vast, exhausting war in China since 1937, with no end in sight. Cut off from American oil, its leaders decide to seize the oil fields of the Dutch East Indies, and to strike the American fleet first. On 7 December 1941 their aircraft attack Pearl Harbor. Japan is now fighting China and the United States at once. On 6 and 9 August 1945 atomic bombs destroy Hiroshima and Nagasaki, and on 2 September Japan signs its surrender. Medellín, 1988 to 1993. Pablo Escobar is already at war with the Colombian state. On 13 January 1988 a car bomb explodes outside his Monaco building in Medellín, where his family is sleeping; he blames the Cali cartel, and opens a second war, against his former partners. Then a third, against members of his own organisation he suspects of betrayal, whom he has killed inside his prison in 1992. His enemies combine: the state, the Cali cartel, the families of his victims and his own former men, who form the vigilante group Los Pepes. He cannot fight all of them, and on 2 December 1993 he is killed." },
          { name: "The Cost", text: "For Hitler: his life, his regime and his country, which was occupied, divided for forty-five years and stripped of a quarter of its territory. For the world: a war that killed some seventy to eighty-five million people, among them around twenty-seven million Soviet citizens and six million Jews murdered in the Holocaust. For Athens: its empire, its walls and its independence. For Japan: its empire and two cities. For Escobar: his life. The second front is never the cost of one more war. It is the cost of losing the first one as well." },
          { name: "The Record", text: "Verified: the postponement of the invasion of Britain on 17 September 1940; Directive 21 of 18 December 1940; the invasion of 22 June 1941; the Soviet counterattack before Moscow on 5 December 1941; Hitler's declaration of war on the United States on 11 December 1941; the surrender at Stalingrad on 2 February 1943; Hitler's suicide on 30 April 1945, confirmed by witnesses in the bunker and Soviet investigators. Disputed: the claim, made by some writers, that Stalin was about to attack Germany first and that Hitler's invasion was preventive. Most historians who have studied the Soviet archives reject it. Disputed: the total death toll of the war, for which estimates differ by millions." },
          { name: "Keys", text: "For those seeking: first, win one war before you start the next; momentum is not the same thing as strength. Second, before you take on a new rival, ask who benefits most from your being distracted. Third, if you must fight more than one enemy, make sure they cannot help each other. For those keeping: first, when you are already in a fight, every new enemy is a gift to the old one. Second, keep at least one powerful neighbour friendly, even at a cost, as Bismarck did with Russia. Third, never declare war on someone who has not yet declared it on you, simply because you assume you will have to fight them later." },
          { name: "Image", text: "A man holding back a heavy door with both hands while someone pushes from the other side. He is winning; the door is almost closed. Then he hears a knock at the window behind him, and takes one hand off the door to answer it." },
          { name: "Authority", text: "\"There is no instance of a country having benefited from prolonged warfare.\" Sun Tzu, The Art of War, as translated by Lionel Giles in 1910. And from Bismarck, to the German parliament in 1876: the whole of the Balkans is not worth the healthy bones of a single Pomeranian grenadier." },
          { name: "Reversal", text: "Washington, 1941 to 1945. The United States fights the Second World War on two vast fronts at once, against Germany and Italy in Europe and against Japan across the Pacific, and wins both. It can do so because of two things Hitler lacked. First, overwhelming resources: by 1944 American factories are building an aircraft roughly every five minutes, and producing more weapons than all the Axis powers combined. Second, a clear priority: Roosevelt and Churchill agree to defeat Germany first, and fight Japan with whatever is left until then. That is the reversal: a second front can be survived, and even won, but only by someone whose strength far exceeds the combined strength of their enemies, and who decides in advance which war comes first. Few who open a second front have either. Most only believe they do." },
        ],
      },
      {
        n: 18, title: "Terror Unites Your Enemies", opener: "The Arellano Félix brothers", place: "Guadalajara, 1993",
        judgment: "Fear can scatter your enemies for a season. Indiscriminate terror does the opposite: it gives people who hate each other a reason to stand together, and that reason is you.",
        eras: ["Nineveh, 612 BC", "Guadalajara, 1993", "Mosul, 2017"],
        story: "The Arellano Félix brothers ran the Tijuana cartel with a cruelty that frightened even other traffickers. On 24 May 1993 their gunmen opened fire in the car park of Guadalajara's airport, hunting a rival. Among the dead was Cardinal Juan Jesús Posadas Ocampo, the Archbishop of Guadalajara, shot fourteen times in his car. Overnight, the Catholic Church, the Mexican government, the United States and the brothers' own rivals had one enemy in common. Within a decade one brother was dead and the others were in prison.",
        key: "Seeking: if you use force, use it rarely, precisely and with a clear way out for those who submit. Keeping: never strike the innocent, the sacred or the admired; it turns your enemies' quarrel with each other into a common cause against you.",
        sections: [
          { name: "The Law", text: "Terror unites your enemies. Nineveh, 612 BC. For three centuries the kings of Assyria have ruled the Near East by terror, and they boast of it in stone: carved reliefs in their palaces show captured enemies flayed alive, impaled on stakes, whole peoples deported in long columns to the far ends of the empire. Their enemies hate each other almost as much as they hate Assyria: Babylonians, Medes from the Iranian plateau, Scythians from the north. Terror keeps them divided and afraid for generations. Then, after the death of the last great Assyrian king, Ashurbanipal, the Babylonians under Nabopolassar and the Medes under Cyaxares make an alliance. In 612 BC their combined armies besiege Nineveh, the greatest city in the world, and after three months they break in and burn it. Within a few years the Assyrian empire has vanished so completely that, two centuries later, the Greek soldier Xenophon marched past the ruins of Nineveh and did not know what city it had been." },
          { name: "Judgment", text: "Indiscriminate terror gives people who hate each other a reason to stand together. Iraq and Syria, 2014 to 2019. In June 2014 the group calling itself Islamic State seizes Mosul, Iraq's second city, and declares a caliphate. It beheads hostages on camera, enslaves Yazidi women, massacres prisoners and destroys ancient monuments, and it boasts of all of it online. By doing so it achieves something no diplomat could: it puts the United States, Iran, Russia, the Iraqi army, Kurdish fighters, Syrian rebels and the Syrian government all on the same side. Its enemies hated each other, and some kept fighting each other even while they fought it. But in July 2017 Mosul is retaken; in October, its capital, Raqqa; and in March 2019 its last scrap of territory, the village of Baghouz, falls." },
          { name: "Transgression", text: "Tijuana and Guadalajara, 1989 to 2006. After the arrest of Miguel Ángel Félix Gallardo in 1989, his nephews, the Arellano Félix brothers, take over the trafficking routes through Tijuana into California. Benjamín, the eldest, is the strategist; Ramón, the enforcer, is known for his violence; there are seven brothers and four sisters in all, several of them in the business. They recruit young men from wealthy Tijuana families as gunmen, and they kill freely: rivals, police, prosecutors and journalists. In 1988 a co-founder of the Tijuana weekly Zeta, Héctor Félix Miranda, is murdered, and in 1997 their gunmen nearly kill its editor, Jesús Blancornelas. In their war with the Sinaloa traffickers led by El Chapo Guzmán, they send gunmen to Guadalajara. On 24 May 1993, in the car park of the international airport, gunmen open fire on a white Grand Marquis. Inside is Cardinal Juan Jesús Posadas Ocampo, Archbishop of Guadalajara, arriving to meet the papal nuncio. He is killed with six others. The gunmen then walk onto a scheduled flight to Tijuana, which is held at the gate for them. The Church, the state and the public are united in fury. Within weeks El Chapo, the rival the shooters were hunting, is arrested in Guatemala; the government turns on the Arellanos too. On 10 February 2002 Ramón is shot dead by police in Mazatlán. On 9 March 2002 Benjamín is arrested in Puebla. Brother after brother is captured or killed. In 2011 Benjamín is extradited to the United States and in 2012 he is sentenced to twenty-five years." },
          { name: "Observance", text: "Babylon, October 539 BC. Cyrus the Great of Persia, who has already conquered the Medes and the kingdom of Lydia, takes Babylon, the greatest city of its age, almost without a fight. He does not burn it, flay its nobles or carve boasts of slaughter on its walls. He enters as a liberator, honours the local god Marduk, keeps much of the administration in place, and lets the peoples the Babylonians had deported, among them the Jews, return to their homelands and rebuild their temples; a clay cylinder in his name, found in Babylon in 1879, records his policy. The book of Isaiah calls him the Lord's anointed. Cyrus built the largest empire the world had yet seen, and he built it largely by making it easier to surrender to him than to fight. His enemies had no reason to unite against him, because he gave them better reasons to join him." },
          { name: "Interpretation", text: "Targeted force sends a message to one person: do not cross me. Indiscriminate terror sends a message to everyone: no one is safe. The first divides your enemies, because each one calculates his own interest. The second unites them, because now everyone's interest is the same: to destroy you before you destroy them. Terror also has a way of escalating beyond its author's control. The Arellanos' gunmen were not sent to kill a cardinal. But a group that kills casually will, sooner or later, kill someone who matters to millions, and on that day it loses the one advantage criminals most depend on: that the people who might hunt them are busy, divided or indifferent. After Guadalajara, no one in Mexico was indifferent." },
          { name: "Parallels", text: "Medellín, 1993. Pablo Escobar's bombing campaign, which killed hundreds of ordinary Colombians in streets, shopping centres and on an airliner, gives his enemies a reason to work together that nothing else could have. In January 1993 a group calling itself Los Pepes, People Persecuted by Pablo Escobar, begins killing his lawyers, accountants and relatives and burning his properties. It is made up of his rivals in the Cali cartel, former members of his own organisation and right-wing paramilitaries, and investigators have long reported that it shared information with the police unit hunting him. By December he is dead. Tamaulipas, August 2010. Los Zetas, the former soldiers who had broken away from the Gulf cartel, massacre seventy-two migrants from Central and South America at a ranch in San Fernando, apparently for refusing to work for them. Their cruelty drives rival cartels into a loose alliance against them and focuses the Mexican and American governments on them as never before. In October 2012 their leader, Heriberto Lazcano, is killed by Mexican marines; in July 2013 his successor, Miguel Ángel Treviño, is captured. The organisation splinters." },
          { name: "The Cost", text: "For the Arellano Félix brothers: Ramón dead at thirty-seven; Benjamín, Francisco Javier, Francisco Rafael and Eduardo captured and imprisoned in Mexico or the United States; their cartel broken into rival factions that went to war with each other. For Tijuana: years of killings as the factions fought over what was left. For the families of the dead at Guadalajara airport: decades without a full answer. For Assyria: its name nearly erased from history. For Islamic State: its territory, its leaders and its so-called caliphate. Terror is cheap to begin. Its full price is presented later, all at once, by everyone it has frightened." },
          { name: "The Record", text: "Verified: the killing of Cardinal Posadas Ocampo and six others at Guadalajara airport on 24 May 1993; El Chapo's arrest in Guatemala on 9 June 1993; the death of Ramón Arellano Félix in Mazatlán on 10 February 2002 and the arrest of Benjamín on 9 March 2002; Benjamín's extradition in 2011 and his sentence of twenty-five years in 2012. Disputed: whether the cardinal was killed by mistake. The official Mexican finding was that the gunmen confused his car with El Chapo's. The Archdiocese of Guadalajara and some investigators have argued that he was a deliberate target; the case has been reopened more than once and remains contested. Disputed: the extent of official involvement with Los Pepes, which American and Colombian documents released over the years have pointed to, and which those involved denied." },
          { name: "Keys", text: "For those seeking: first, if you must use force, use it rarely, precisely and against those who threaten you directly, never against bystanders. Second, always leave your rivals a way to surrender or step aside; a cornered enemy fights with every friend he can find. Third, never let your enforcers decide for you who the enemy is. For those keeping: first, never strike the innocent, the sacred or the admired; it turns your enemies' quarrels with each other into a common cause against you. Second, watch your rivals' relations with each other more closely than your relations with them; the day they start talking, you are already in danger. Third, cruelty used for display is a gift to every enemy who wants a reason to unite." },
          { name: "Image", text: "Two dogs fighting in a yard, each trying to tear the other apart. A man walks in and kicks them both. For a moment they stop. Then they turn, together, and look at him." },
          { name: "Authority", text: "\"They make a desert and call it peace.\" Tacitus, Agricola, around AD 98, putting the words in the mouth of Calgacus, a chieftain rallying the tribes of Caledonia, peoples who had fought each other for generations, to unite against Rome. And Machiavelli, The Prince, chapter 8: cruelties must be done all at once, and not repeated, so that people feel them less and forget them sooner; cruelties that grow over time unite those who suffer them." },
          { name: "Reversal", text: "Central Asia, 1219 to 1221. Genghis Khan invades the Khwarazmian Empire, whose governor had murdered his envoys and merchants. His method is terror, but terror with a rule everyone understands: a city that opens its gates is spared and taxed; a city that resists is destroyed and its people killed, as at Merv and Nishapur in 1221. The message spreads ahead of his armies, and city after city surrenders without a fight. The Mongol empire becomes the largest land empire in history. That is the reversal, and it is a hard one: terror that is predictable, that always offers a way out, and that falls on resistance rather than on the innocent, can divide and conquer instead of uniting enemies. The Arellanos' terror had no rule and offered no way out. Even so, the Mongol empire split into four rival states within two generations of his death." },
        ],
      },
      {
        n: 19, title: "Do Not Strike the One the World Is Watching", opener: "Rafael Caro Quintero", place: "Guadalajara, 1985",
        judgment: "Some people are protected not by guards but by attention. Strike one of them, and you are no longer fighting your enemy. You are fighting everyone who was watching.",
        eras: ["Canterbury, 1170", "Guadalajara, 1985", "Istanbul, 2018"],
        story: "In February 1985 men working for the Guadalajara cartel kidnapped an American drug agent, Enrique Camarena, outside the United States consulate, tortured him for days and killed him. They had believed their protection in Mexico was complete. But Camarena was an American federal agent, and the United States turned its full weight on Mexico until the men responsible were caught. Within weeks Rafael Caro Quintero was arrested in Costa Rica. The cartel that had controlled Mexico's drug trade never recovered.",
        key: "Seeking: know who in your world is watched by people more powerful than you, and leave them alone. Keeping: the more powerful you are, the more your enemies' martyrs will cost you; never make one.",
        sections: [
          { name: "The Law", text: "Do not strike the one the world is watching. Canterbury, 29 December 1170. Thomas Becket, Archbishop of Canterbury and once King Henry II's closest friend and chancellor, has defied the king for years over the rights of the Church. At Christmas the king, in a rage in Normandy, is reported to have cried out against the men of his household who let him be mocked by a low-born priest. Four knights take him at his word, cross the Channel, and late on the afternoon of 29 December cut Becket down in his own cathedral. All of Christian Europe is horrified. Within three years the Pope makes Becket a saint, and pilgrims flock to his tomb. On 12 July 1174 King Henry II, the most powerful ruler in western Europe, walks barefoot through Canterbury in a pilgrim's shirt and kneels at the tomb while monks whip him. In life, Becket had been a stubborn opponent. In death, he defeated the king." },
          { name: "Judgment", text: "Some people are protected not by guards but by attention. London, 1 November 2006. Alexander Litvinenko, a former officer of Russia's security service who has fled to Britain and accuses his old service of terrible crimes, drinks tea with two visitors from Moscow at the Millennium Hotel in Mayfair. Within days he is dying in hospital; doctors find he has been poisoned with polonium-210, a rare radioactive substance. He dies on 23 November. Britain traces radioactive traces through hotels, offices and aircraft. A public inquiry concludes in 2016 that the killing was probably approved by President Putin and the head of the security service, which Russia denies. The murder of one exile, in the capital of a great power, becomes a case studied by every intelligence service in the world and a lasting wound in relations between the two countries." },
          { name: "Transgression", text: "Guadalajara, 1984 to 1985. Rafael Caro Quintero, a young trafficker from Sinaloa, is one of the leaders of the Guadalajara cartel with Miguel Ángel Félix Gallardo and Ernesto Fonseca Carrillo, known as Don Neto. In November 1984 Mexican soldiers, acting on American intelligence, raid Rancho Búfalo in the desert of Chihuahua, a marijuana plantation of more than a thousand hectares, with thousands of workers. Thousands of tons of marijuana are burned. The traffickers believe the information came from Enrique Camarena, an agent of the American Drug Enforcement Administration working in Guadalajara. On 7 February 1985 Camarena walks out of the American consulate to meet his wife for lunch and is pushed into a car. A Mexican pilot who had worked with the agency, Alfredo Zavala, is taken the same day. They are held at a house on Calle Lope de Vega, tortured over many hours, and killed; the torture is recorded on tape. On 5 March their bodies are found on a ranch in Michoacán. The United States responds as if it has been attacked. Customs officers search every car at the Mexican border, choking trade; the agency launches Operation Leyenda; the American ambassador accuses Mexican officials of protecting the killers. On 4 April 1985 Caro Quintero, who had flown out of Guadalajara on a private jet, is arrested at a villa in Costa Rica with his girlfriend. Don Neto is arrested days later in Puerto Vallarta. Félix Gallardo follows in 1989. Caro Quintero is sentenced to forty years." },
          { name: "Observance", text: "Cali, 1980s to 1995. Whatever else they did, the Rodríguez Orejuela brothers of the Cali cartel kept, by many accounts, a rule that the Medellín traffickers did not: no open war with the state, and no attacks on American agents or famous public figures. They preferred bribes to bullets, lawyers to bombs and anonymity to fame. While Escobar, who murdered a justice minister, a presidential candidate and an airliner full of passengers, was hunted by the whole world, the Cali brothers grew richer and remained free for years longer. They fell in 1995, for other reasons, as Law 9 tells. But for more than a decade, they understood exactly who it was too dangerous to touch." },
          { name: "Interpretation", text: "Power protects people in two ways. Some are protected by force: walls, guards, armies. Others are protected by attention: they belong to an institution or a nation that will treat any attack on them as an attack on itself, or they are watched by so many people that their death becomes a story no one can ignore. The second kind of protection is invisible until it is triggered. The Guadalajara traffickers thought only about the first kind. They knew they could pay Mexican police and officials. They did not consider that the man they were killing was protected by the attention of the most powerful country in the world, and that the moment he died, the question was no longer whether they would be caught, only when. Killing him did not remove a problem. It created a cause." },
          { name: "Parallels", text: "Palermo, 23 May and 19 July 1992. Salvatore Riina, the boss of the Corleonesi clan who rules the Sicilian Mafia through terror, has the judges Giovanni Falcone and Paolo Borsellino blown up, Falcone with half a ton of explosives under a motorway, Borsellino with a car bomb outside his mother's home. The Italian public explodes in anger; the state sends seven thousand soldiers to Sicily and passes harsh new laws. On 15 January 1993 Riina, who had been a fugitive for twenty-three years, is arrested in Palermo. He dies in prison in 2017. Istanbul, 2 October 2018. The Saudi journalist Jamal Khashoggi, a columnist for The Washington Post, walks into his country's consulate to collect a document for his marriage and is killed by a team sent from Riyadh. Turkey releases evidence day after day. In February 2021 an American intelligence report concludes that Crown Prince Mohammed bin Salman approved the operation, which Saudi Arabia denies. For years the crown prince is shunned by Western leaders, and his country's name is tied to the murder around the world." },
          { name: "The Cost", text: "For Caro Quintero: decades of his life in prison, years as a fugitive after a court released him on a technicality in 2013, a place on the FBI's Ten Most Wanted list, recapture in July 2022 in an operation in which a navy helicopter crashed and fourteen marines died, and in February 2025 his transfer by Mexico to the United States to face trial. For the Guadalajara cartel: its leaders imprisoned, its empire divided among the younger men who became the Tijuana, Juárez and Sinaloa cartels. For Mexico: years of strained relations with its neighbour. For Henry II: humiliation before Christendom. For Riina: life in prison, and the collapse of the Mafia's power. Striking the watched one does not end a fight. It invites the whole audience onto the stage." },
          { name: "The Record", text: "Verified: the raid on Rancho Búfalo in November 1984; the kidnapping of Enrique Camarena on 7 February 1985 and the discovery of his body and Zavala's on 5 March; Caro Quintero's arrest in Costa Rica on 4 April 1985; his release in August 2013 and recapture on 15 July 2022; his transfer to the United States in February 2025. Disputed: who ordered the killing. Caro Quintero has always denied ordering Camarena's death; several men have been convicted in American courts of taking part, and trials have been argued for decades. Disputed: claims, made by some former agents in interviews in 2013, that American intelligence officers were involved with the traffickers; the CIA has denied them. Verified: the size of Rancho Búfalo was reported in very large figures; the exact acreage and tonnage vary between accounts." },
          { name: "Keys", text: "For those seeking: first, know who in your world is watched by people more powerful than you, and leave them alone, however much they cost you. Second, never assume your protection extends to everyone you might harm; your protector may not be theirs. Third, find another way to deal with a dangerous opponent who is admired: outlast him, outwork him, or make him irrelevant. For those keeping: first, the more powerful you become, the more your enemies' martyrs will cost you; never make one. Second, control the men who act in your name; one of them, guessing at your anger, can start the war you would never have chosen. Third, if a watched person is harmed in your name, do not hide; the hiding becomes the story." },
          { name: "Image", text: "A man in a dark theatre who throws a stone at the actor on the stage. In the dark he feels safe; no one can see him. Then the lights come up, and every face in the audience turns to look at the seat the stone came from." },
          { name: "Authority", text: "\"The blood of the martyrs is the seed of the Church.\" Tertullian, around AD 197, paraphrasing his Apology: each Christian the Romans killed won them more converts. And a judgment from 1804, when Napoleon had a young royal prince, the Duke of Enghien, seized abroad and shot: \"It is worse than a crime; it is a blunder.\" The line is usually given to Napoleon's minister Talleyrand or his police chief Fouché; who said it first is disputed." },
          { name: "Reversal", text: "Mexico City, 20 August 1940. An agent of Stalin's secret police, Ramón Mercader, kills Leon Trotsky, Stalin's great exiled rival, with an ice axe in his study. The world is watching Trotsky, but the world is also at war; France has fallen two months earlier, and the killing becomes one more horror among many. Stalin suffers almost nothing for it. And Mohammed bin Salman, after years of being shunned, was received again by Western leaders once his country's oil mattered more to them than the journalist did. That is the reversal, and it is cold: a power large enough, useful enough, or lucky enough in its timing can survive striking the watched one. A cartel cannot. Neither can any power that needs the goodwill of those who were watching." },
        ],
      },
      {
        n: 20, title: "Every Conquest Has a Border; Find It First", opener: "Napoleon Bonaparte", place: "The river Niemen, 1812",
        judgment: "Every advance has a point beyond which each step costs more than it gains. The wise find that line on a map before they reach it. The rest find it in the snow.",
        eras: ["Carrhae, 53 BC", "Moscow, 1812", "Afghanistan, 1989"],
        story: "On 24 June 1812 Napoleon led one of the largest armies Europe had ever seen across the river Niemen into Russia. The Russians retreated, burning what they left behind. He reached Moscow in September and found it empty; that night it began to burn. He waited five weeks for a surrender that never came, then turned back into the Russian winter. Of the hundreds of thousands who had crossed the Niemen in June, only a small fraction came back across it in December.",
        key: "Seeking: before you advance, decide where you will stop, and why. Keeping: every victory moves you further from your supplies and closer to your limits; measure both after every win.",
        sections: [
          { name: "The Law", text: "Every conquest has a border; find it first. Carrhae, Mesopotamia, 53 BC. Marcus Licinius Crassus is the richest man in Rome, partner with Pompey and Julius Caesar in ruling the Republic. What he lacks is military glory to match theirs. He marches east against the Parthian Empire without any real cause, ignoring the advice of an Armenian ally to take the route through the hills. In the open desert near Carrhae, the Parthian general Surena surrounds his legions with horse archers, supplied with fresh arrows by a train of camels, and armoured cavalry. Day after day of arrows, heat and thirst destroy the Roman army. About twenty thousand Romans are killed and ten thousand captured; the eagles of seven legions are taken. Crassus himself is killed at a parley. Rome took thirty years to win back the eagles, by diplomacy, not war. Crassus had found Rome's eastern border by walking past it." },
          { name: "Judgment", text: "Every advance has a point beyond which each step costs more than it gains. Poltava, Ukraine, 8 July 1709. Charles XII of Sweden is a military genius who, by the age of twenty-five, has defeated Denmark, Poland and the Russians. In 1708 he marches on Moscow. Peter the Great's armies retreat and burn the land behind them. Charles turns south into Ukraine; the winter of 1708 to 1709 is the coldest in Europe in five hundred years, and thousands of his men freeze. When he finally fights the Russians at Poltava, his army is exhausted and outnumbered, and it is destroyed. Charles flees to Ottoman territory with a few hundred men. Sweden's time as a great power is over. Napoleon owned a history of Charles's campaign and read it on his own march into Russia." },
          { name: "Transgression", text: "Russia, June to December 1812. Napoleon rules or controls almost all of continental Europe. Only Britain, behind its navy, and Russia, at the far edge of the continent, escape his system. When Tsar Alexander I begins trading with Britain again, Napoleon decides to force him back into line. On 24 June 1812 the Grande Armée, with soldiers from France and every nation of his empire, about 450,000 men in the first wave and more than 600,000 counting the reinforcements, begins crossing the Niemen. The Russians refuse to fight; they retreat, burning crops and villages behind them. Napoleon's supply wagons cannot keep up; tens of thousands of men die of heat, disease and desertion before any great battle. On 7 September he finally fights the Russian army at Borodino, the bloodiest single day of the Napoleonic wars, with some seventy thousand casualties on both sides, and wins, but the Russians withdraw intact. On 14 September he enters Moscow. It is almost empty. That night fires break out, set, most historians believe, on the orders of the city's governor, Fyodor Rostopchin, and burn for days. Napoleon waits for the tsar to ask for peace. No message comes. On 19 October he leaves. The retreat becomes a catastrophe: early snow, Cossack raids, starvation. At the river Berezina in late November his engineers build bridges in freezing water so that the remnants can cross while the Russians close in. In December the last of the army staggers back over the Niemen. Fewer than a hundred thousand of the men who had entered Russia ever returned; many accounts put the number of fighting men still with the colours far lower." },
          { name: "Observance", text: "Rome, AD 9 to AD 14. In the year 9, three Roman legions under Publius Quinctilius Varus are ambushed and wiped out in the Teutoburg Forest in Germany. The emperor Augustus, by then an old man, is said to have beaten his head against a door, crying, \"Varus, give me back my legions!\" But he does not send a great army to avenge them and conquer Germany. He fixes the empire's border at the Rhine. At his death in AD 14 he leaves a document for his successors which, Tacitus reports, includes advice to keep the empire within its existing limits. In 117 the emperor Hadrian gives up provinces his predecessor Trajan had just conquered in Mesopotamia, and in the 120s he begins the wall across northern Britain that still carries his name. Both understood that an empire's strength is not how far it reaches, but how much of what it reaches it can hold." },
          { name: "Interpretation", text: "Every advance stretches the line that feeds it. Each mile forward is a mile further from your supplies, your reinforcements and the people who know you, and a mile closer to your enemy's. At first the gains are larger than the costs. But there is a point, the military theorist Carl von Clausewitz called it the culminating point of victory, beyond which each step forward weakens you more than it weakens the enemy. The danger is that this point is invisible from the front, where you are still winning battles. Napoleon won almost every battle in Russia. He won at Borodino. He took Moscow. And with every victory he was further from France, with fewer men, in a bigger country, nearer the winter. He found his border not on a map, where he could have seen it, but in the snow, where he could not escape it." },
          { name: "Parallels", text: "Afghanistan, 25 December 1979 to 15 February 1989. The Soviet Union sends its army into Afghanistan to prop up a friendly communist government, expecting a short operation. It stays almost ten years. About fifteen thousand Soviet soldiers are killed, and estimates of Afghans killed run from several hundred thousand to over a million. On 15 February 1989 the last Soviet general walks back across the Friendship Bridge into Soviet territory. Within three years the Soviet Union itself is gone. New York, 2019. WeWork, a company that rents office space, has expanded into more than a hundred cities across the world in a few years, signing long leases on hundreds of buildings, with a valuation of forty-seven billion dollars. When it prepares to go public in 2019, investors read its accounts and see the losses; the share sale is cancelled in September and its founder, Adam Neumann, is forced out. In 2023 it files for bankruptcy. Britain and America, 2007 to 2013. Tesco, Britain's largest supermarket, launches a chain called Fresh and Easy in the American West. Six years and more than a billion pounds later, it gives up and sells what is left. Success at home had told it nothing about the border of its strength abroad." },
          { name: "The Cost", text: "For Napoleon: the army that had made him master of Europe; within two years his enemies were in Paris, and on 6 April 1814 he abdicated. After a brief return in 1815 that ended at Waterloo on 18 June, he died in exile on the island of Saint Helena on 5 May 1821. For France: hundreds of thousands of its young men and those of its allies. For Russia: Moscow burned and its western provinces ruined. For Crassus: his life, his son's and Rome's eagles. For Charles XII: Sweden's empire. For the Soviet Union: a defeat that helped bring its collapse. Every one of them found the border of their strength. None found it in time." },
          { name: "The Record", text: "Verified: the crossing of the Niemen beginning on 24 June 1812; the battle of Borodino on 7 September; the entry into Moscow on 14 September and the fire that began that night; the departure on 19 October; the crossing of the Berezina in late November; the return across the Niemen in December. Disputed: the numbers. Estimates of the army that entered Russia range from about 450,000 in the first wave to over 680,000 in total; estimates of those who came back range from under 30,000 fighting men to around 100,000 survivors of all kinds. A famous chart drawn in 1869 by the French engineer Charles Minard shows the army shrinking as a band of colour across the map. Disputed: who set Moscow on fire. Most historians blame Rostopchin's orders; he later both claimed and denied it." },
          { name: "Keys", text: "For those seeking: first, before you advance, decide where you will stop, and why; write it down while you are calm. Second, measure your supply lines, money, people and attention, not just your victories. Third, study those who tried the same thing before you, and ask where they stopped and why. For those keeping: first, every victory moves you further from your base and closer to your limits; measure both after every win. Second, a retreat chosen early is a strategy; a retreat forced late is a rout. Third, when your enemy keeps falling back without fighting, ask whether you are winning, or whether you are being led." },
          { name: "Image", text: "A rope tied to a post, and a man walking away from it across a frozen lake, paying out the rope as he goes. Every step takes him further from the shore and closer to the centre, where the ice is thinnest. He looks back and sees how far he has come, and is proud of it. He does not look down." },
          { name: "Authority", text: "\"He will win who knows when to fight and when not to fight.\" Sun Tzu, The Art of War, as translated by Lionel Giles in 1910. Carl von Clausewitz, On War, 1832: most attacks reach a culminating point, beyond which the attacker's strength turns into weakness. And Tacitus, Annals, on Augustus's last advice: keep the empire within its borders." },
          { name: "Reversal", text: "Narva, 1700, to Saint Petersburg, 1721. Peter the Great of Russia, beaten badly by Charles XII at Narva in November 1700, does not try to win the war at once. He pulls back, rebuilds his army on modern lines, founds Saint Petersburg in 1703 on land he has taken from Sweden, and builds roads, factories and a navy to support the next advance. Only when the Swedish army has exhausted itself in Ukraine does he fight it, at Poltava in 1709, and win. By the Treaty of Nystad in 1721 Russia's border has moved permanently to the Baltic Sea. That is the reversal: borders can be moved, but only by building the road before you march down it. Napoleon marched first and planned to build later. Peter built first, and marched only when the road could carry him." },
        ],
      },
    ],
  },
  {
    n: 5, title: "The People", opens: "Apr 2027",
    line: "The crowd that crowns, and the square that brings it down.",
    laws: [
      {
        n: 21, title: "Hear the Square Before It Shouts", opener: "Nicolae Ceaușescu", place: "Bucharest, 1989",
        judgment: "A crowd does not turn in a moment. It murmurs for years, and then it shouts once. The ruler who waits for the shout to start listening has already lost.",
        eras: ["Paris, 1848", "Bucharest, 1989", "Dhaka, 2024"],
        story: "On 21 December 1989 Nicolae Ceaușescu stood on the balcony of the Central Committee building in Bucharest to address a crowd his party had gathered to cheer him. A few minutes into his speech, the crowd began to boo. On live television, the whole country watched his face as he realised what he was hearing. The next day he fled by helicopter from the roof. Four days later, on Christmas Day, he and his wife Elena were tried by a military court and shot.",
        key: "Seeking: build a way to hear bad news before it becomes a crowd; reward the ones who bring it. Keeping: if the only voices that reach you are cheering, it is because someone is filtering the rest.",
        sections: [
          { name: "The Law", text: "Hear the square before it shouts. Paris, February 1848. King Louis-Philippe has ruled France for eighteen years, a careful, cautious king in a frock coat who carries an umbrella and calls himself the citizen king. Only the richest men can vote, and when reformers ask to widen the vote, his chief minister, François Guizot, tells them to get rich. Unable to hold political meetings, the opposition holds banquets instead, with speeches between the courses. On 27 January the writer Alexis de Tocqueville warns the Chamber of Deputies that they are sleeping on a volcano. The government bans the great Paris banquet set for 22 February. Crowds gather. On the 23rd the king dismisses Guizot, but that night soldiers fire on a crowd on the Boulevard des Capucines, killing about fifty people, and by morning the city is covered in barricades. On 24 February Louis-Philippe abdicates and escapes to England under the name Mr Smith. He had been warned for years. He heard it only when it became a shout." },
          { name: "Judgment", text: "A crowd does not turn in a moment. It murmurs for years, and then it shouts once. Dhaka, July and August 2024. Sheikh Hasina has ruled Bangladesh for fifteen years in a row. In June a court restores a quota reserving almost a third of government jobs for descendants of the fighters of 1971, often relatives of her own party's supporters. Students protest. On 14 July Hasina compares them, in effect, to the collaborators of 1971, a deadly insult in Bangladesh. Police and party youth attack the students; on 16 July a student named Abu Sayed is shot dead in Rangpur with his arms spread wide, on video, and the country sees it. The government shuts down the internet. The Supreme Court cuts the quota, but by now the demand is for her to go. On 5 August, as hundreds of thousands march on her residence and the army refuses to stop them, she flees by military helicopter to India. A United Nations report later estimated that as many as 1,400 people had been killed in the crackdown." },
          { name: "Transgression", text: "Romania, 1980 to 1989. Nicolae Ceaușescu has ruled Romania since 1965. In the 1980s, determined to pay off the country's foreign debts, he exports most of what Romania produces: food, fuel, electricity. At home, bread, meat and cooking oil are rationed; flats are heated a few hours a day; streets are dark; television is cut to two hours a night, much of it about him. His secret police, the Securitate, listen to everything. By April 1989 the debt is paid, and he announces it as a triumph. On 16 December 1989 in the western city of Timișoara, people gather to stop the eviction of a Hungarian pastor, László Tőkés. The protest grows. On the 17th the army fires on the crowd. Ceaușescu flies to Iran on a state visit, returns on the 20th and calls the protesters hooligans on television. On 21 December his party gathers a crowd of about a hundred thousand outside the Central Committee building in Bucharest for a rally of support. A few minutes into his speech, there are noises, whistles, then boos. He stops, raises his hand and says, Alo, alo, as if the line were faulty. The broadcast is cut, but millions have already seen it. He promises a rise in wages and pensions. It is too late. That night there is shooting in the streets. The next morning the defence minister, Vasile Milea, is found dead, and the army goes over to the crowd. At about noon on 22 December the Ceaușescus escape by helicopter from the roof of the building as protesters break in below. They are caught that afternoon near Târgoviște. On 25 December they are tried by a hastily assembled military court in a barracks there, and shot in the courtyard the same afternoon." },
          { name: "Observance", text: "Pretoria and Cape Town, 1989 to 1994. F. W. de Klerk becomes president of South Africa in September 1989, the leader of the party that had built apartheid. He is not a liberal. But he sees the strikes, the boycotts, the townships in revolt, the sanctions, and the end of the Cold War, and he understands what the square will say if he waits. On 2 February 1990, in his first speech to open parliament, he lifts the ban on the African National Congress and other banned movements. On 11 February Nelson Mandela walks out of prison after twenty-seven years. In March 1992 de Klerk asks white voters, in a referendum, whether to continue the negotiations; nearly seven in ten say yes. On 27 April 1994 South Africans of every race vote together, and Mandela becomes president, with de Klerk as one of his deputies. In 1993 the two men shared the Nobel Peace Prize. De Klerk died at home in 2021, at eighty-five. He listened while the crowd was still murmuring." },
          { name: "Interpretation", text: "Power has a way of making the powerful deaf. The people around a ruler learn which news pleases him and which news gets them punished, and so, little by little, the news that reaches him becomes the news he wants. Crowds are arranged to cheer. Reports are rewritten on their way up. The ruler is not lying to himself; he is being lied to by a system he built, and he has no way to know it. Ceaușescu really did believe the crowd on 21 December would cheer him, because every crowd for twenty-four years had. The boos on the square were not sudden. They had been growing in queues for bread, in cold flats, in whispered jokes, for a decade. He had only made sure he could not hear them until they were loud enough to be heard on live television." },
          { name: "Parallels", text: "East Berlin, October 1989. On 7 October Erich Honecker celebrates the fortieth anniversary of East Germany with a parade, while tens of thousands of his citizens are escaping through Hungary to the West. The visiting Soviet leader, Mikhail Gorbachev, is reported to have warned that life punishes those who come too late. Two days later, seventy thousand people march through Leipzig chanting, We are the people. On 18 October Honecker is forced out by his own colleagues. On 9 November the Berlin Wall opens. Khartoum, December 2018 to April 2019. Omar al-Bashir has ruled Sudan for almost thirty years. On 19 December 2018 the price of bread triples, and protests begin in the town of Atbara. Bashir calls them a conspiracy, declares a state of emergency and tells the security forces to shoot. In April 2019 protesters camp outside army headquarters in Khartoum. On 11 April the army removes him. He had heard the square for months, and believed he could silence it." },
          { name: "The Cost", text: "For Ceaușescu: his life and his wife's, after a trial that lasted about an hour. For Romania: around 1,100 people killed in the days of the revolution, and decades of argument about who fired on whom. For Louis-Philippe: his throne and the French monarchy itself, which never returned. For Honecker: power, arrest after German reunification, and death in exile in Chile in 1994. For Hasina: her office, her country and, in November 2025, a death sentence passed in her absence by a court in Dhaka. A ruler who will not hear the murmur pays for it all at once, in the hour when the shout arrives." },
          { name: "The Record", text: "Verified: the protests in Timișoara from 16 December 1989; the rally and the booing in Bucharest on 21 December, which was broadcast live; the escape by helicopter on 22 December; the trial and execution at Târgoviște on 25 December. Disputed: how Vasile Milea died; the government said suicide, and investigations since have not settled the question for everyone. Disputed: who was doing the shooting after 22 December, when the new authorities blamed terrorists loyal to Ceaușescu. Romanian prosecutors have spent decades on the question. Disputed: the early reports of tens of thousands dead in Timișoara, which were false; the true figure there was around a hundred. Disputed: the death toll in Bangladesh in 2024, which different counts place between several hundred and the United Nations estimate of up to 1,400." },
          { name: "Keys", text: "For those seeking: first, build a way to hear bad news before it becomes a crowd. Second, reward the people who bring it, even when it hurts, or they will stop bringing it. Third, go and see for yourself: the queue, the market, the classroom, the street. For those keeping: first, if the only voices that reach you are cheering, someone is filtering the rest. Second, a crowd gathered to cheer you is the most dangerous crowd there is, because it can turn in front of the cameras. Third, a concession made after the shout looks like fear; made before it, it looks like wisdom." },
          { name: "Image", text: "A dam in a river. For years there is a thin trickle through a crack at its base, and the keeper paints over it every spring. Then one morning he hears a sound like distant thunder from inside the wall." },
          { name: "Authority", text: "\"We are sleeping on a volcano.\" Alexis de Tocqueville, to the French Chamber of Deputies, 27 January 1848, four weeks before the king fell. And from about 798, the scholar Alcuin of York to the emperor Charlemagne: those people should not be listened to who keep saying the voice of the people is the voice of God. The king should have weighed both warnings." },
          { name: "Reversal", text: "Beijing, April to June 1989. For seven weeks students and workers fill Tiananmen Square, demanding freedom and an end to corruption. The Communist Party leader, Zhao Ziyang, goes to the square on 19 May and tells the students, with tears in his eyes, we came too late. He is removed and spends the rest of his life under house arrest. Deng Xiaoping declares martial law, and on the night of 3 to 4 June the army clears the streets with tanks and rifles. Hundreds, perhaps thousands, are killed; the true number has never been published. The party survives, and China becomes the second largest economy in the world. That is the reversal, and it is hard: a regime willing to kill enough people, with an army willing to obey, can silence the square instead of hearing it. But Ceaușescu tried exactly that a few months later, and his army would not obey. No one knows in advance which army they have." },
        ],
      },
      {
        n: 22, title: "The Story Told About You Outlives the Truth", opener: "Marie Antoinette", place: "Paris, 1793",
        judgment: "People do not judge you by what you did. They judge you by the story they have been told about you. If you do not tell your story, your enemies will, and theirs will be remembered.",
        eras: ["Paris, 1785", "Paris, 1793", "Atlanta, 1996"],
        story: "Marie Antoinette almost certainly never said, Let them eat cake. The line was written by Jean-Jacques Rousseau about an unnamed great princess when she was a child in Austria. It did not matter. For twenty years pamphlets painted her as a spendthrift, a traitor and worse, and the people of Paris believed them. On 16 October 1793 she was taken through the streets in an open cart and guillotined. More than two centuries later, the line she never said is still the first thing most people know about her.",
        key: "Seeking: tell your own story early, plainly and often, before someone else tells it for you. Keeping: a rumour answered late is a rumour confirmed; the truth needs a head start.",
        sections: [
          { name: "The Law", text: "The story told about you outlives the truth. France, 1765 to today. In the sixth book of his Confessions, written in the late 1760s, Jean-Jacques Rousseau remembers a great princess who, told that the peasants had no bread, answered, Then let them eat brioche. Marie Antoinette was about ten years old at the time and living in Vienna; she had never seen France. No document records her saying anything like it, and those who knew her described her as generous to the poor. The line was attached to her later, and the attachment stuck so firmly that today it appears on mugs, in films and in exam answers across the world. The real Marie Antoinette made real mistakes. But it is the invented one who is remembered." },
          { name: "Judgment", text: "People judge you by the story they have been told. Atlanta, 27 July 1996. During the Olympic Games a security guard named Richard Jewell spots a suspicious backpack under a bench in Centennial Olympic Park and starts moving people away. It explodes minutes later, killing one woman and injuring more than a hundred; a cameraman dies of a heart attack running to the scene. Jewell is praised as a hero. Three days later the Atlanta Journal-Constitution reports that the FBI is investigating him as a suspect. For eighty-eight days television crews camp outside his mother's flat, and he becomes, around the world, the lonely guard who planted a bomb to play the hero. On 26 October 1996 federal prosecutors clear him in writing. The real bomber, Eric Rudolph, is caught in 2003 and admits it. Jewell spent the rest of his life correcting a story that had travelled further than the truth ever did. He died in 2007, at forty-four." },
          { name: "Transgression", text: "Versailles and Paris, 1770 to 1793. Maria Antonia of Austria, the fifteenth child of the Empress Maria Theresa, is married at fourteen to the heir to the French throne, as part of an alliance with France's old enemy. She is a foreigner from the start; the French call her the Austrian woman. Her husband becomes Louis XVI in 1774. She is young, fond of fashion, gambling and the theatre, and she retreats from the stiff rituals of Versailles to her own small palace, the Petit Trianon, and later to a toy farm village built for her in the park. Her enemies at court and in the streets fill the country with pamphlets: she is spending France into ruin, she is loyal to Austria, she is taking lovers of both sexes. In 1785 comes the affair of the diamond necklace. A con woman, Jeanne de la Motte, persuades Cardinal de Rohan that the queen secretly wants a necklace worth 1.6 million livres; he buys it on credit in her name and the con woman's partners take it to London. The queen knew nothing of it. But when the cardinal is acquitted by the Paris court in May 1786, the public decides that the queen must have been guilty of something. They call her Madame Déficit. In October 1789 a crowd marches on Versailles and brings the royal family to Paris. In June 1791 their attempt to escape is stopped at Varennes. In August 1792 the monarchy falls; in January 1793 Louis is guillotined. In October she is tried by the Revolutionary Tribunal. The journalist Jacques Hébert accuses her of abusing her own eight-year-old son. She answers that nature refuses to reply to such a charge against a mother, and appeals to every mother in the room; the women in the gallery murmur in sympathy. It makes no difference. On 16 October 1793, her hair cut short, her hands tied behind her back, she is driven through Paris in an open cart and guillotined. She was thirty-seven." },
          { name: "Observance", text: "England, 1558 to 1603. Elizabeth I comes to the throne in 1558 as a young, unmarried Protestant woman, declared illegitimate by her own father's laws, in a country many thought only a man could rule. She sets out to control her own story. In 1563 her council drafts a proclamation to stop unflattering portraits being painted and sold; the official images show her ageless, crowned, jewelled, her hand on a globe. She lets poets turn her into Gloriana, the Virgin Queen married to her people. On 9 August 1588, with the Spanish Armada in the Channel, she rides among her soldiers at Tilbury and tells them she knows she has the body of a weak and feeble woman, but the heart and stomach of a king. The Armada is scattered. She rules for forty-five years, and four centuries later the story she told is still the one most people know." },
          { name: "Interpretation", text: "Most people will never meet you. They will know you only through what is said about you: in the press, in pamphlets, on social media, in the corridor. That story is not built from evidence. It is built from what is vivid, repeated and convenient to believe. A single memorable line beats a hundred dull facts. A rumour that fits what people already suspect beats a truth that asks them to think again. And once a story has settled, every new fact is read through it. When Marie Antoinette was generous, it was called a trick; when she was frugal, it was called hypocrisy. By the time she stood trial, the verdict had been written for years. Her mistake was not only to spend, but to stay silent while others told the country who she was." },
          { name: "Parallels", text: "Paris, 1894 to 1906. Captain Alfred Dreyfus, a Jewish officer in the French army, is convicted of selling secrets to Germany on the strength of a torn note and forged evidence, and sent to Devil's Island. The real traitor, Major Esterhazy, is identified and then acquitted. Much of France prefers the story of the Jewish traitor to the truth. On 13 January 1898 the novelist Émile Zola publishes his open letter, J'accuse, and is convicted of libel for it. Dreyfus is pardoned in 1899 and fully cleared only in 1906, after twelve years. Perugia, 2007 to 2015. A British student, Meredith Kercher, is murdered. Her American flatmate, Amanda Knox, is arrested, and the press around the world turns her into Foxy Knoxy, a sex-mad killer. She is convicted in 2009, acquitted in 2011, convicted again in 2014, and finally cleared of the murder by Italy's highest court on 27 March 2015. Another man had been convicted of the killing years before. For millions of people, the first story was the one that stayed." },
          { name: "The Cost", text: "For Marie Antoinette: her life, and a reputation that two centuries of historians have not been able to repair. For her son, Louis-Charles: death in prison in 1795, at ten years old. For Richard Jewell: years of his life, and a name that stayed linked to a crime he had tried to stop. For Dreyfus: four years on Devil's Island and twelve years of disgrace. A false story costs twice: once when it is believed, and again for every year it takes the truth to catch up, if it ever does." },
          { name: "The Record", text: "Verified: the passage in Rousseau's Confessions about a great princess and brioche; the diamond necklace affair and the cardinal's acquittal on 31 May 1786; the march on Versailles in October 1789; the flight to Varennes in June 1791; her trial on 14 and 15 October 1793 and her execution on 16 October. Disputed: that Marie Antoinette ever said let them eat cake. No source from her lifetime says so, and historians agree it is almost certainly false. Disputed: her spending. She was extravagant, but the court's spending was a small part of France's debt; the wars, above all the money spent helping the American Revolution, mattered far more. Disputed: her relationship with the Swedish count Axel von Fersen, which letters partly decoded in recent years suggest was very close." },
          { name: "Keys", text: "For those seeking: first, tell your own story early, plainly and often, before someone else tells it for you. Second, give people a vivid picture of who you are; dull truth loses to a lively lie. Third, never let your enemies be the only ones writing. For those keeping: first, a rumour answered late is a rumour confirmed; the truth needs a head start. Second, watch the small symbols, a palace, a party, a car, that can be turned into a whole story about you. Third, when you are attacked, answer the story, not just the facts; people remember the story." },
          { name: "Image", text: "A footprint left in wet cement. The man who made it walks on, and the cement dries. Years later he comes back, a different man, with different shoes, and finds strangers standing around the old footprint, telling each other how big his feet must be." },
          { name: "Authority", text: "\"Falsehood flies, and the Truth comes limping after it.\" Jonathan Swift, The Examiner, 9 November 1710. The line is often given in a newer form, a lie can travel halfway around the world while the truth is putting on its shoes, and wrongly credited to Mark Twain, which proves its point." },
          { name: "Reversal", text: "Rouen, 1431, to Rome, 1920. Joan of Arc, the peasant girl who led French armies against the English, is captured and tried by an English-controlled church court as a witch and a heretic. On 30 May 1431, at nineteen, she is burned alive in the market square of Rouen. Her enemies' story is official. But in 1456 a new church court, ordered by the Pope, examines the trial, hears over a hundred witnesses, and declares the verdict null. In 1920 the Catholic Church makes her a saint. That is the reversal: a false story can be overturned, if someone with authority does the slow, careful work of telling the true one, again and again, for as long as it takes. For Joan it took twenty-five years to clear her name and nearly five hundred to make her a saint. The truth can win. It is simply never in a hurry." },
        ],
      },
      {
        n: 23, title: "Never Leave the House While the Ground Is Shaking", opener: "Kwame Nkrumah", place: "Accra, 1966",
        judgment: "Absence is an invitation. When your position is uncertain, the men who want it are waiting for only one thing: a day when you are not there to defend it.",
        eras: ["Moscow, 1964", "Accra, 1966", "Lagos, 1975"],
        story: "Kwame Nkrumah led Ghana to independence in 1957, the first black African colony to win it, and became a hero across the continent. By 1966 his economy was failing, his opponents were in prison, and his army was angry. On 21 February he left Accra on a peace mission to Vietnam. Three days later, while he was in Beijing, soldiers and police seized power. Crowds in Accra pulled down his statue. He never saw Ghana again.",
        key: "Seeking: before you travel, know who would gain if you never came back. Keeping: when the ground is shaking at home, the most important meeting abroad is less important than being at home.",
        sections: [
          { name: "The Law", text: "Never leave the house while the ground is shaking. Lagos and Kampala, 1974 and 1975. General Yakubu Gowon has ruled Nigeria since 1966, when he became head of state at thirty-one. He led the country through the civil war and ended it in 1970 with the words no victor, no vanquished. He had promised to hand power to civilians in 1976. On 1 October 1974 he announces that the date is no longer realistic, and gives no new one. Officers who had hoped for change, and governors accused of corruption whom he refuses to remove, grow restless. In July 1975 Gowon flies to Kampala for the summit of the Organisation of African Unity, hosted that year by Idi Amin. On 29 July, while he is there, his own officers announce on Radio Nigeria that he has been removed, and that Brigadier Murtala Mohammed is the new head of state. Gowon hears the news in Kampala. He goes into exile in Britain, where he becomes a student again and earns a doctorate at the University of Warwick. He was lucky: it was a coup without blood. He had left home at the one moment his place was least secure." },
          { name: "Judgment", text: "Absence is an invitation. Pitsunda, October 1964. Nikita Khrushchev has led the Soviet Union for a decade. He has denounced Stalin, put the first satellite and the first man in space, and backed down over Cuba. His colleagues are tired of his reforms, his temper and his humiliations. In October he goes on holiday to the Black Sea coast. While he is away, Leonid Brezhnev and the others quietly line up a majority. On 12 October Khrushchev is telephoned and asked to return to Moscow for a meeting; on the 13th he walks into a room of men who have already decided. On 14 October he is retired, officially for reasons of age and health. He spends his last seven years as a pensioner at his dacha, dictating his memoirs, which have to be smuggled out to be published in the West." },
          { name: "Transgression", text: "Ghana, 1957 to 1966. On the night of 6 March 1957, Kwame Nkrumah stands before a crowd in Accra and declares Ghana free for ever. He is the hero of a continent: the first leader of a black African colony to win independence, a champion of African unity. Then the ground begins to move. In 1958 he passes the Preventive Detention Act, allowing anyone to be jailed without trial for five years; hundreds of opponents are imprisoned. In August 1962 a bomb is thrown at him at Kulungugu; after it he rarely appears in public without heavy guard. In 1964 a referendum makes Ghana a one-party state. The price of cocoa, Ghana's main export, collapses, falling to less than half what it had been; the country's reserves are spent on grand projects and its debts mount. Prices rise in the shops. Nkrumah builds a separate presidential guard, better paid and better armed, and the regular army resents it. On 21 February 1966 he flies out of Accra, heading for Hanoi, where he hopes to help end the war in Vietnam. On 24 February, in an operation its planners call Cold Chop, soldiers led by Colonel Emmanuel Kotoka and Major Akwasi Afrifa, with the police commissioner John Harlley, seize Accra. Nkrumah lands in Beijing and is told by his Chinese hosts that he is no longer president. In Accra, crowds celebrate and pull down his statue outside Parliament House. He goes to Guinea, where President Sékou Touré makes him an honorary co-president. He waits there for six years for a call home that never comes, and dies of cancer in a hospital in Bucharest on 27 April 1972." },
          { name: "Observance", text: "Madrid, 23 and 24 February 1981. Six years after the death of the dictator Franco, Spain's new democracy is fragile. At 6.23 in the evening of 23 February, Lieutenant Colonel Antonio Tejero and about two hundred civil guards burst into parliament, fire into the ceiling and hold the deputies hostage. In Valencia, General Milans del Bosch sends tanks into the streets. Everything depends on the young king, Juan Carlos, whom the plotters expect to support them. He does not leave his palace. He stays on the telephone all night, calling the generals in each military region one by one, ordering them to stay loyal. At 1.14 in the morning he appears on television in his uniform as commander in chief and says that the Crown will not tolerate any attempt to interrupt the democratic process. By noon the coup has collapsed. Juan Carlos's later years brought scandal, and he gave up the throne in 2014. But that night, he was where he needed to be." },
          { name: "Interpretation", text: "A position that is secure can survive its holder's absence. A position that is contested cannot, because absence changes the arithmetic. When the leader is in the room, rivals must decide whether to strike at someone who can strike back, see their faces and remember them. When he is away, they need only decide among themselves, and present him with a finished fact. Distance also slows the leader's response: he hears late, through others, and must decide whether to return to a country that may arrest him at the airport. Nkrumah left on a mission that flattered his place in the world, at a moment when his place at home was cracking. Nothing he could have achieved in Hanoi was worth what he lost in Accra." },
          { name: "Parallels", text: "Phnom Penh, March 1970. Prince Norodom Sihanouk, who has ruled Cambodia since independence, leaves for a long rest cure in France and visits to Moscow and Beijing, while his country is being drawn into the war in Vietnam. On 18 March, while he is in Moscow, the National Assembly votes to remove him, and General Lon Nol takes power. In his anger Sihanouk allies himself with the Khmer Rouge, which Law 16 tells of. Nouakchott, 3 August 2005. Maaouya Ould Taya, who has ruled Mauritania for twenty-one years, flies to Saudi Arabia for the funeral of King Fahd. That morning his own head of security, Colonel Ely Ould Mohamed Vall, and other officers take control of the capital. Ould Taya never returns to power. And in Kampala in 1971, as Law 16 tells, Milton Obote lost Uganda to Idi Amin while he was at a conference in Singapore." },
          { name: "The Cost", text: "For Nkrumah: his country, and six years of exile ending in a foreign hospital. For Ghana: a run of coups for the next fifteen years. For Gowon: power, and years abroad; he was later accused of involvement in the coup that killed Murtala Mohammed in February 1976, which he denied, and he came home only after a pardon in the 1980s. For Khrushchev: power, and the dignity of being heard; his name was barely mentioned in the Soviet press for years. A journey that seems like a show of confidence becomes, when you are overthrown during it, the proof that you were not paying attention." },
          { name: "The Record", text: "Verified: Ghana's independence on 6 March 1957; the Preventive Detention Act of 1958; the Kulungugu bombing of 1 August 1962; the one-party referendum of 1964; Nkrumah's departure on 21 February 1966 and the coup of 24 February; his death in Bucharest on 27 April 1972. Verified: Gowon's removal on 29 July 1975 while at the OAU summit in Kampala; Khrushchev's removal on 14 October 1964. Disputed: the role of the American CIA in the 1966 coup. A former CIA officer, John Stockwell, wrote in 1978 that the agency's station in Accra had been in contact with the plotters; American documents released since show that Washington knew of the plans in advance and welcomed the result. How far it helped is still argued." },
          { name: "Keys", text: "For those seeking: first, before you travel, know who would gain if you never came back. Second, the bigger your stage abroad, the more you must secure the floor at home. Third, if you must leave, leave someone in charge who loses everything if you fall. For those keeping: first, when the ground is shaking at home, no meeting abroad matters more than being at home. Second, a holiday during a quarrel is a vote of confidence in your enemies. Third, if you hear that something is wrong while you are away, come back at once; every hour you wait, the finished fact grows harder." },
          { name: "Image", text: "A man who steps out of his house to watch a storm from the hill. From up there it looks magnificent. When he comes back down, the door is locked from the inside, and through the window he can see someone else sitting in his chair." },
          { name: "Authority", text: "Machiavelli, The Prince, chapter 3, 1513: a ruler should go and live in a newly won country, because being on the spot, disorders are seen as they spring up and can quickly be remedied; but not being there, they are heard of only when they are great, and then there is no remedy." },
          { name: "Reversal", text: "Russia, 1697 and 1698. Peter the Great leaves Russia for a year and a half on his Grand Embassy, travelling through Europe in disguise, working in a shipyard in Holland and studying in England. While he is away, the Streltsy, the old musketeer regiments, revolt and march on Moscow. But the generals Peter left behind are loyal men who owe everything to him, and they crush the revolt before he gets home. He returns in August 1698 and destroys the Streltsy in a wave of executions. That is the reversal: a ruler can leave even when the ground is shaking, if those he leaves behind fear his return more than they want his seat, and if the army is in hands that cannot survive without him. Nkrumah left Accra in the care of an army that had already decided it could." },
        ],
      },
      {
        n: 24, title: "Change Before the People Change You", opener: "Hosni Mubarak", place: "Tahrir Square, 2011",
        judgment: "Every people asks for change slowly, then demands it all at once. A ruler who gives a little early keeps his throne. A ruler who gives everything late gives it to his successor.",
        eras: ["London, 1832", "Cairo, 2011", "Kathmandu, 2025"],
        story: "Hosni Mubarak ruled Egypt for almost thirty years under emergency law, and seemed to be preparing his son Gamal to follow him. On 25 January 2011 young Egyptians, inspired by Tunisia, filled Tahrir Square in Cairo. He offered a new cabinet, then a promise not to run again, then a speech refusing to leave. Every offer came a few days too late. On 11 February 2011 he resigned, and the army took power. Within months he was lying on a stretcher in a courtroom cage.",
        key: "Seeking: give a little while it is still a gift; it buys more than everything given under pressure. Keeping: when the people's request turns into a demand, the price of peace has just risen, and it will rise again tomorrow.",
        sections: [
          { name: "The Law", text: "Change before the people change you. Paris, July 1830. King Charles X, brother of the executed Louis XVI, believes the concessions made after Napoleon's fall have gone too far. When elections return a hostile chamber, he answers on 25 July with four ordinances: he dissolves the new chamber before it meets, ends the freedom of the press, and changes the voting rules so that fewer people can vote. On 27 July the printers and journalists of Paris go into the streets; the workers follow. In three days of fighting, the Three Glorious Days, the royal troops are driven out of the city. On 2 August Charles abdicates and goes into exile in Britain. He had not been asked for much. He chose to take away what little there was, and lost everything." },
          { name: "Judgment", text: "Every people asks for change slowly, then demands it all at once. Kathmandu, September 2025. Nepal's politicians have taken turns in power for years while the young leave the country by the hundreds of thousands to find work abroad. Online, the children of politicians show off their cars and holidays, and young Nepalis start calling them the nepo kids. On 4 September the government blocks twenty-six social media platforms. On 8 September tens of thousands of young people, many in school uniforms, march on parliament. Police open fire, and nineteen are killed that day. That night the ban is lifted. It is too late. On 9 September crowds set fire to parliament, the government offices at Singha Durbar and the homes of leading politicians, and Prime Minister K. P. Sharma Oli resigns. Days later a former chief justice, Sushila Karki, becomes interim prime minister, chosen in part through an online poll of the protesters. The ban had lasted four days. The government it ended had lasted three years." },
          { name: "Transgression", text: "Cairo, 1981 to 2011. Hosni Mubarak, a former air force commander, becomes president on 14 October 1981, eight days after Islamist soldiers assassinate President Anwar Sadat at a military parade. An emergency law is declared. It remains in force, with brief pauses, for almost his entire rule. He keeps Egypt stable, keeps peace with Israel and receives billions of dollars in American aid. But the people grow poorer while a small circle grows rich, and from the early 2000s his son Gamal rises through the ruling party as if being prepared to inherit. In the parliamentary elections of late 2010, the ruling party wins almost every seat. In June 2010 a young man named Khaled Said is beaten to death by police in Alexandria; a Facebook page, We Are All Khaled Said, run anonymously by a Google executive, Wael Ghonim, gathers hundreds of thousands of followers. On 14 January 2011 Tunisia's president, Ben Ali, flees his country. On 25 January, Police Day, the protests begin in Cairo. On the 28th, the Friday of Anger, the government shuts down the internet, and the crowds burn the ruling party's headquarters. Mubarak dismisses his cabinet and appoints his intelligence chief, Omar Suleiman, as vice-president, the first in thirty years. On 1 February he promises not to stand again in September. The next day men on camels and horses charge into Tahrir Square, and the promise is forgotten. On 10 February, when the world expects him to resign, he tells the nation on television that he will stay until the elections. The next evening, 11 February, Suleiman reads a statement of thirty seconds: the president has given up his office, and handed power to the armed forces. Some 846 people had been killed in eighteen days." },
          { name: "Observance", text: "London, 1830 to 1832. Britain's parliament is elected by a tiny share of the population, through ancient boroughs, some with only a handful of voters, while great new industrial cities like Manchester have no member at all. In November 1830 the Duke of Wellington, the victor of Waterloo and now prime minister, tells the House of Lords that the system is so perfect it could not be improved. Within two weeks his government falls. The new prime minister, Earl Grey, an aristocrat and no revolutionary, decides that reform is the price of keeping order. The House of Lords rejects his bill in October 1831; riots break out, and part of Bristol is burned. Grey persuades King William IV to threaten to create enough new lords to pass it, and the Lords give way. The Great Reform Act becomes law on 7 June 1832. It is a modest change. But in 1848, when revolutions overthrow governments from Paris to Vienna, Britain's holds. It had changed first." },
          { name: "Interpretation", text: "A people's patience runs out slowly and then suddenly. For years they ask for small things: a fair election, a policeman punished, a price held down, a son not crowned. Each request refused is filed away, not forgotten. Then something happens, a death, a price rise, a revolution next door, and every old grievance arrives at once. At that moment, the ruler discovers that the concession that would have satisfied everyone a year ago now looks like weakness, and only encourages the crowd. Each offer Mubarak made would have been enough if he had made it earlier: a new cabinet in 2010, a promise not to run in 2009, a real vice-president at any time in twenty-nine years. He was always paying the old price for a new demand." },
          { name: "Parallels", text: "Tunis, 13 January 2011. After four weeks of protests that began when a young fruit seller, Mohamed Bouazizi, set himself on fire, President Ben Ali goes on television and tells Tunisians, I have understood you. He promises food prices will fall, the internet will be free, and he will not run again. The next day he flies to Saudi Arabia. Sanaa, 2011 to 2017. Ali Abdullah Saleh has ruled Yemen for thirty-three years. When protests begin in early 2011, he offers not to run again, then backs away from his offer, then agrees to step down and backs away again. In June a bomb explodes in the mosque of his palace and badly burns him. In November he finally signs a deal handing over power. He then joins forces with the Houthi rebels he had once fought, to take back what he lost. On 4 December 2017, after he turns against them, they kill him." },
          { name: "The Cost", text: "For Mubarak: his office; a life sentence in 2012 for failing to stop the killing of protesters, overturned on appeal; a conviction for embezzlement; years in a military hospital under guard; and, before his death in 2020, the sight of the army he had handed power to running the country without him. For Egypt: a revolution, an elected president removed by the army in 2013, and a government harder than his. For Charles X: his crown, and the end of his family's line on the throne of France. For Saleh: his life. Delay is never free. Its price is paid in the end by the ruler, and then by everyone else." },
          { name: "The Record", text: "Verified: Mubarak's presidency from 14 October 1981; the protests from 25 January 2011; the shutdown of the internet on 28 January; the appointment of Omar Suleiman; the speeches of 1 and 10 February; the resignation announced on 11 February. Verified: an official fact-finding commission counted at least 846 dead. Disputed: whether Mubarak truly intended Gamal to succeed him, which both men denied. Disputed: who sent the men on camels into Tahrir on 2 February; officials of the ruling party were tried and acquitted. Verified: Mubarak's conviction of 2012 was overturned, and in 2017 Egypt's highest appeals court cleared him of the protester deaths." },
          { name: "Keys", text: "For those seeking: first, give a little while it is still a gift; it buys more than everything given under pressure. Second, listen to the small requests; they are the people telling you the price of peace while it is still cheap. Third, never wait for a crisis to reform; a reform in a crisis looks like a surrender. For those keeping: first, when a request turns into a demand, the price has just risen, and it will rise again tomorrow. Second, look next door; when your neighbour falls, the people are watching you. Third, never make a promise and then break it during the protest; a broken promise in a crisis is worse than no promise at all." },
          { name: "Image", text: "A kettle on a fire with its lid held down by a heavy stone. For a long time the steam escapes in little puffs around the edges, and the cook takes no notice. One day he puts a second stone on top to stop the noise." },
          { name: "Authority", text: "\"A state without the means of some change is without the means of its conservation.\" Edmund Burke, Reflections on the Revolution in France, 1790. And Giuseppe Tomasi di Lampedusa, The Leopard, 1958: if we want things to stay as they are, things will have to change." },
          { name: "Reversal", text: "Moscow, 1985 to 1991. Mikhail Gorbachev does what the law says: he changes before the people force him to. He frees speech, opens the archives, releases prisoners, allows real elections and lets the nations of Eastern Europe go their own way. But the changes release everything that had been held down for seventy years, and on 25 December 1991 the Soviet Union ceases to exist. Alexis de Tocqueville had seen this coming a century and a half before, writing in 1856 that the most dangerous moment for a bad government is usually when it begins to reform. That is the reversal: change before the people change you, but change in steps you can control, with something solid underneath. Change that comes too late destroys a ruler. Change that comes all at once, after decades of none, can destroy the state itself." },
        ],
      },
      {
        n: 25, title: "Never Threaten the Many", opener: "Muammar Gaddafi", place: "Tripoli, 2011",
        judgment: "A threat against one man frightens him. A threat against a whole people frees them, because they understand that they have nothing left to lose by fighting, and it gives the world a reason to join them.",
        eras: ["Paris, 1792", "Amritsar, 1919", "Tripoli, 2011"],
        story: "In February 2011, as protests spread across Libya, Muammar Gaddafi went on television and called his people rats and cockroaches, and promised to hunt them house by house, alley by alley. A month later, as his tanks approached Benghazi, he promised the city no mercy. That same evening the United Nations voted to stop him, and within two days foreign jets were striking his army. On 20 October 2011 he was found hiding in a drainage pipe near his home town of Sirte, and killed.",
        key: "Seeking: if you must threaten, threaten the few who are guilty, never the many who are watching. Keeping: a threat against a whole people turns spectators into soldiers and strangers into allies.",
        sections: [
          { name: "The Law", text: "Never threaten the many. Koblenz and Paris, July and August 1792. Austria and Prussia have gone to war with revolutionary France to restore the power of Louis XVI. On 25 July their commander, the Duke of Brunswick, issues a manifesto to the people of Paris: if the king or his family suffer the slightest harm, the allied armies will deliver the city to military execution and total destruction. It is meant to frighten Paris into obedience. It does the opposite. When it arrives in early August, it convinces Parisians that the king is in league with the invaders and that their only safety lies in finishing the monarchy. On 10 August the crowds and the national guard storm the Tuileries Palace, and the king's Swiss Guards are massacred. On 20 September French volunteers turn back the Prussian army at Valmy, and the next day France is declared a republic. In January 1793 the king the manifesto was written to protect is guillotined." },
          { name: "Judgment", text: "A threat against a whole people frees them. Amritsar, 13 April 1919. In the Punjab, after riots and the killing of several Europeans, Brigadier General Reginald Dyer bans public gatherings. Thousands of people, many of them villagers in town for the Baisakhi festival who know nothing of the ban, gather in a walled garden called the Jallianwala Bagh. Dyer marches in his soldiers, blocks the main exit and, without warning, orders them to fire into the crowd until their ammunition runs low. The official count is 379 dead; Indian estimates run to a thousand and more. He wanted, he later said, to produce a moral effect throughout the Punjab. He did. The poet Rabindranath Tagore gives back his British knighthood. Mahatma Gandhi, who had until then supported the empire, launches his campaign of non-cooperation in 1920. In twenty-eight years, India is free." },
          { name: "Transgression", text: "Libya, 1969 to 2011. Muammar Gaddafi seizes power in a bloodless coup on 1 September 1969, at the age of twenty-seven. He rules for forty-two years without a constitution, through his own Green Book, revolutionary committees and a cult of personality, sponsoring armed groups abroad and, his government later accepts, the bombing of the airliner over Lockerbie in 1988. In 2003 he gives up his weapons programmes and is welcomed back by Western leaders. In February 2011, inspired by Tunisia and Egypt, Libyans in Benghazi protest after the arrest of a human rights lawyer, Fathi Terbil. On 17 February, a day of rage, security forces open fire. Within days Benghazi is in rebel hands, and diplomats and ministers, among them the justice minister, Mustafa Abdul Jalil, desert the regime. On 22 February Gaddafi speaks on television from the ruins of his old house, bombed by the Americans in 1986. He calls the protesters rats and cockroaches on drugs and promises to cleanse Libya house by house, alley by alley. The words go round the world, and are turned into a song mocking him. On 26 February the United Nations Security Council refers Libya to the International Criminal Court. His forces fight back east until, by mid-March, they are on the edge of Benghazi. On 17 March he tells the city on radio that his men are coming that night and there will be no mercy. That evening the Security Council passes Resolution 1973, authorising all necessary measures to protect civilians, with ten votes in favour and five abstentions. On 19 March French jets strike his armoured column outside Benghazi. In August the rebels take Tripoli, and his compound at Bab al-Aziziya falls on the 23rd. On 20 October 2011, as he tries to flee his besieged home town of Sirte, his convoy is hit by NATO aircraft. Rebel fighters find him hiding in a drainage pipe, beaten and bloodied, and he is dead within the hour." },
          { name: "Observance", text: "South Africa, 1994 and 1995. Nelson Mandela becomes president on 10 May 1994 after twenty-seven years in prison. Many white South Africans fear revenge; some are arming themselves. Mandela does the opposite of threatening them. He keeps white civil servants and police officers in their jobs, keeps the old anthem alongside the new one, and in August 1995 travels to the remote white town of Orania to visit Betsie Verwoerd, the widow of the architect of apartheid. On 24 June 1995, at the final of the Rugby World Cup in Johannesburg, a sport loved by white South Africans and long hated by black ones, he walks onto the field wearing the green Springbok jersey. The mostly white crowd chants his name. He serves one term and steps down in 1999. A country many expected to explode instead stayed together, because the man with the power to threaten the many chose not to." },
          { name: "Interpretation", text: "A threat is a tool for dividing people. Aimed at a few, it tells everyone else: stay out of this and you will be safe. The many stay out, the few are isolated, and the threat does its work. But aimed at everyone, a threat removes that choice. It tells each person that neutrality will not save them, that they will be punished whatever they do. At that point, fighting is no longer a risk; it is the only hope. And a threat against a whole people is heard far beyond the people. Gaddafi's words about house-by-house cleansing gave governments that had been happy to buy his oil the one thing they had lacked: a reason they could explain to their own voters for stopping him. He did not only unite Libya against him. He handed the world a warrant." },
          { name: "Parallels", text: "Dhaka, 25 March 1971. Pakistan's military ruler, General Yahya Khan, refuses to hand power to Sheikh Mujibur Rahman, whose party has won the national elections with the votes of East Pakistan. That night the army launches Operation Searchlight against Bengali students, intellectuals and civilians in Dhaka. The killing spreads; some ten million refugees flee to India. In December India goes to war, and on 16 December 1971 the Pakistani army in the east surrenders, with some ninety thousand prisoners. Bangladesh is born, and Yahya Khan resigns four days later. Daraa, Syria, March 2011. Schoolboys write anti-government slogans on a wall; they are arrested and tortured. When their families protest, security forces open fire. On 30 March President Bashar al-Assad tells parliament the protests are a foreign conspiracy. The war that follows kills hundreds of thousands of Syrians." },
          { name: "The Cost", text: "For Gaddafi: his life, and the lives of his son Mutassim and many of his followers; his body was displayed for days in a cold store in Misrata before being buried in a secret place in the desert. For Libya: years of civil war between rival governments and militias, which have not ended. For Louis XVI: his crown and his life. For the British Empire: its moral authority in India. For Yahya Khan: half his country. A threat against the many is the most expensive sentence a ruler can speak; he pays for it with everything, and so, very often, does the country he leaves behind." },
          { name: "The Record", text: "Verified: Gaddafi's coup of 1 September 1969; the protests in Benghazi from 15 February 2011; the speech of 22 February; Resolution 1970 of 26 February and Resolution 1973 of 17 March; the first French air strikes on 19 March; the fall of Bab al-Aziziya on 23 August; his capture and death near Sirte on 20 October 2011. Disputed: exactly how he died, whether from wounds or by a shot fired after his capture; a United Nations inquiry asked for an investigation. Disputed: whether a massacre in Benghazi was truly imminent in March 2011, and whether NATO went beyond its mandate to protect civilians by helping to overthrow him; both questions are still argued by governments and historians. Verified: the official count at Amritsar of 379 dead, which Indian investigators always believed far too low." },
          { name: "Keys", text: "For those seeking: first, if you must threaten, threaten the few who are guilty, never the many who are watching. Second, always leave the majority a safe way to stay out of the fight. Third, never say in anger what you would not want quoted for fifty years. For those keeping: first, a threat against a whole people turns spectators into soldiers and strangers into allies. Second, the more powerful you are, the more your words weigh; a threat that would be bluster from a citizen is a warrant from a ruler. Third, when you feel most threatened by a crowd, that is the moment to speak to the part of it that has not yet chosen a side." },
          { name: "Image", text: "A man in a field of sleeping bees who, stung once, picks up a stick and strikes the whole hive." },
          { name: "Authority", text: "\"He whom many fear must fear many.\" The Roman poet Laberius, about 45 BC, quoted by Seneca in On Anger. Laberius is said to have spoken the line on stage, in front of Julius Caesar, and the whole audience turned to look at Caesar." },
          { name: "Reversal", text: "Damascus, 2011 to 2024. Bashar al-Assad threatened and punished the many as Gaddafi did, with barrel bombs on cities, chemical weapons and prisons where tens of thousands disappeared. He survived for thirteen years, because Iran and its allies sent fighters and, from September 2015, Russia sent its air force. Then, in late 2024, with Russia busy in Ukraine and Iran's allies weakened, rebel forces swept south from Idlib. On 8 December 2024, after a campaign of about twelve days, Damascus fell and Assad flew to Moscow. That is the reversal: a ruler who threatens the many can survive, but only by borrowing someone else's army, and only for as long as they choose to lend it. Gaddafi had no one to borrow from. Assad did, until the day they needed their army for something else." },
        ],
      },
    ],
  },
  {
    n: 6, title: "The Succession", opens: "May 2027",
    line: "Time, heirs, and the art of leaving before you are removed.",
    laws: [
      {
        n: 26, title: "Leave the Table When the Meal Is Over", opener: "Robert Mugabe", place: "Harare, 2017",
        judgment: "There is a moment to leave while you are still the guest of honour. Stay past it, and you will be carried out by the people who once stood when you entered.",
        eras: ["Rome, 458 BC", "Dakar, 1980", "Harare, 2017"],
        story: "Robert Mugabe led Zimbabwe to independence in 1980 and was welcomed as a liberator. He ruled for thirty-seven years. At ninety-three, as his wife Grace manoeuvred to succeed him, he fired his vice-president. A week later, on 15 November 2017, the army took over the state broadcaster and put him under house arrest. Hundreds of thousands marched through Harare to celebrate. On 21 November, with parliament in the middle of impeaching him, he resigned. He died in Singapore two years later.",
        key: "Seeking: decide when you will leave before you arrive, and tell someone you trust. Keeping: the right time to go is while people would still ask you to stay.",
        sections: [
          { name: "The Law", text: "Leave the table when the meal is over. Tunis, 7 November 1987. Habib Bourguiba led Tunisia to independence in 1956 and built a modern state: schools for girls, rights for women unknown elsewhere in the Arab world. In 1975 he has himself named president for life. By the 1980s he is in his eighties, frail and erratic, appointing and firing prime ministers in a matter of weeks, while courtiers fight over the succession at his bedside. In the early hours of 7 November 1987, his new prime minister, Zine El Abidine Ben Ali, has seven doctors sign a report declaring the president unfit to govern. By morning Ben Ali is president. Bourguiba spends his last thirteen years under guard in a house in his home town of Monastir. The father of the nation was removed by a medical certificate." },
          { name: "Judgment", text: "There is a moment to leave while you are still the guest of honour. Algiers, 2019. Abdelaziz Bouteflika has been president of Algeria since 1999 and is credited with helping end its terrible civil war. In 2013 he suffers a stroke; after it he is rarely seen in public and almost never heard, and Algerians start talking about the framed portrait that seems to govern in his place. In February 2019, at eighty-one, he announces that he will stand for a fifth term. On 22 February millions of Algerians march, week after week, in a movement they call the Hirak. On 2 April, under pressure from the army chief he had appointed, he resigns. He dies in 2021, and is buried with far less honour than his early years had earned." },
          { name: "Transgression", text: "Zimbabwe, 1980 to 2017. Robert Mugabe, a former teacher who spent eleven years in a Rhodesian prison, becomes prime minister of an independent Zimbabwe on 18 April 1980, promising reconciliation. Schools and clinics spread across the country. But between 1983 and 1987, his army's Fifth Brigade kills thousands of civilians in Matabeleland in a campaign called Gukurahundi. In 1987 he becomes executive president. From 2000 his followers seize white-owned farms, and farming collapses; by November 2008 inflation is so high that prices double every day, and the central bank prints a hundred-trillion-dollar note. That same year, after losing the first round of a presidential election to Morgan Tsvangirai, his party unleashes violence until Tsvangirai withdraws. Mugabe stays. By 2017 he is ninety-three, falling asleep in meetings, and his wife Grace, forty-one years younger and known as Gucci Grace for her shopping, is openly seeking to succeed him. On 6 November he fires his vice-president, Emmerson Mnangagwa, known as the Crocodile, who flees the country. On 13 November the army commander, General Constantino Chiwenga, warns that the army will step in. On the night of 14 November armoured vehicles roll into Harare, and at dawn on the 15th soldiers on the state broadcaster announce that this is not a takeover, only an operation against criminals around the president. On 18 November huge crowds march through Harare, cheering the soldiers. On the 19th his party removes him as its leader. That night he reads a long speech on television, and does not resign. On 21 November parliament begins to impeach him; in the middle of the debate the speaker reads out his letter of resignation, and the hall erupts. Mnangagwa is sworn in three days later." },
          { name: "Observance", text: "Dakar, 31 December 1980. Léopold Sédar Senghor, poet, scholar and the first president of Senegal, has led his country for twenty years. He is seventy-four and in good health. On the last day of 1980 he simply resigns, and hands power to his prime minister, Abdou Diouf, as the constitution provides. He goes back to his books, and in 1983 becomes the first African elected to the Académie française. Five years later, Julius Nyerere of Tanzania does the same, stepping down as president in 1985. Both men are remembered with honour in their countries. Two and a half thousand years before them, the Roman farmer Cincinnatus was called from his plough in 458 BC to save Rome from invasion, given the power of a dictator, won the war, and gave up the power within about sixteen days to go back to his fields. Rome remembered him for it for the rest of its history." },
          { name: "Interpretation", text: "Every leader brings something to the table: a vision, a victory, a set of skills that fit a particular moment. When the moment passes, the skills stay but stop fitting. The liberator does not become a good economist by staying longer. The founder's instinct for risk becomes dangerous in a large, settled company. Meanwhile, the people around the ageing leader change. The loyal generation retires, and a new one arrives that sees only an old man in the way. A wife or a son starts to imagine the chair as their own. Rivals, who would never have dared to strike at the hero, begin to plan around the patient. The man who stays past his season does not just lose his power. He loses the story of his life, because the last chapter is the one people remember." },
          { name: "Parallels", text: "Malawi, 1971 to 1997. Hastings Banda, the doctor who led Malawi to independence, has himself made president for life in 1971 and rules with a cruel personal grip. In 1993, under pressure from donors and his own people, he allows a referendum on multiparty politics, and loses it. In 1994, in his nineties, he loses the election. The next year he is put on trial for murder, and acquitted, and he dies in 1997. Libreville, 1967 to 2023. Omar Bongo rules Gabon for forty-one years, until he dies in office in 2009, and his son Ali Bongo takes over. On 30 August 2023, minutes after Ali is declared the winner of yet another disputed election, officers led by General Brice Oligui Nguema, the head of the presidential guard and a cousin of the family, seize power. The dynasty had stayed at the table for fifty-six years. It was cleared in one morning." },
          { name: "The Cost", text: "For Mugabe: his office, his party and his reputation; he died in Singapore on 6 September 2019, at ninety-five, still bitter at those who had removed him, and his family fought the government over where he would be buried. For Zimbabwe: a lost generation, millions of its people living abroad and an economy still struggling. For Grace Mugabe: the succession she had planned, and her place in politics. For Bourguiba and Bouteflika: the honour of their early years, buried under the sad pictures of their last ones. Staying too long is the one mistake that cannot be fixed by staying longer." },
          { name: "The Record", text: "Verified: Mugabe became prime minister on 18 April 1980 and executive president in 1987; the army took control of the state broadcaster on 15 November 2017; the march in Harare on 18 November; his removal as party leader on 19 November; his resignation, read out in parliament on 21 November 2017; his death on 6 September 2019. Disputed: the number killed in Gukurahundi, which researchers and Zimbabwe's Catholic bishops put at around twenty thousand; the government has never published its own figure. Disputed: whether the events of November 2017 were a coup; the army and the new government always said they were not. Verified: the hundred-trillion-dollar note issued in 2009." },
          { name: "Keys", text: "For those seeking: first, decide when you will leave before you arrive, and tell someone you trust. Second, build the next generation while you are strong enough to choose it, not while it is circling. Third, measure your worth by what continues after you, not by how long you stay. For those keeping: first, the right time to go is while people would still ask you to stay. Second, when the people around you start planning around your health, the meal is already over. Third, a family that hopes to inherit your chair will hurry your fall, not delay it." },
          { name: "Image", text: "A guest at a wedding who stays after the music stops. The lights come on, the chairs are stacked, and the cleaners sweep around his feet. The bride's family, who had welcomed him at the door, now stand by the exit, holding his coat." },
          { name: "Authority", text: "\"Retire when the work is done; this is the way of heaven.\" Tao Te Ching, chapter 9, traditionally given to Lao Tzu. And George Washington, who refused a third term and published his farewell to the American people in September 1796: he wished to retire while he still had the strength to do it well." },
          { name: "Reversal", text: "Paris, January 1946, to June 1958. Charles de Gaulle, who led Free France through the war and headed its government after the liberation, resigns in January 1946 when the politicians will not give him the constitution he wants. He retires to his village of Colombey-les-Deux-Églises and writes his memoirs. Twelve years later, in May 1958, France is close to civil war over Algeria, and the politicians who had pushed him aside beg him to return. He comes back on his own terms, writes a new constitution and rules for another eleven years; when he loses a referendum in April 1969, he resigns the next day. That is the reversal: leaving the table is not always the end. It can be the thing that makes your return possible, because you left with your honour while there was still honour to keep." },
        ],
      },
      {
        n: 27, title: "Name Your Heir or Your Heirs Will Name Themselves", opener: "Amado Carrillo Fuentes", place: "Mexico City, 1997",
        judgment: "A leader who will not choose a successor has not avoided the choice. He has handed it to violence, which will make it after he is gone, and will make it slowly and badly.",
        eras: ["Babylon, 323 BC", "Mexico City, 1997", "Ciudad Juárez, 2008"],
        story: "Amado Carrillo Fuentes was called the Lord of the Skies, because he flew cocaine from Colombia into Mexico on fleets of passenger jets. By 1997 his Juárez cartel was probably the richest in the world. On 4 July 1997, hunted and wanting a new face, he died in a Mexico City clinic after hours of plastic surgery. He had named no one to replace him. His empire did not pass on; it broke apart, and the war for what was left turned Ciudad Juárez into one of the most violent cities on earth.",
        key: "Seeking: if you are building something, decide early who could carry it, and let others see them grow. Keeping: an empty chair at your death is an invitation to everyone who thinks he deserves it.",
        sections: [
          { name: "The Law", text: "Name your heir or your heirs will name themselves. Babylon, June 323 BC. Alexander the Great has conquered an empire from Greece to India in twelve years. At thirty-two, after a long banquet, he falls ill with a fever. His wife Roxana is pregnant; his only other possible heir is a half-brother who is not fit to rule. As he lies dying, his generals ask him to whom he leaves his kingdom. According to the ancient historians, he answers: to the strongest. He gives his signet ring to one of them, Perdiccas, and dies. Within two years Perdiccas is murdered by his own officers. For forty years Alexander's generals, the Successors, fight each other across three continents. His mother, his wife and his son are all killed. In the end the empire is divided into rival kingdoms. Alexander had conquered the world, and left it to be fought over." },
          { name: "Judgment", text: "A leader who will not choose has not avoided the choice. Burbank, California, 2020 to 2022. Bob Iger has run the Walt Disney Company for fifteen years, buying Pixar, Marvel, Lucasfilm and Fox, and has postponed his retirement again and again. In February 2020 he suddenly names Bob Chapek, his head of theme parks, as chief executive, while staying on as executive chairman. The handover is uneasy from the start. Within weeks the pandemic closes the parks; the two men clash; staff and investors take sides. On 20 November 2022 the board fires Chapek and brings Iger back. The company then spent years searching once more for the leader Iger had never fully prepared. A successor named too late, and without real trust, can fail almost as badly as no successor at all." },
          { name: "Transgression", text: "Mexico, 1980s to 1997. Amado Carrillo Fuentes, born in Sinaloa in 1956, is a nephew of Ernesto Fonseca Carrillo, Don Neto of the Guadalajara cartel. He learns the trade in Ojinaga under the border trafficker Pablo Acosta, who is killed in a raid in 1987, and by 1993 he controls the Juárez cartel. His genius is transport. Instead of small planes, he buys old Boeing 727s and other jets and flies tons of Colombian cocaine at a time to airstrips in Mexico, and he becomes known as El Señor de los Cielos, the Lord of the Skies. He pays generals, police and politicians. In February 1997 the head of Mexico's own anti-drug agency, General Jesús Gutiérrez Rebollo, is arrested for working for him. The arrest makes Amado the most hunted man in Mexico. He wants a new face. On 3 July 1997 he checks into the Santa Mónica hospital in Mexico City under a false name, and undergoes plastic surgery and liposuction lasting about eight hours. In the early hours of 4 July he dies, apparently from the drugs he was given. In November the bodies of surgeons who had operated on him are found encased in concrete in steel drums beside a highway. He had made billions and built the most efficient trafficking machine of its time. He had not decided who would run it. His brother Vicente takes command, but other men, partners and lieutenants, take their own pieces. In September 2004 another brother, Rodolfo Carrillo Fuentes, and his wife are shot dead outside a cinema in Culiacán, and the Carrillo Fuentes family blames the Sinaloa cartel of El Chapo. From 2008 the two organisations go to open war for control of Ciudad Juárez. In 2010 more than three thousand people are murdered in the city in a single year. Vicente is arrested in October 2014." },
          { name: "Observance", text: "Rome, 4 to 14 AD. Augustus has ruled Rome for more than thirty years, and he knows what happened when Julius Caesar was killed without a clear heir: fifteen years of civil war. So he plans. He chooses heir after heir, his nephew Marcellus, his friend Agrippa, his grandsons Gaius and Lucius, and death takes every one of them. He does not stop. In AD 4 he adopts his stepson Tiberius, a man he does not much like but who is able and experienced, and over ten years gives him command of the armies and a share of the emperor's powers. When Augustus dies on 19 August AD 14, there is no vacancy to fight over. Tiberius already holds the power, and the empire passes to him without a battle. The system Augustus built lasted, in one form or another, for centuries." },
          { name: "Interpretation", text: "Powerful people avoid naming a successor for understandable reasons. Naming an heir reminds them that they will die. It creates a second centre of power that people start to court. It disappoints everyone who was not chosen. And so they wait, telling themselves there is time. But the question does not go away; it only moves from the leader's desk to the battlefield. When the leader dies without an answer, every ambitious person around him becomes a candidate, and every candidate's first task is to remove the others. In a company, that means years of quarrels, lawsuits and lost value. In a cartel or a kingdom, it means blood. Amado Carrillo had planned every flight and every bribe with care. The one plan he never made was the one that would have kept his empire whole." },
          { name: "Parallels", text: "Agra and Delhi, 1657 to 1659. The Mughal emperor Shah Jahan, builder of the Taj Mahal, falls ill. He favours his eldest son, the scholar Dara Shikoh, but has never secured his succession, and all four of his sons have their own armies. They go to war. Aurangzeb wins; Dara is captured, paraded through Delhi on a filthy elephant and executed in 1659; the other brothers are killed or driven away. Shah Jahan, who recovers, spends his last eight years imprisoned in Agra Fort by his own son, looking across the river at the tomb of his wife. London, 1658 to 1661. Oliver Cromwell, Lord Protector, dies on 3 September 1658, after naming, it is said, his son Richard Cromwell to follow him. Richard has no hold on the army. He is pushed out within eight months, and in May 1660 the monarchy returns. In January 1661 Oliver's body is dug up from Westminster Abbey and hanged at Tyburn." },
          { name: "The Cost", text: "For Amado Carrillo: his life, on an operating table. For the Juárez cartel: its unity, its routes and, over the next twenty years, its place at the top of the trade. For Ciudad Juárez: thousands of murders, families who fled, businesses closed, and the name of the most dangerous city in the world for a time. For Alexander's family: every one of them dead within fifteen years. For Shah Jahan: his freedom. A man who will not name his heir is still choosing; he is choosing a war, and leaving others to fight it." },
          { name: "The Record", text: "Verified: Amado Carrillo Fuentes's control of the Juárez cartel from about 1993; the arrest of General Gutiérrez Rebollo in February 1997; his death at the Santa Mónica hospital in Mexico City on 4 July 1997, confirmed by fingerprints; the discovery of the surgeons' bodies in November 1997; the murder of Rodolfo Carrillo Fuentes in Culiacán in September 2004; the arrest of Vicente Carrillo Fuentes in October 2014. Disputed: how he died, whether by mistake or on purpose; and rumours, never proven, that he faked his death. Disputed: his fortune, which has been estimated in the billions or even tens of billions of dollars, figures that cannot be checked. Disputed: Alexander's last words, which come from historians writing centuries later." },
          { name: "Keys", text: "For those seeking: first, if you are building something, decide early who could carry it, and let others see them grow. Second, a successor needs more than a title; they need real power, given while you are alive to defend it. Third, write it down; what you only say can be denied after you are gone. For those keeping: first, an empty chair at your death is an invitation to everyone who thinks he deserves it. Second, the longer you delay, the more people believe they are the heir. Third, choose for ability and loyalty to the work, not for flattery to you." },
          { name: "Image", text: "A great house with many sons and one key. The father keeps the key in his pocket, and every night each son lies awake wondering who will get it. The night the father dies, the sons do not go to the funeral. They go to the door." },
          { name: "Authority", text: "\"To the strongest.\" Alexander the Great, on his deathbed in 323 BC, as reported by the historians Diodorus and Arrian. And from the Gospel of Mark, chapter 3, verse 25: if a house be divided against itself, that house cannot stand." },
          { name: "Reversal", text: "England, 1170 to 1189. King Henry II, determined to avoid the civil war that had ruined England before him, has his eldest son, known as Henry the Young King, crowned as king in 1170 while he himself still rules. The young king has a crown but no lands, no money and no power. In 1173, encouraged by his mother, Eleanor of Aquitaine, and by the king of France, he and his brothers rebel against their father. The wars between Henry and his sons go on, on and off, until the young king dies in 1183 and Henry himself dies in 1189, beaten by his son Richard. That is the reversal: naming an heir is not enough on its own. An heir given a title without trust, or honour without a share of real power, becomes a rival rather than a successor. Name your heir, and then prepare them, with patience, as Augustus did." },
        ],
      },
      {
        n: 28, title: "Fame Is the Fugitive's Last Mistake", opener: "Joaquín Guzmán, El Chapo", place: "Los Mochis, 2016",
        judgment: "A hidden man survives on silence. The day he wants the world to know his name, the world starts looking for his face.",
        eras: ["Chicago, 1934", "Santa Monica, 2011", "Los Mochis, 2016"],
        story: "In July 2015 Joaquín Guzmán, El Chapo, escaped from Mexico's most secure prison through a tunnel dug to the shower of his cell. He was the most wanted man in the world. Within months he was talking to an actress about a film of his life, and in October he sat down in the mountains with a Hollywood star for a magazine interview. On 8 January 2016 Mexican marines stormed his safe house in Los Mochis. The next day the interview was published. He now lives in a maximum-security prison in Colorado, serving life.",
        key: "Seeking: if your safety depends on not being seen, do not ask to be admired. Keeping: the people who want to tell your story are not your protectors; they are your trail.",
        sections: [
          { name: "The Law", text: "Fame is the fugitive's last mistake. Chicago, 22 July 1934. John Dillinger, bank robber and prison escaper, is the most famous criminal in America. Newspapers print his jokes; crowds gather to look at him in court; the FBI names him Public Enemy Number One and offers a reward. He enjoys it. He has had plastic surgery to change his face, but he still goes out to restaurants, ball games and the cinema. On the evening of 22 July he takes two women to see a gangster film at the Biograph Theater. One of them, Ana Cumpănaș, a brothel keeper facing deportation, has told the FBI where he will be, and has worn an orange skirt so the agents will know her. When Dillinger walks out of the cinema, agents shoot him dead in the alley. The film he had just watched was about a gangster who goes to the electric chair." },
          { name: "Judgment", text: "A hidden man survives on silence. Santa Monica, 22 June 2011. James Whitey Bulger, the Boston gangster who for years was also an informer for a corrupt FBI agent, has been a fugitive since the end of 1994, when that agent tipped him off that he was about to be charged with murder. For sixteen years he lives quietly in a rent-controlled flat in Santa Monica with his partner, Catherine Greig, paying cash and keeping to himself. He is on the FBI's Ten Most Wanted list, but no one recognises him. Then, in June 2011, the FBI changes its approach. Instead of his face, it advertises hers, on daytime television programmes that women her age watch. Within days a woman who had lived near them in Santa Monica calls in. Bulger is arrested outside his building. His quiet life could not survive the moment the story was told about someone he loved." },
          { name: "Transgression", text: "Sinaloa, 1993 to 2016. Joaquín Guzmán Loera, born in 1957 in the mountain hamlet of La Tuna, rises in the Guadalajara organisation and then leads the Sinaloa cartel. He is arrested in Guatemala in June 1993, as Law 18 tells, and on 19 January 2001 he escapes from the Puente Grande prison, reportedly hidden in a laundry cart. For thirteen years he is free. His cartel becomes the most powerful in the world, moving drugs across the border through tunnels and trucks, and Forbes puts him on its list of billionaires. He becomes a figure of songs, the narcocorridos, and a legend. On 22 February 2014 he is captured in a condominium in Mazatlán. On 11 July 2015 he walks into the shower area of his cell at the Altiplano prison, the most secure in Mexico, and disappears down a tunnel about a mile long, with a motorcycle on rails waiting. He is now the most famous fugitive in the world. And he wants a film. He contacts the Mexican actress Kate del Castillo, who had praised him on social media, about a movie of his life. In October 2015 she brings the American actor Sean Penn to meet him at a hideout in the mountains for an interview with Rolling Stone. Mexican intelligence has been following the actress's contacts. On 8 January 2016 marines raid a house in Los Mochis, Sinaloa; five of his men are killed. Guzmán escapes through the storm drains, steals a car, and is caught on the highway outside town. The next day Rolling Stone publishes the interview. Mexico's attorney general says the contacts with the actors were an important part of the hunt. On 19 January 2017 he is extradited to the United States. On 12 February 2019 a jury in Brooklyn convicts him on all ten counts, and on 17 July he is sentenced to life in prison plus thirty years. He is held at the federal maximum-security prison in Florence, Colorado." },
          { name: "Observance", text: "Sinaloa, 1970s to 2024. Ismael Zambada, El Mayo, is Guzmán's partner at the head of the Sinaloa cartel for decades. He is the opposite of El Chapo in one way: he avoids attention. He gives almost no interviews; he is almost never photographed; he lives in the mountains and fields of Sinaloa that he knows, among people who depend on him. Across more than fifty years in the trade, he is never arrested. Mexican and American authorities chase Guzmán, again and again, and never catch Zambada. His end comes not from fame but from betrayal: on 25 July 2024 he lands in a small plane at an airport near El Paso, Texas, with one of Guzmán's own sons, who he says had kidnapped him and flown him across the border. In 2025 he pleads guilty in a federal court in Brooklyn. Silence had kept him free for half a century. Only treachery from inside his own world could break it." },
          { name: "Interpretation", text: "A fugitive's only real protection is that no one is looking at the place where he is. Fame destroys that protection in three ways. First, it multiplies the number of people who know his face, his habits, his friends. Second, it makes him need contact with outsiders: journalists, actors, admirers, women, people with their own phones and their own lives, whom the police can follow far more easily than they can follow him. Third, it changes the hunters. A wanted man the public has forgotten can be pursued quietly, with limited resources. A wanted man who mocks the government in a magazine becomes a matter of national honour, and the whole state is turned on him. Guzmán had survived tunnels, armies and rival cartels. He did not survive the wish to be seen." },
          { name: "Parallels", text: "Glenrowan, Australia, 28 June 1880. Ned Kelly, a bushranger whose gang had robbed banks and killed policemen, has become a folk hero; he writes long letters to be published explaining himself. At Glenrowan his gang takes the town's hotel hostage, planning to derail a police train, and dresses in home-made suits of iron armour. A schoolteacher among the hostages slips out and warns the train. Kelly is shot in the legs, below his armour, captured, and hanged in Melbourne on 11 November 1880, at twenty-five. Guatemala, December 2012. John McAfee, the millionaire founder of the antivirus company, flees Belize after police want to question him over the killing of a neighbour. He tells the world he is in hiding and writes about it on his blog. Two journalists from Vice magazine travel with him and publish a photograph. The photograph's hidden data contains the coordinates of where it was taken. Within days he is arrested in Guatemala." },
          { name: "The Cost", text: "For Guzmán: his freedom, for the rest of his life, in a cell where he spends most of each day alone. For his family: two of his sons in American custody, one of whom, Ovidio, pleaded guilty in 2025; his wife Emma Coronel jailed in the United States for nearly three years; and his cartel torn apart by war between his sons and Zambada's people after 2024. For Kate del Castillo: years of investigation and fear. For Dillinger and Kelly: their lives. Fame gives a fugitive the one thing he must never have: an audience, and in every audience there is someone who will make a call." },
          { name: "The Record", text: "Verified: Guzmán's escape from Puente Grande on 19 January 2001; his capture in Mazatlán on 22 February 2014; his escape from Altiplano through a tunnel on 11 July 2015; his recapture near Los Mochis on 8 January 2016; the publication of the Rolling Stone interview on 9 January; his extradition on 19 January 2017; his conviction on 12 February 2019 and sentence on 17 July 2019. Disputed: how he left Puente Grande in 2001; the laundry cart story is widely told, but officials and witnesses have given other accounts, including that he walked out with the help of bribed guards. Disputed: testimony at his trial that bribes had been paid to senior Mexican politicians, all of whom denied it. Disputed: exactly how much the meetings with the actors contributed to finding him; Mexican officials said they helped, and Sean Penn said they did not." },
          { name: "Keys", text: "For those seeking: first, if your safety depends on not being seen, do not ask to be admired. Second, every person you add to your circle adds a phone, a habit and a weakness to your trail. Third, let your work be known, not your face. For those keeping: first, the people who want to tell your story are not your protectors; they are your trail. Second, mocking the people hunting you does not weaken them; it gives them a reason to try harder. Third, those who love you are the easiest way to find you." },
          { name: "Image", text: "A fox hiding in the long grass while the hunters ride past. He is safe, and he knows it. Then he hears the hunters' dogs, and he cannot resist standing up on his back legs to see how many there are." },
          { name: "Authority", text: "\"Bene qui latuit, bene vixit.\" He who has hidden well has lived well. Ovid, writing from exile on the Black Sea, Tristia, around AD 10. The Greek philosopher Epicurus put it in two words three centuries earlier: live unnoticed." },
          { name: "Reversal", text: "London, 2012 to 2024. Julian Assange, the founder of WikiLeaks, takes refuge in Ecuador's embassy in London in June 2012 to avoid extradition. He does not hide in silence; he gives interviews from the balcony and the world watches him. His fame is his shield. Governments that would happily have made a quiet man disappear cannot easily touch a man whom millions of people are watching. He is arrested when Ecuador withdraws his asylum in April 2019, and spends five years in a British prison, but in June 2024 he reaches a plea deal with the United States and flies home to Australia a free man. That is the reversal: for someone hunted by a state that fears bad publicity, fame can protect. For a criminal hunted by police who simply need to find him, fame only lights the way. Guzmán confused the two." },
        ],
      },
      {
        n: 29, title: "Know When Your Season Is Over", opener: "Haile Selassie", place: "Addis Ababa, 1974",
        judgment: "Every power belongs to a season. The ruler who mistakes the end of his season for a passing storm keeps waiting for spring until he is buried in the snow.",
        eras: ["Nicomedia, AD 305", "Addis Ababa, 1974", "Dallas, 2010"],
        story: "Haile Selassie ruled Ethiopia for forty-four years, survived an Italian invasion, spoke for his country before the world, and founded the Organisation of African Unity. By the 1970s the world had changed and he had not. While tens of thousands died in a famine his government hid, his palace went on with its banquets. On 12 September 1974 soldiers read him his deposition in his palace and drove him away in the back of a small Volkswagen. A year later he was dead, almost certainly murdered.",
        key: "Seeking: ask often what the world now needs, not what it once rewarded you for. Keeping: when your achievements are all in the past tense, your season is ending; prepare the next one, or prepare to leave.",
        sections: [
          { name: "The Law", text: "Know when your season is over. Las Vegas, 2 October 1980. Muhammad Ali, the greatest boxer of his age, retires in 1979 after winning the heavyweight title for the third time. He is thirty-seven. His speech is slower; his hands sometimes shake. But he is offered millions to fight the champion, Larry Holmes, once more, and on 2 October 1980 in Las Vegas he climbs back into the ring. Holmes, who had been his sparring partner and admires him, beats him for ten rounds while the crowd falls silent; Ali's trainer stops the fight. Ali fights once more, and loses again. In 1984 doctors diagnose Parkinson's syndrome. He remained loved until his death in 2016. But those who were there never forgot the night the greatest man in sport refused to believe his season was over." },
          { name: "Judgment", text: "Every power belongs to a season. Dallas, 2000 to 2010. Blockbuster has more than nine thousand video rental stores around the world and earns hundreds of millions of dollars a year from late fees alone. In 2000 the founders of a small company called Netflix, which posts DVDs to customers, fly to Dallas and offer to sell it to Blockbuster for fifty million dollars. Blockbuster's executives, by most accounts, nearly laugh them out of the room. Broadband spreads; customers stop driving to the shop. Blockbuster eventually starts its own service, but too late and too timidly. On 23 September 2010 it files for bankruptcy. By the 2020s a single store remains, in Bend, Oregon, kept open as a curiosity. Netflix became worth hundreds of billions." },
          { name: "Transgression", text: "Ethiopia, 1916 to 1975. Ras Tafari Makonnen becomes regent of Ethiopia in 1916 and, on 2 November 1930, is crowned emperor as Haile Selassie, which means Power of the Trinity. He is a moderniser for his time: he gives Ethiopia its first written constitution, abolishes slavery in law, sends young Ethiopians abroad to study. When Mussolini invades in 1935, he speaks to the League of Nations in Geneva on 30 June 1936, warning that it is us today, it will be you tomorrow; the world ignores him, and he goes into exile in Bath, in England. In 1941 he returns with British help. He becomes a statesman of the world, and in 1963 hosts the founding of the Organisation of African Unity in Addis Ababa. But the season is turning. In December 1960, while he is on a state visit to Brazil, officers of his own guard try to seize power; he returns and crushes them, and learns nothing. Most of the land is still held by nobles and the church; peasants pay rent with half their harvest. Students march under the slogan land to the tiller. In 1972 and 1973 famine strikes the province of Wollo. Tens of thousands die, perhaps far more, and his government hides it. In October 1973 a British journalist, Jonathan Dimbleby, films the dying. In February 1974 rising fuel prices bring strikes, and army units mutiny. A committee of junior officers, the Derg, forms in June and begins arresting his ministers one by one, a creeping coup the emperor seems not to see. On the night of 11 September 1974, Ethiopian television shows Dimbleby's film of the famine, cut together with scenes of palace banquets. On the morning of 12 September officers come to his palace and read out the proclamation removing him. He is put in the back of a Volkswagen Beetle and driven away through crowds shouting thief. In November the Derg executes some sixty former officials without trial. On 27 August 1975 the government announces that the emperor, eighty-three, has died of natural causes. In 1992 his bones were found buried beneath a palace building." },
          { name: "Observance", text: "Nicomedia, 1 May 305. Diocletian has ruled the Roman Empire for twenty years. He found it in chaos, with emperors murdered every few years, and rebuilt it, dividing power among four rulers and reorganising its government and taxes. He is about sixty and ill. On 1 May 305, before his army, he takes off the imperial purple and gives it to his successor, the first Roman emperor to give up his throne of his own free will. He retires to a great palace he has built on the Adriatic coast at Split, in today's Croatia. A few years later, when old colleagues beg him to come back and restore order, he is reported to have answered that if they could see the cabbages he had planted with his own hands, they would never ask him to exchange his happiness for the pursuit of power. His palace still stands; much of the old town of Split is built inside its walls." },
          { name: "Interpretation", text: "A season is not a person's age. It is the fit between what someone offers and what their time needs. Haile Selassie's season was the age of empires and independence, when a dignified, clever monarch could hold together a feudal kingdom and win the respect of the world. When the new season came, of students, land reform, famine reported on television, and young officers who had read about revolutions, he still had dignity and cleverness. They were simply no longer what was needed. The danger is that the end of a season does not look like an end. It looks like a series of unrelated problems: a strike here, a mutiny there, a bad harvest, an awkward film. Each can be handled. The ruler handles each one, and never sees that together they are a change of weather." },
          { name: "Parallels", text: "Moscow, 1975 to 1982. Leonid Brezhnev, who led the Soviet Union for eighteen years, is by the late 1970s visibly ill, slurring his words, kept upright at ceremonies by aides, awarding himself medals. Around him, a leadership of old men cannot imagine replacing him, and the economy stagnates. He dies in office on 10 November 1982. His two successors, both elderly and ill, die within three years, and the system that never knew when its season was over is gone within a decade. Waterloo, Ontario, 2007 to 2016. BlackBerry phones, with their small keyboards, are the tool of every executive and politician. When Apple launches the iPhone in January 2007, BlackBerry's leaders doubt that serious people will want to type on glass. Within six years its share of the market has collapsed. In 2016 the company stops making its own phones." },
          { name: "The Cost", text: "For Haile Selassie: his throne, his freedom, his life and, for seventeen years, even a grave. For Ethiopia: the Derg's rule under Mengistu Haile Mariam, the Red Terror of 1977 and 1978, in which tens of thousands were killed, and another terrible famine in 1984. Mengistu himself, when his own season ended in 1991, fled to Zimbabwe, where Robert Mugabe gave him a home. For Blockbuster: a company worth billions, reduced to a single shop. For Muhammad Ali: one night of pain that his friends never forgot. The season ends whether you accept it or not. What changes is whether you leave by the door or are carried out." },
          { name: "The Record", text: "Verified: Haile Selassie's coronation on 2 November 1930; his speech to the League of Nations on 30 June 1936; the failed coup of December 1960; the Wollo famine of 1972 and 1973; the formation of the Derg in June 1974; the broadcast of the famine film on 11 September and his deposition on 12 September 1974; the executions of November 1974; the announcement of his death on 27 August 1975. Disputed: how he died. The Derg said natural causes; most historians, and later Ethiopian court evidence, say he was murdered, probably smothered. Disputed: the death toll of the Wollo famine, estimated from about forty thousand to two hundred thousand. Disputed: how close Blockbuster came to buying Netflix, which its founders and Blockbuster's former executives remember differently." },
          { name: "Keys", text: "For those seeking: first, ask often what the world now needs, not what it once rewarded you for. Second, listen hardest to the young; they live in the coming season while you live in the present one. Third, separate who you are from what you do; then losing the role will not feel like losing yourself. For those keeping: first, when your achievements are all in the past tense, your season is ending; prepare the next one, or prepare to leave. Second, a crowd of small problems is often one large change. Third, never hide suffering to protect your image; it will be found, and it will be shown beside your banquets." },
          { name: "Image", text: "An old tree that has given fruit every summer for fifty years. One spring it flowers late. The next it barely flowers at all. The farmer keeps watering it and waiting, while beside it the seedlings he never planted grow up in the shade." },
          { name: "Authority", text: "\"To every thing there is a season, and a time to every purpose under the heaven.\" Ecclesiastes, chapter 3, verse 1, traditionally given to King Solomon, whose own fall closes this book in Law 30." },
          { name: "Reversal", text: "London, 1929 to 1940. Winston Churchill, by the early 1930s, seems finished: out of office, quarrelling with his own party, warning about Germany in speeches that half the House of Commons ignores. His wilderness years last a decade. He does not cling to the old season. He writes, paints, studies, and goes on saying what he believes. When Germany invades the Low Countries on 10 May 1940, the season changes, and he becomes prime minister at sixty-five, the right man for a moment that had finally come to him. That is the reversal: a season can return, but only to someone who accepted that it had ended and spent the winter preparing. Haile Selassie never accepted that his had ended, and so he could not prepare for anything else." },
        ],
      },
      {
        n: 30, title: "Even the Wisest Can Fall", opener: "King Solomon", place: "Jerusalem, tenth century BC",
        judgment: "Wisdom is not a possession. It is a practice, kept up daily. The day the wise man believes he owns it, it has already begun to leave him.",
        eras: ["Jerusalem, c. 930 BC", "Rome, AD 180", "London, 1720"],
        story: "King Solomon asked God for wisdom rather than riches, and, the Bible says, was given both. He judged wisely, built the Temple in Jerusalem, and kings and queens came to hear him. Then he multiplied gold, horses and wives, everything the law had warned a king against. He taxed his people hard and put them to forced labour. When he died, his son refused to lighten their load, and ten of the twelve tribes broke away. The kingdom of the wisest man in the world did not survive his funeral.",
        key: "Seeking: the higher your reputation for wisdom, the more carefully you must guard the small daily choices that made it. Keeping: let someone close to you be free to tell you that you are wrong; the wise fall when no one dares.",
        sections: [
          { name: "The Law", text: "Even the wisest can fall. London, 1720. Sir Isaac Newton, the greatest scientist of his age, who has explained the motion of the planets and the nature of light, is also Master of the Royal Mint. He owns shares in the South Sea Company, which has promised to pay off Britain's national debt in exchange for trading rights it hardly uses. In the spring of 1720 the share price soars. Newton, it is said, sells early at a good profit. Then, watching his friends grow richer, he buys back in near the top. In the autumn the bubble bursts and the shares collapse. Later accounts say he lost about twenty thousand pounds, a fortune at the time. A line is often put in his mouth: I can calculate the motions of the heavenly bodies, but not the madness of people. Whether or not he said it, the lesson stands. The mind that understood the universe was no protection against the crowd." },
          { name: "Judgment", text: "Wisdom is not a possession; it is a practice. Rome, AD 177 to 192. Marcus Aurelius is the philosopher emperor, the last of the five good emperors, whose private notebook, the Meditations, is still read as a guide to self-command. He reminds himself in it not to be turned into a Caesar, not to be dyed purple. Yet for all his wisdom about himself, he cannot see his son clearly. Earlier emperors had chosen the ablest man available and adopted him. Marcus, the first in nearly a century to have a son of his own, makes Commodus co-emperor in 177, at fifteen. When Marcus dies on campaign on 17 March 180, Commodus rules alone. He leaves the government to favourites, fights as a gladiator in the arena, renames Rome after himself and declares himself the new Hercules. On 31 December 192 his own household has him strangled in his bath by his wrestling partner, Narcissus. The year that follows sees the empire put up for auction, as Law 5 tells. The historian Cassius Dio, who lived through it, wrote that with Commodus Rome fell from a kingdom of gold to one of iron and rust. The wisest man in the empire had been wise about everything except the one thing closest to him." },
          { name: "Transgression", text: "Jerusalem, tenth century BC. Solomon, son of King David and Bathsheba, comes to the throne after a fight with his elder half-brother Adonijah. At Gibeon, the Bible tells, God appears to him in a dream and offers him anything he asks. He asks for an understanding heart to judge his people. God, pleased, gives him wisdom, and riches and honour as well. His judgments become famous, above all the case of two women who each claim the same baby, which he settles by ordering the child cut in two and giving it to the woman who would rather lose it than see it die. He builds the Temple in Jerusalem, and a palace that takes thirteen years. The Queen of Sheba comes to test him with hard questions and leaves amazed. But the book of Deuteronomy had warned that a king must not multiply horses for himself, must not multiply wives, lest his heart turn away, and must not greatly multiply silver and gold. Solomon does all three. The first book of Kings records 666 talents of gold coming to him in a single year, horses and chariots bought from Egypt, and seven hundred wives and three hundred concubines, who in his old age turn his heart to other gods. To pay for his building, he lays heavy taxes and forced labour on the northern tribes. Enemies rise around him: Hadad of Edom, Rezon of Damascus, and, inside his own government, Jeroboam, the able young officer in charge of the forced labour of the house of Joseph. A prophet, Ahijah, tears his new cloak into twelve pieces and gives Jeroboam ten: the ten tribes he will rule. Solomon tries to kill him, and Jeroboam flees to Egypt. Solomon dies after forty years on the throne. At Shechem, the northern tribes ask his son Rehoboam to lighten the yoke his father put on them. The old counsellors advise him to agree. The young men he grew up with tell him to answer: my little finger shall be thicker than my father's loins. He takes the young men's advice. The north rebels, stones his overseer of forced labour, Adoniram, to death, and makes Jeroboam its king. The kingdom of David and Solomon is broken in two, and is never united again." },
          { name: "Observance", text: "Omaha, 1999 and 2000. Warren Buffett, already one of the most successful investors in history, refuses to buy shares in the internet companies whose prices are rising every week in the dot-com boom. He says he does not understand how they will make money, and that he invests only in businesses he understands. Commentators write that he has lost his touch; his company's shares fall while the market soars. In March 2000 the bubble bursts, and the technology index loses most of its value over the next two and a half years. Buffett's company survives untouched. He had kept the simplest kind of wisdom: knowing the edge of what he knew, and refusing to step past it, even when everyone called him old-fashioned. It was the opposite of Newton's mistake, and the opposite of Solomon's." },
          { name: "Interpretation", text: "Wisdom is not a stock of knowledge; it is a habit of seeing clearly, and especially of seeing oneself clearly. That habit is easiest to keep when one is young, uncertain and watched. Success wears it away. The wise man is praised for his wisdom until he believes he cannot be foolish. His reputation means that no one around him dares to contradict him. His wealth removes the pressure that once kept him careful. And his past successes make him trust his own judgment in fields where he has no right to. Solomon's wisdom did not disappear in a day. It was spent, one marriage of alliance, one tax, one exception at a time, by a man who was sure he could afford it. That is why this law closes the book. Every ruin in these thirty laws began with someone who believed the laws applied to other people." },
          { name: "Parallels", text: "London, 1621. Francis Bacon, philosopher, scientist and Lord Chancellor of England, the highest judge in the land, is accused by parliament of taking gifts from people with cases before him. He confesses, and is fined forty thousand pounds, banned from office and briefly held in the Tower. He writes that he was the justest judge in England for fifty years, but that it was the justest censure in parliament for two hundred years. New York, March 2021. Bill Hwang, a celebrated investor and generous giver to Christian charities, runs a private fund called Archegos. Using borrowed money from several banks, each of which does not know how much the others have lent, he builds hidden positions worth tens of billions of dollars in a handful of shares. When one of them falls, the banks demand their money, and in a few days his fortune of about twenty billion dollars disappears. The banks lose more than ten billion dollars. In 2024 he is convicted of fraud and sentenced to eighteen years in prison." },
          { name: "The Cost", text: "For Solomon: the kingdom he inherited and enlarged, split in two at his death. For his son Rehoboam: ten of the twelve tribes; and, in the fifth year of his reign, the Egyptian pharaoh Shishak marches on Jerusalem and carries off the treasures of the Temple and the palace, including the golden shields Solomon had made. Rehoboam replaces them with shields of bronze. For the people: two kingdoms that fought each other and fell, one by one, to Assyria and to Babylon. For Newton: a fortune and, it is said, a lasting dislike of hearing the South Sea mentioned. For Rome: the end of its golden age. The fall of a wise man costs more than the fall of a fool, because more people trusted him." },
          { name: "The Record", text: "Verified, as text: the account of Solomon's reign and the division of the kingdom in the first book of Kings, chapters 3 to 12, and the warning to kings in Deuteronomy 17, verses 16 and 17. Disputed: the history behind the text. No inscription from his lifetime names Solomon, and archaeologists disagree sharply about how large and rich Jerusalem was in the tenth century BC; some see the evidence of a real kingdom, others a much smaller chiefdom later remembered as an empire. Verified: Shishak, known in Egypt as Shoshenq I, recorded a campaign into Canaan on the walls of the temple at Karnak. Disputed: the size of Newton's loss and the line about the madness of people, which come from accounts written after his death. Verified: Commodus's murder on 31 December 192, recorded by Cassius Dio, who sat in the Senate at the time." },
          { name: "Keys", text: "For those seeking: first, the higher your reputation for wisdom, the more carefully you must guard the small daily choices that made it. Second, know the edge of what you know, and stay inside it. Third, keep the rules you would advise others to keep; there are no laws for other people. For those keeping: first, let someone close to you be free to tell you that you are wrong; the wise fall when no one dares. Second, success removes the pressures that made you careful; replace them with your own. Third, choose your heir's counsellors as carefully as your heir; Rehoboam lost the kingdom by listening to his friends." },
          { name: "Image", text: "A lamp that has burned brightly in the window for forty years, so famous that travellers steer by it. No one remembers to trim the wick or fill the oil, because it has always burned. One night it flickers, and the ships on the rocks below never knew it was going out." },
          { name: "Authority", text: "\"Pride goeth before destruction, and an haughty spirit before a fall.\" Proverbs, chapter 16, verse 18, a book the tradition gives to Solomon himself. And from the apostle Paul, 1 Corinthians, chapter 10, verse 12: wherefore let him that thinketh he standeth take heed lest he fall." },
          { name: "Reversal", text: "Jerusalem, after the fall. Jewish and Christian tradition has long held that in his old age, after his wisdom had failed him, Solomon wrote the book of Ecclesiastes. It begins, Vanity of vanities, all is vanity, and it reads like the confession of a man who had tried everything that power and wealth could buy, and found it empty. Whoever wrote it, it has been read for more than two thousand years as the wisdom that comes after a fall. It ends: let us hear the conclusion of the whole matter; fear God, and keep his commandments, for this is the whole duty of man. That is the reversal, and the reason this book exists. A fall is not always the end of the story. If someone has the honesty to write down what they learned, a ruin can become a warning, and a warning can save someone else. Every law in this book is written for that purpose." },
        ],
      },
    ],
  },
];
